/* 平成19年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h19.committeeSessions.push(...[{"id":"h19-20070314-3","meetingId":"h19-c-budget","date":"2007年3月14日","dateIso":"2007-03-14","committee":"予算特別委員会","time":"午前１０時０４分～午後５時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を150件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１９年度品川区一般会計予算","agenda":"平成１９年度品川区一般会計予算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、教育総務費の中で、２９７ページ、プラン２１関連事業関係、３２１ページ、生涯学習費の中から、歴史館の関係で質問させていただきたいと思います。その寄贈された資料がどう生かされているのか。事情がいろいろあったと思います。私もその場に立ち会ったわけじゃないので、状況の細かいことはわからないんですけど、資料の開示をどういうふうに考えているかということを教えてください。","respondent":"古里学務課長、富田生涯学習課長","answer":"第二日野小学校で、現在入れなかったというか、最終的に待ち状態のまま終わってしまった方が約６０名程度、原小学校のほうで２０名程度というふうに考えてあります。その場ですぐレファレンスに応ずることができる場合もあれば、対応できる職員等々の状況により、後日改めてということもあろうかと思いますが、今後そのようなことのないように徹底してまいりたいと思います。","voiceIndex":4,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"歴史館のほうは、いろいろな事情があったと思います。学校のほうですけれども、６０人入れなかったという数なんですけれども、これも、例えば第二日野小学校に入れたとして、その下にお子さんがいらっしゃいますよね。その方も入りたいという希望を持ったときに、どういうふうに考えていったらいいのかなと。その辺どうお考えかなと。","respondent":"古里学務課長","answer":"そうしたリスクを負いながらも、希望する学校を選ぶということから、品川区における兄弟枠の扱いについて、今年度も校長先生方に集まっていただいて、検討いたしましたけれども、やはり従来どおり、品川区の方式を継続するということで考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ、やはりその辺、実際に親御さんからのそういう声もあるということを再度頭に入れておいていただきたいと思います。例えば小学校から中学校に行こうとしても、片道１５分以上かかるような地域もあると思います。その辺の連携校に対する支援、既にやっていらっしゃるんでしょうけれども、これからどういうふうに考えていかなきゃいけないのかなという点でお答えをいただきたいと思います。","respondent":"吉村小中一貫教育担当課長","answer":"特に直接交流については、教員の問題が１つ課題として出てまいりますので、連携における教員の補助といいますか、正規教員に加えまして、連携校に非常勤の教員を配置して、その連携を少しでも補助する。スムーズにできるようにする。そういったことを今現在進めているところです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それともう一つ、例えば連携、中学校のグループの中で、今度小学校同士の交流というのもある面必要じゃないかなと思うんですね。そこに他の学校から来る人もいますけど、基本的にはその中で進んでいく子が多いという中で、１つの中学校のグループの中で、そこに小学校が３つか４つついていたら、そこの交流というのはどういうふうに考えていくのかなというのを教えてください。","respondent":"吉村小中一貫教育担当課長","answer":"それからもう一つ、子どもの面でいいますと、例えば遠足であるとか、市民科の中のスチューデント・シティであるとか、宿泊行事であるとか、そういった部分について、連携校はできるだけ一緒にやっていくというスタンスで、１年目を終えて、２年目に向けて、今、準備をしています。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"意見","question":"例えば運動をやっていて、野球とかサッカーとかをやって、地域のチームに入って交流があれば、顔を知っているお子さんもいっぱいいらっしゃると思うんですけれども、あと、地域ごとの地区委員会活動とかで会うかもしれないけど、やっぱり接触は非常に少ない部分があると思うので、子ども同士の交流という面でも、これからもまたその辺もよくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"私は、２９７ページのプラン２１関連事業に関連して質問したいと思います。こういった方向に果たして品川区がこれから突き進んでいくのがいいことなのかどうかというのは、今ここでしっかりと議論していくことが必要だと思います。改めて、品川の教育改革の目的、プラン２１の目的についてお尋ねしたいんですが。","respondent":"河野指導課長","answer":"プラン２１の目的ですが、プラン２１は、子どもたち、あるいは保護者の期待にこたえる公立学校づくりということが一番大きな目的です。","voiceIndex":15,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと淡白な答弁だと思うんですけれども、期待の内容というのがよくわからないんですけれども。子どもの姿が全然見えてこない。本来ならば、教育というのは、子どもの実態、子どもは学びの主人公のはずですから、その目的の中に、子どもをどうするのかという目的が入っていないというのは絶対おかしいと思いますので、もう少し丁寧な答弁をお願いしたいと思います。","respondent":"河野指導課長","answer":"例えば指導助手をほかの学校よりも時間数を増やして配置するとか、あるいは、さまざまな教材関係の購入の支援であるとか、そういうような形をして、それぞれの学校が当初、目標としている成果が達成できるように、教育委員会としても支援をしています。","voiceIndex":17,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"品川なんですけれども、すべての子どもたちに学ぶ権利を保障するということをどのように行っているのかということをお伺いしたいです。この冊子を読ませていただいたんですが、習熟度別と少人数指導ということで行っていると書いているんですけれども、習熟度別授業を取り入れている理由と、何を根拠にしているのかということをお伺いしたい。","respondent":"吉村小中一貫教育担当課長","answer":"５時間でわかったしまった子と５時間たってもまだ理解できない子の個人差がある。その個人差を、７時間終わった段階で一定のテストのようなものをやって、まだ十分に理解していない子に対して、幾つかのグループに分けて、どの子にも最低限の基礎基本を身につけさせよう。","voiceIndex":19,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"間違っていたら指摘していただきたいんですけど。そこで、４年生の担任で、現役で品川区で先生をやっている方の話を伺う機会がありまして、習熟度別クラスには、１人先生を加配するということをお伺いしたんですが、加配教師にはだれを充てているのか。加配の状況を教えていただきたいんですよ。常勤か、非常勤か、状況などを教えていただきたいのと、それとあわせて、先生の話ですと、加配がされていると。","respondent":"吉村小中一貫教育担当課長","answer":"１点目の加配教員のことについてですけれども、例えば小学校で言えば、すべての学校に加配の正規の教員が入っております。プラス、品川の場合には、再三ご説明しておりますが、指導助手という形で、教員免許を持っている人間を配置している。","voiceIndex":21,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"もう一度お伺いしたいんですが、先ほど紹介したような実態というのはご存じでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"あくまでも自分として最低限の基礎基本を身につけていくんだと。そういう部分をきちんと指導しましょうということをこの７年間やってきておりますので、今現在、例えば今年、学校側からそういう声が上がってきたということは、我々は把握しておりません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"現役の教師の方からも聞いた声なので、７年間かけて、そういった配慮をしている、指導しているということかもしれないんですが、ぜひこういった声にも謙虚に耳を傾けていただいて改善、ただ単なる改善という問題じゃないと思います。習熟度別によってクラスを編成するのではなくて、そういうことをやめた上での少人数の学び合いの教育スタイルをとるべきではないかと思うんですが、いかがでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"そういった実態がありますので、さまざまな学習形態についてはご意見はあろうかと思いますが、品川区の現実の子どもたち、保護者の声を聞きつつ、今現在はこの習熟度別学習を変えていくという気持ちは全くございません。","voiceIndex":25,"id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"学力テストという話がありましたが、現在、品川では４年生と７年生で学力テストをやっています。５年生と８年生では東京都で学力テストがあります。６年生と９年生では、国の学力テストがあります。確かな学力というのは、習熟度別によってついたのかどうかというのを検証したいわけですが、東京でやっていたり、国でやっているやつの品川区の学力テストの結果の推移はどうなっているんでしょうか。","respondent":"河野指導課長","answer":"平成１５年４月から昨年２月まで４回のテストをやっておりますが、国語、算数ともに、平成１５年度が、国語７３.５％に対して、平成１８年度の学力調査においては、８３.７％というような到達度の向上を示しております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"武内委員","kind":"質問・要望","question":"２９７ページの小中一貫教育の推進と、同じページのすまいるスクール運営費、３１９ページの品川版総合型スポーツクラブの設置の３点についてお伺いします。最初の小中一貫教育の推進のほうですけれども、先ほど鈴木真澄委員からも、質疑の中で、今回第二日野小学校が６０名、原小学校が約２０名と、残念ながら希望に沿えなかった方がいるというお話を伺ったんですが、定員が何名だったのか。","respondent":"古里学務課長","answer":"第二日野小学校、原小学校とも、３クラスです。３クラスの定員そのものは、１２０名ですけれども、将来の転校枠を考えて、１００名まで受け入れをしています。それぞれ１１０名程度、１０７名程度というふうに、最終的な数ですが、その程度でということで聞いてあります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"その１０名、７名、１００名受け入れに対して増えたのは、いわゆる転入ということでよろしいんですか。","respondent":"古里学務課長","answer":"抽選を行う時点での定数以外に、転居によって入ってこられる方がいらっしゃいました。その方によって、定員の１００名より超えた受け入れの数になっているというものです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"非常に残念なことがあったわけですね。ちゃんとアパートまで借りて、引っ越して、学区内に住所を移して入ってくる。そこまで過熱しているということをお聞きしまして、そういった中で、今、不動産も、「日野学園とか伊藤学園の学区内ですよ」、そんな看板を出すぐらい白熱しちゃっているということをお聞きしているんですけれども、その辺の状況はどのように認識されていますでしょうか。","respondent":"古里学務課長","answer":"私どもとしては、一体型小中一貫校をできるだけ各地区に速やかに展開するということで、小中一貫校６校構想を立ち上げてあります。私どもとしては、全力を挙げて、その実現方、努めたいと考えています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"今回、小学校５校、中学校６校で抽選があったということなので、必ずしも日野と原の小中の施設一体型のところだけということではないとは思うんですけれども、実際にこの２つの小学校に入れなかったということで、この人気の原因はどのように考えていらっしゃるんでしょうか。","respondent":"古里学務課長","answer":"それ以外にも、学校の特色をきちんと見て、その中で選択された結果だと考えています。そういう意味では、選択制そのものの権利を皆さんが行使なさっているということの結果かと思います。","voiceIndex":36,"id":"exchange-016"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、すまいるスクールの運営費のほうで、これもお聞きしたいんですけれども、これも私が聞いたお声で、すまいるスクールが始まって大分たつんですけれども、学校の体育館をすまいるスクールで使われることもあると思うんですけど、その中で、全部の学校じゃないと思うんですけれども、例えば今までバレーボールとか一輪車とか、いろんなチームで体育館を使っていた方が。","respondent":"富田生涯学習課長","answer":"すまいるスクールの夕方の部分の利用だと思いますけれども、その点につきましては、少年少女のスポーツ団体が夕方利用していますので、そこの部分とすまいるスクールでの利用調整ということで、これは個別の学校の状況により、学校の校長先生。","voiceIndex":38,"id":"exchange-017"},{"speaker":"武内委員","kind":"提案","question":"最後に３１９ページの品川版総合型スポーツクラブの設置ということで、これは一番近いところで言いますと、昨年の第１回定例会で、うちの藤田議員が、また古いところで言いますと、平成１４年の第２回定例会で先輩議員が、平成１５年の決算特別委員会では、亡くなった嶋議員が、また私も平成１６年の第２回定例会で、総合型地域、これは地域が入っていませんけれども。","respondent":"富田生涯学習課長","answer":"委員ご指摘のように、総合型地域スポーツクラブ、文科省の主導で行っているものですが、会員制で、多種目、多世代、多レベルで行っていくということで、東京都でも、国体実施の２０１３年までには各区市町村に１つはということで言われているところです。","voiceIndex":40,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、拠点は日野学園の体育館とか総合体育館とか、そういうところを使われるのかということと、あと、自主運営でやられるということなので、その辺、スポレクを中心とした新たな組織、運営協議会みたいなものをつくるのか、その辺も教えてください。","respondent":"富田生涯学習課長","answer":"このことにつきましては、体育指導委員会内部でも検討組織を設け、検討を重ねてきているところであり、１７とまではいきませんけれども、大きく分けたブロック単位ぐらいに拡大していければいいかなと考えているところです。","voiceIndex":42,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"今、ブロックごとにというお話があったんですけれども、最終的には文部科学省のほうも各中学校区に１つ、こういった総合型のスポーツクラブを設置していきたいという目標があるみたいなんですね。今そのお話なのかなと思ったんですけれども、その辺のところと、あと先ほどお伺いした、自主的な運営主体の考え方を教えてください。","respondent":"富田生涯学習課長","answer":"具体的にはスポレクを中心としながら、区民の皆様方の実行委員会のような、そうした組織になっていこうかと思いますが、これはまた今後検討してまいりたいと考えています。","voiceIndex":44,"id":"exchange-020"},{"speaker":"武内委員","kind":"質問・要望","question":"いろんなことで難しい部分もあると思いますけれども、非常に期待していますので、多世代の方、高齢者、お年寄りから小さい方まで、地域でスポーツに親しんで、そこでまたコミュニケーションも図れる、そういう取り組みの趣旨があると思いますので、ぜひ期待をしておりますので、頑張っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-021"},{"speaker":"阿部委員","kind":"質問","question":"私からは、２９５ページ、独自採用教員について、２９９ページ、特別支援教育体制について、３０３ページのプラン２１、３２１ページの文化センター建設費についてお伺いしたいと思います。それは原案をつくった上で、要は議会としては、そこにどこまで関与できるのか。そのスケジュールと、議会としてどこまで内容に関与できるのかということを教えてください。","respondent":"河野指導課長","answer":"教員の独自採用の今後の予定ですが、詳細について、まだまだ詰めなければならないこと、それから、都、あるいは他区との調整の部分もありますので、そのような採用の中身については、平成１９年度中に検討して、要綱を定め、平成２０年度に採用選考。","voiceIndex":48,"id":"exchange-022"},{"speaker":"阿部委員","kind":"質問・要望","question":"自主的にそういったことが言っていけないというのであれば、この場で、要望を兼ねてなんですけれども、言わせていただきます。ですから、そういった経験を持った方、また採用後も交流人事ですとか、都全体への研修の参加など、マクロで見られる先生を育てていく環境、あるいはそういった資質を持った方ということが必要ではないかと思いますが、事務局のお考えを教えてください。","respondent":"河野指導課長","answer":"したがいまして、身分が区の独自採用であったとしても、管理職になる場合には、管理職選考を受けて、合格した後、県費負担教職員という立場で任用になりますので、そういうようなことも含めて、今後さらに検討してまいりたいと考えております。","voiceIndex":50,"id":"exchange-023"},{"speaker":"阿部委員","kind":"質問","question":"特別支援教育体制についてお伺いしたいのですが、聞きたいことが山のようにあるんですけど、終わらなくなっちゃいますので、１点だけ。個別指導計画なんですけれども、個別指導計画については、いつからどのぐらいの規模での作成を考えていらっしゃるのか、小中学校の普通学級などでの作成も平成１９年度から始められるというイメージでよろしいのでしょうか。","respondent":"河野指導課長","answer":"個別指導計画ですが、現在既に心障学級等では、個別指導計画を作成しております。作成に当たっては、通常学級においても今後作成を支援するということで、スクールカウンセラー等も活用して、あるいは、保護者の要望も受けとめながら、具体的に作成していく予定です。","voiceIndex":52,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問","question":"特別支援教育で、もう一つ忘れていました。就学前から修了までの一貫した支援ということを考えましても、あるいは小中一貫という考え方からいっても、今の日野中学校部分に心障学級があるということで、第二日野小学校部分にも心障学級があるのが理屈の上ではすっきりするのではないかなと思うんですけれども、その辺いかがお考えでしょうか。","respondent":"河野指導課長","answer":"第二日野小学校の部分にというご指摘ですが、日野学園のほうは、特別支援教育の先取りという形で、特に心障学級を小学校のほうに設置しないで、支援の必要のあるお子さんに対して必要な支援をしていくということで現在取り組んでいるところです。","voiceIndex":54,"id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"よろしいようですね。この疑問が１点。そういったことで、学区の見直し、エリア的な見直しですとか、あるいは、対象となる子どもの数ですとか、そういったことも、平成１９年度からというわけにはいかないかもしれませんけれども、ある程度見直して調整していく必要があるのではないかと思うんですけれども、これは学校規模の適正化の話と絡めて行っていくようなお考えはあるのでしょうか。","respondent":"林（宏）委員長、古里学務課長","answer":"平塚学園じゃないですよね。平塚中学校と平塚小学校の一貫校ということですよね。平塚学園というのはまだありませんから。これを簡単にいじるというのは、算数で１＋１が２になるということではなくて、地域の財産としての学校ということもあります。地域の方々とよく協議をしながら、学区域の問題については検討してまいりたいと考えています。","voiceIndex":56,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"もちろん社会教育施設ですから、教材としての使い方もあると思いますが、それも、五反田文化センターまで区内全部の学校から行くよりも、今は移動式の星空投影機というのも、非常に高品質なものが出ていて、それを各学校に配置して教材として使ったほうがよほど感動的な授業ができるのではないかと考えています。そういうような考えを持っておりますが、いかがでしょうか。見直しの可能性。","respondent":"富田生涯学習課長","answer":"４０人定員ですので、今の５,０００人弱の利用でありますけれども、１学級単位しか利用できないということもあります。こういったことを含めまして、学校の子どもたちにもぜひ見てもらいたい。","voiceIndex":59,"id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは、２９５ページ、生活指導対策費のクラブ活動指導対策費についてお尋ねさせていただきたいと思います。確認なんですけれども、クラブ活動指導対策費というのは、外部指導員の報酬ということでよろしいのでしょうか。","respondent":"古里学務課長","answer":"外部講師の費用として予算計上しています。","voiceIndex":63,"id":"exchange-028"},{"speaker":"山内委員","kind":"質問・要望","question":"１つが、授業をしなくてはならない。そして、生活指導、いじめ等、いろいろ問題がある。正直言って、私が今申し上げた３つは何としてもクリアしなきゃならない部分かとは思うんですけれども、クラブ活動ということになると、どうしても手薄になってしまう。そんな中、特色のあるクラブ活動、部活動というものをしていかなくてはならないのではないかと思って、本日質問させていただきたいなと思いました。","respondent":"河野指導課長、古里学務課長","answer":"そのように教員が指導ができないとか、あるいは顧問が不在になってしまって、活動ができなくなるということを予防するために、まず外部指導員、できれば、さらにすぐれた技術。委員が先ほど言われました費目につきましては、学校での指導の問題でやってあります。外部指導員の招聘費用については、予算書３００ページの下から９行目、これが私が先ほど申し上げた経費です。訂正させていただきたいと思います。","voiceIndex":65,"id":"exchange-029"},{"speaker":"山内委員","kind":"質問・要望","question":"じゃあ、どうするのと。そういう話になってくるんじゃないかと思うので、生徒を集めるという形では、まず最初に指導員に魅力のある指導をしていただけるということが大事なのではないかと思うんですけれども、その辺をもう少し、品川区としても、外部指導員という部分の意味で考えていただきたいなと思うんですけれども、これはまだ同じお答えになっちゃうかもしれないんですが、すいません。","respondent":"河野指導課長","answer":"これからも、できるだけ大勢の子どもが、自分がやりたい活動ができるように、私どもといたしましても支援してまいりたいと考えているところです。","voiceIndex":68,"id":"exchange-030"},{"speaker":"山内委員","kind":"質問・要望","question":"外部指導員を積極的に受け入れる体制を要望いたしまして、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"２９７ページのプラン２１関連事業のうちで、まちの人々に学ぶ授業についてお伺いします。この授業の目的と授業内容と対象年齢を教えてください。","respondent":"河野指導課長","answer":"まちの人々に学ぶという取り組みですが、これは、一般的に言われている中身でいいますと、地域の人たちに学校に入っていただいて、それぞれさまざまなご自身の体験であるとか、仕事であるとか、そういうものを生かして、子どもたちに指導していただくという取り組みです。","voiceIndex":72,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"えっ、自慢、と思ったんですね。給料はいいですよ。もし自分が若いときに帰れたら、こういう選択もあったんじゃないか」という、人生を教えるという形にもなっていくと思うんですけれども、どうかこの事業にそういうことが反映できないかということが１点。よく企画部のほうで、団塊の世代に地域を担っていただくということが出ますが、そこら辺については、お考えはありますでしょうか。","respondent":"河野指導課長、日下部企画財政課長","answer":"今後とも、そういう意味も含めて、まちの人々にさらに学校の中に入っていただいて、子どもたちとの触れ合いを通して、生き方について学ぶ機会を充実させていきたいなと考えてまいりたいと思います。非常に重要なことだと思いますので、私どもとしましても、その辺は教育委員会との連携等も含めて、今後積極的に取り組んでいきたいと考えております。","voiceIndex":74,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"次当選できたら、次の質問で、「あれはどうなりましたか」と必ず質問させていただきたいと思いますので、よろしくお願いいたします。それと、今はこの事業は、学校に来ていただくという事業ですが、子どもたちが地域を担っている１つである商店街に出ていったり、いろんな現場に出ていって学ぶという形は何か考えているんでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"小学校の高学年になれば、まちの工場を見ていこうというときには、必ず現場に出ていって、現場の方に直接話を聞きながら、社会のいろいろな仕組みを考えていくということをやっておりますので、これについては今後も継続していきたいと考えています。","voiceIndex":77,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"私からは、３２１ページの五反田文化センターの改築についてお伺いをいたします。プレス発表でもありますけれども、文化センター、音楽ホールと防音設備を施した改修を行っていくということも出されていますけれども、この文化センターの改修は、音楽専用ホールをつくるという計画でよろしいのかということと、もしそうであれば、どういった利用団体を想定しているのかということをお伺いしたいと思います。","respondent":"富田生涯学習課長","answer":"きゅりあんの大ホールは大変規模が大きゅうありますので、そういう意味では、区内の音楽関係の団体の方々が発表等々できる場ということで、新たに音楽ホールを設けたいということで、設計の内容としては、音響に配慮した音楽専用のホールということで、演劇とか。","voiceIndex":81,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"プロポーザルのところに、太鼓なんかをする団体も想定をされているということも書いてあったかなと思うんですけれども、ここの音楽専用ホールというところでは、太鼓の演奏者とか、そういう発表の場というふうには考えていらっしゃいますでしょうか。","respondent":"富田生涯学習課長","answer":"区内に太鼓、特に和太鼓等を含めた防音設備のある施設が全くございませんので、そういう意味では、太鼓、和太鼓の防音を含めた仕様の施設にしていきたいと考えています。","voiceIndex":83,"id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"そういったところを想定しているということは、文化センターの改修において、遮音というか、複合施設でもあるわけですから、結果的に学校に音が漏れたりとか、教育センターのほうに漏れたりということは、せっかくつくったものが困難だというふうに思うんですけれども、そういう和太鼓なんかの低周波の音響によると、一番最初の計画段階でその処置をしないと。","respondent":"富田生涯学習課長","answer":"そういったことも含めてプロポーザルを行って、設計していきたいと思いますけれども、結果として、ないとは思いますけれども、遮音ができるかということについては、できる限り努力をしてまいりたいと思っています。","voiceIndex":85,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"そういう意味では、今のプロポーザルの中に、音響とか遮音とか、きっちりと専門的な知識を持った人が入ることが一番だと思うんですけれども、その辺についてのプロポーザルに対するお考えはいかがでしょうか。","respondent":"富田生涯学習課長","answer":"プロポーザルに当たりまして、音響の専門家を入れることを条件として、そういった防音を徹底することを条件としてやっております。","voiceIndex":87,"id":"exchange-038"},{"speaker":"井上委員","kind":"質問・要望","question":"今回も、単独でつくるよりは、学校にどういう影響があるかとか、使用勝手も、９時とか、時間的な制約も出てくると思いますので、その辺のリスクも含めて、ぜひ当事者の声を聞く場を設けてほしいと思いますけれども、実際にどういうところで声を拾っていこうと考えていらっしゃるんでしょうか。","respondent":"富田生涯学習課長","answer":"五反田文化センターにも利用者協議会がありますので、そういったところを中心に意見を聞いていく予定にしております。","voiceIndex":89,"id":"exchange-039"},{"speaker":"井上委員","kind":"質問","question":"改修の時期的なものなんですけれども、今実際に文化センターで活動されている方たちが、改修に当たって、行き場所がなくなってしまう。いろいろな建て替えでも同じようなことがあるんですけれども、そういった場合に、教育センターのほうが改修がずれたりした場合には、代替えみたいな利用は考えていらっしゃるんでしょうか。","respondent":"富田生涯学習課長","answer":"工事のスケジュールというのは、これから決まってくるものであろうと思いますが、教育総合会館のほうの工事が始まるまでの間ということでは、ぜひ教育センター部分の活用等を含めて、検討してまいりたいと考えています。","voiceIndex":91,"id":"exchange-040"},{"speaker":"井上委員","kind":"質問・要望","question":"それがこういう予算の場にぽんと出てくるということではなく、単独でつくられるのを複合施設にして、どういうコスト変化が見込まれてきて、そういう決定をされたのかとか、その辺の比較検討について少しお話を伺いたいと思います。","respondent":"市川庶務課長","answer":"ご案内のとおり、第一日野小学校の改築については、平成１８年度の基本設計ということで、予算計上させていただいておりました。これまで何回か説明していますけれども、この同じ年度に、隣接しております五反田文化センターと教育総合会館の耐震診断を実施いたしました。","voiceIndex":93,"id":"exchange-041"},{"speaker":"本多委員","kind":"質問","question":"２９５ページの区教員採用事務費、２９５ページのＣＡＰ事業、３０８ページの学校施設建設費と学校管理費に関連して、樹木についてお聞きしたいと思います。最初に、区教員採用事務なんですが、区独自ということで、平成１９年度に採用準備、平成２０年度に採用選考、平成２１年度から採用ということなんですけれども、それまでの事務を進めていく中で、人事委員会とのかかわりがどうなるのか。","respondent":"河野指導課長","answer":"今、幼稚園教諭に関しましては、特別区人事・厚生事務組合の中で採用選考を実施している経緯がありますが、独自採用教員につきましては、品川区独自ですので、最終的には、人事委員会とも協議はいたしますが、採用そのものは品川区として進めていきたいと考えております。","voiceIndex":96,"id":"exchange-042"},{"speaker":"本多委員","kind":"質問・要望","question":"協議していくということなんですけれども、特に脱会とかはもちろんしないで、進めるということだと思うんですけれども、その辺、教えていただきたいのと、あと、プレス発表に、「採用については、教員および講師などを数年経験した者」となっているんですけれども、その辺について、採用する枠の理想像を教えてください。","respondent":"河野指導課長","answer":"そういうようなことをできるだけ予防するために、ある程度経験や実績を積んだ方を私どもとしてはぜひ採用したいと考えているところです。","voiceIndex":98,"id":"exchange-043"},{"speaker":"本多委員","kind":"質問","question":"小中一貫校を進めていて、いろんな教育改革をしていて、その学校学校の独自性もあると思いますので、校長、副校長が同時に異動というのは避けたほうがいいんじゃないかと思うんですけど、その辺を教えてください。","respondent":"河野指導課長","answer":"人事異動に絡んで、それぞれの学校の管理職、校長、副校長になるわけですが、同時に異動するということにつきましては、私どももできる限り避ける方向で検討しております。","voiceIndex":100,"id":"exchange-044"},{"speaker":"本多委員","kind":"質問","question":"わかりました。次の２９５ページのＣＡＰ事業について聞きます。メニューがずっと同じで進められているのか。２年生が実施されていたと思うんですが、毎年新しい２年生がやるわけですから、メニューが同じでもいいのかもしれないんですけれども、かなり浸透されていて、少しメニューが変わったほうがいいんじゃないかという角度もあると思いますので、その辺を教えてください。","respondent":"河野指導課長","answer":"ＣＡＰですが、今、実施している学年は小学校３年生と５年生です。","voiceIndex":102,"id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"工夫をして、さらに進めていただきたいと思います。３０８ページの学校施設建設費ですとか、学校管理費に関連して、学校整備に当たって樹木を整える計画みたいなものを教えてください。","respondent":"市川庶務課長","answer":"改築校、新規の小中一貫校については、外溝工事の中で、周辺環境にマッチした樹木の植栽を行っていく。こういうことでそれぞれ計画をし、実施をしてきてあります。既存校の樹木につきましても、現状の維持ということで、植栽の管理に当たってきてあります。","voiceIndex":104,"id":"exchange-046"},{"speaker":"本多委員","kind":"質問","question":"桜のことでお聞きしたいんですけれども、日本の桜というのは、主に９種類ぐらいあるそうなんですけれども、世界に行くともっと種類が多いらしいんですが、通常、卒業式ですとか入学式に桜が満開だと美しい感じですけれども、最近暖冬ということで、開花が早いです。","respondent":"市川庶務課長","answer":"そういったことも考えあわせて、今、ご指摘のあった点、今後検討させていただければと思います。","voiceIndex":106,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、荏原西地区の小中一貫校についてお聞きしたいと思います。この説明会では、ほとんどの保護者が、突然の統合に寝耳に水という形で、驚いて、平成２０年度の統合はやめてほしいという意見がほとんどだったと思います。この説明会の中でも、保護者の方からは、区は地域からの要望で統合すると言うだけだけれども、その地域にＰＴＡは入っていない。いつ、どこで、だれの要望で出てきたのか教えてほしい。","respondent":"古里学務課長、河野指導課長","answer":"なぜ突然の決定かですけれども、私ども、今年度、荏原西地区一貫校の建設に際して、建設前、周辺の皆さんにご説明を申し上げる機会を持たせていただきました。平中のほうが、現在のところ、３学級に対して、教員の定数のほうが、同じく９名、加配が２名です。","voiceIndex":110,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"驚くぐらいだから、自分たちから平中と二中を統合してほしいなんていう要望を出すはずがありませんよというふうに町会長たちは言っていました。一体どこの地域から出されたのか、本当に要望というのが出されたのかということを改めてお聞きしたいと思います。ということでは、町会で平成２０年度統合というのは、求めていないのではないかと思うんですけれども、改めてこのことについてお聞かせください。","respondent":"古里学務課長","answer":"こうした判断を教育委員会でした上で、この決定をいたしたものです。それから、近隣の中学校との共生ですが、今申し上げた点も踏まえて、私どもとしては、荏原西地区全体の中学校の教育環境を考えて、決定をしたものです。","voiceIndex":113,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ということは、何も今、１カ月半前に至って、突然出てくるという理由が全く明確になっていないと思うんですね。５０年先を考えているのであれば、なぜ一、二年が待てないのか。棚上げにして、再度提案するのが教育ではないのか」。「選択制の中で３年間は保証してほしい。自然な流れでやっていってほしい。２校存在もあり得ると検討してほしい」。二中がよくて選んだのに、性急に進めないでほしい」。","respondent":"古里学務課長","answer":"扱っているのは、子どもであって、人間であって、物ではないですが、私ども、生徒という人格、あるいはこれからの成長過程にある人間ということを考えて、こうした発表をし、その後、生徒のケア、それから、両校の統合ということを真摯に事務を進めていく。","voiceIndex":115,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"おわびをするしかないということで繰り返し言われていますけれども、そういうことであれば、私は改めて、これを延期する、平成２０年統合はとりやめるということで検討すべきだと思うんですね。平成２０年度、荏原二中、平中の統合はやめてほしいという声です。この点で、大半が反対という意思表示になれば、計画変更もあり得るということで考えてもいいでしょうか。","respondent":"長田教育次長、河野指導課長","answer":"荏原二中のほうの教育環境がどうなるのか。場合によると、希望がなくなって、廃校になる可能性もあるということの中で、今回の対応をしてきたわけです。そういった意味で、反対があるのは理解をしています。その影響に対して、最少限度にとどめるのが私たちの努めです。そういう発言をしています。","voiceIndex":117,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これをみずから壊しているという、このことに対してどう思うのかを改めて問いたいと思うんですが、時間がなくなっちゃったので、問うことができないんですけれども、今の１年生は、二中も平中も一緒にならないということで選んでいるんです。改めて、平成２０年統合はやめるべき、平成２２年３月までは荏原二中、平中を存続させるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":120,"id":"exchange-052"},{"speaker":"若林委員","kind":"提案","question":"２９９ページの特別支援教育、２９７ページのプラン２１に関連いたしまして、質問をします。特別支援教育がいよいよ平成１９年４月から本格スタートになります。これまで私も一般質問、また予算特別委員会の場でもさまざまなご提案を含めまして、質問等させていただきました。","respondent":"河野指導課長","answer":"本区では、平成１６年度より特別支援教育検討委員会を立ち上げて、品川区としての特別支援教育のあり方について、モデル的な取り組みを含め、今年度まで検討を進めてきたところです。","voiceIndex":122,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、予算のほうなんですが、金額のほう、心障学級経費として、ずっと経年で計上されておりまして、比較をさせていただきたいんですが、昨年度の予算では、予算書によりますと、小学校が８,４００万円余、中学校が２,９００万円余、合計で１億１,４００万円余。この金額がちょっと下がった理由について、検討委員会の中で内容について変化があったのかどうか、ご答弁をお願いいたします。","respondent":"河野指導課長","answer":"心障学級経費の減額の分ですが、１つは、報酬基準の見直しによる医療相談員関係の単価が下がったという点、それから、専門家チームによる特別支援教育関係で、品目を心障学級経費から特別支援教育費のほうへ一部移行したことに伴う減額でございまして。","voiceIndex":124,"id":"exchange-054"},{"speaker":"若林委員","kind":"質問・要望","question":"「増額になっているかと思いますが」というご答弁ですが、予算ですので、そこははっきりさせていただきたいと思います。今回、特別支援教育経費として２９９ページに載っているのは、１億３,６００万円余です。それと、言葉尻をとらえるようで申しわけないんですが、今のご答弁の「思います」という部分のお答えをお願いしたいと思います。","respondent":"河野指導課長","answer":"そちらのほうが１,９７０万ほど新たに予算措置をさせていただいておりまして、そちらのほうで専門家チームによる巡回相談でありますとか、そういう経費を賄う予定です。それから、これらの経費に関する予算ですが、これは全部区の負担です。","voiceIndex":126,"id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"国、都のお金が来ない中で、区の一般財源の中でやられているということで、今後ともぜひ力強い前進をお願いしたい。私も質問の中では、小中一貫教育を活用したといいますか、特性を生かした特別支援教育の実現をということで問いかけもしておりますけれども、小中一貫特別支援教育がスタートになりますので、改めてこれの意味を一言お願いいたします。","respondent":"河野指導課長","answer":"こちらのほう、プレス発表の中で、新たに小中一貫特別支援教育というふうに銘打たせていただいたのは、従来、特別支援教育ばかりが個別的な支援のほうに重きを置かれているかのような印象を多くの区民の皆様が抱いていらっしゃると思うんですが、私どもとしては。","voiceIndex":128,"id":"exchange-056"},{"speaker":"若林委員","kind":"質問","question":"私が最後に言いたかったことを課長から言っていただきました。その方向でしっかりと取り組みをお願いしたいと思います。それから、これは１点、端的に、プラン２１の中で、まちの人々に学ぶ授業、また市民科にかかると思うんですが、学校外部からの講師を呼んで授業を行うことがあります。この講師の方々への謝礼ということなんですが、これは今どういうふうにされておりますでしょうか。","respondent":"河野指導課長","answer":"それぞれご協力いただいた皆さんには、区の商品券、１回につき３,０００円ずつお礼ということで差し上げております。","voiceIndex":130,"id":"exchange-057"},{"speaker":"若林委員","kind":"質問","question":"これは来週ケーブルテレビで放映されるそうなんですが。このような区外からわざわざ呼んでお越しいただく。これは当然スタートとしてはボランティアで結構ですよということなんですが、今後こういった有意義な特別授業を行う場合には、当然それなりの予算づけ、謝礼という部分で、力強いご支援を賜りたいと思うんですが、教育委員会のお考えをお聞きしたいと思います。","respondent":"河野指導課長","answer":"今、委員からご指摘のありましたような、特に著名な方ですとか、専門家をお招きする場合には、通常の区の商品券による謝礼とは別に、それぞれの基準に照らしたお礼をお支払いできるように予算措置をして、それぞれの学校が取り組んでいるところです。","voiceIndex":132,"id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"決まった予算書の中のどこに当てはまるかわかりませんけれども、外部の著名な方をお呼びした場合には、既に平成１９年度の予算が決まっていて、それが各学校に配分をされて、その中で学校が工夫するという理解でいいんですね。そういうことですので、どれぐらいの謝礼が要るか、何万円という金額は言いませんけれども、もし学校からの要請があれば、柔軟な対応がお願いできるかどうか、一言お願いいたします。","respondent":"河野指導課長","answer":"学校からの要望に応じて、私どものほうもできる限り柔軟に対応してまいりたいと考えています。","voiceIndex":134,"id":"exchange-059"},{"speaker":"原（浩）委員","kind":"確認","question":"私のほうからは、３１１ページ、学校改築推進経費、特に第一日野小学校、および３２１ページ、文化センター関係、午前中にも他の委員からもお話があったので、そこをもう少しお伺いしていきたいと思います。初めのほうに関しては、私、一般質問でもしたんですけれども、複合化ということなんですけれども、もう１回確認させてください。","respondent":"市川庶務課長","answer":"もととなる第一日野小学校の改築に合わせまして、旧日野中跡地の敷地に隣接いたします現在の五反田文化センター、教育総合会館、これらの敷地の上に１つの建物を建てることによって、さまざまな建築規制に対して、効率的な床の確保ができる。こういった意味での複合化です。","voiceIndex":137,"id":"exchange-060"},{"speaker":"原（浩）委員","kind":"質問・要望","question":"聞いているほうも、答弁されている方も、その結果どっちがよかったのかなというのは、お互いに先の、この世ではわからないところもあるのかと思うんですけれども、ですから、複合化ということを前提といたしまして、これから質問します。その辺のところがあるものですから、それをご検討いただきたいということ。その施設関係の中に調理講習室というのがありますよね。","respondent":"富田生涯学習課長、市川庶務課長","answer":"調理講習室のご指摘につきましては、きゅりあん、荏原文化センター、いずれも５割ということで、五反田文化センターはもっとかなり低い数字になっておりますので、その辺については、学校との活用ができないか等を含めて。ただ、あのプールを活用して、お尋ねにございました、例えば温水化とか、そういうことを行うというのは、母体となる教育総合会館の耐震補強との関係で検討すべき課題ということで、現在のところ認識しています。","voiceIndex":139,"id":"exchange-061"},{"speaker":"原（浩）委員","kind":"質問","question":"ですから、そこのところを、もう１回耐震構造の関係で、構造設計のところにもかかわってくると思いますので、その辺のところをひとつよろしくお願い申し上げます。","respondent":"富田生涯学習課長","answer":"五反田文化センターの運営方法ですけれども、文化センター、既に受付等、委託をしています。こういったことを含めまして、学校施設の地域開放部分の受付等々含めまして、運営方法については、今後、新設設計と同時並行で検討を進めてまいりたいと思っているところです。","voiceIndex":142,"id":"exchange-062"},{"speaker":"原（浩）委員","kind":"意見","question":"一番初めに申し上げたように、立地条件があまりいい場所ではないので、その辺のところを含めまして、今後もまたいろいろと、集客という意味合いも、あと地域の活性化という意味合いも含めまして、よろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":144,"id":"exchange-063"},{"speaker":"須貝委員","kind":"質問・要望","question":"荏原西地区一貫校構成母体校への荏原第二中学校の追加についてということで、先ほどもほかの委員からお話もありましたが、地域の要望もあり、荏原二中を統合するという話でしたが、私の調査では、先ほどもありましたので、繰り返しますが、事前に、近隣町会の町会長には残念ながら話していなかったと。２月に教育委員会での公表後に町会長会議の際にお話をした。その３点について確認をさせてください。","respondent":"古里学務課長","answer":"先ほどもご説明申し上げましたけれども、具体的に町会長の皆さんにこの件でご相談を申し上げたという経過はございません。","voiceIndex":146,"id":"exchange-064"},{"speaker":"須貝委員","kind":"質問","question":"これは実際あるのかどうかわかりませんが、４月に入学するために制服を頼んだ人もいるのかなという懸念もありました。今年２月に転校する人は申し出てくださいなどの呼びかけをしておりますが、実際、移った人もいるという話も聞いておりますが、品川区で、昨年いじめ調査のアンケート調査もやったわけですから、そういう実態も踏まえていると思うんですね。皆さん、見ていると思うんです。","respondent":"古里学務課長","answer":"もう少し待てないのかという問題ですけれども、私ども、平塚中学校、荏原第二中学校という、西地区における学校が、平成２２年４月に一貫校が立ち上がるというスケジュールの中で、両校が西地区の中学校として残っていく、あるいは教育環境として。","voiceIndex":148,"id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区の公立中学校が年度の途中でバレーボールをやるために９人の生徒を受け入れたということはどうかと思うんですが、一生懸命やっている姿を見て、こういう民間の方が頑張っているということで、私はある意味で感動もしましたが、これは、今、品川区の公立中学校のクラブ活動の実態でもあります。人間形成を培う意味で大事な、こういうクラブ活動にもっと目を向けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"小中一貫校問題で、荏原二中の統合の問題で、今の関連でお伺いをしたいと思います。特に中学校においての統合が大変難しいというのは区教委のほうでもおっしゃっていますけれども、各学校で異なる実際の教育の進め方などなど、子どもたちの先行きに大きな不安を感じているのが保護者の皆さんから率直に出されていますけれども、何回も紹介されましたけれども、平成２０年の統合をぜひおくらせてほしい。","respondent":"古里学務課長","answer":"先ほど来るる説明をいたしております。私どもも、平成２０年、平成２１年、平成２２年、それぞれに検討いたしました。","voiceIndex":152,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどから同じ答弁ばかりで、なぜ望ましいのか。なぜならば、子どもたちのことを一番考えているのは、親であり、子どもたち本人です。親がこれだけ意見を言っています。その親の声を聞いてどうなのかということを問うているわけです。子どもたちの責任を負っているのは、親であり、また、本人にも意向がしっかりあるじゃないですか。その辺を踏まえて、望ましいと一方的におっしゃる理由をもう１回聞きます。","respondent":"古里学務課長","answer":"このことを私どもは一番恐れております。そういう意味から、子どもたちの融合を徐々にしていきながら、西地区一貫校としてすばらしい学校環境に仕立て上げていきながらスタートさせていきたい。これが私どもの考え方です。","voiceIndex":154,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"平成２２年４月の一貫校開校は、平塚中学校と平塚小学校と２校合わせての小中一貫校、これを急遽３校にしたので、無理無理最後のゴールのところだけを引いてしまって、それを動かさないということ自体がおかしいと。私は平成２２年４月をおくらせればいいと思います。地域で今反対が起こっていますが、地域の了解を得られない場合は、考えを直せるのかどうか、その辺を最後にお伺いします。","respondent":"古里学務課長","answer":"この問題につきましては、２月９日に初めて地域の方々にお話をし、順次お話をさしあげています。現在のところ、在校生の保護者の方までしか説明ができておりません。これからるる説明をしていくという過程ですので、今の段階でそのようなことは判断できないと思います。","voiceIndex":156,"id":"exchange-069"},{"speaker":"川西委員","kind":"質問","question":"２９７ページ、教育センター関連、同じページのすまいるスクール、あとは、３０１ページになるんでしょうか、通学安全について、それから、３０３ページに関係があるかと思いますが、特色ある教育活動の中の小規模校についての配慮について伺います。それから、３１３ページ、預かり保育、幼稚園の関係です。","respondent":"河野指導課長","answer":"教育相談センターと小学校に配置しているスクールカウンセラーとの連携の件ですが、こちらのほうにつきましては、毎月１回相互に情報交換会を持ちまして、それぞれの取り組みについて、日常的に連携をしながら進めているところです。","voiceIndex":159,"id":"exchange-070"},{"speaker":"川西委員","kind":"質問・要望","question":"要望については後ほどにいたします。すまいるスクールの件ですが、４７人の職員と、あとは短時間勤務者の補充員、専門職員と派遣ということになりますが、今の現況の体制について、１つの学校の中におけるすまいるスクールの統括責任者というのはどういう体制になっておりますか。","respondent":"市川庶務課長","answer":"各すまいるスクールでの統括責任者は、すまいるスクール運営費のところに職員給与費で４７人と挙げてありますけれども、この４７人のうちの４０人は、小学校４０校に各１名ずつ常勤の指導員として配置している職員ですけれども。","voiceIndex":161,"id":"exchange-071"},{"speaker":"川西委員","kind":"質問","question":"もう一つは、子どもたちが不特定ですよね。たまには顔色の悪い子もいたり、心配事があるような雰囲気を持つ子どももいたりというのは、どなたがどういうふうに把握して、だれに相談をしているのかということを伺います。もう一つは、保育園は、７時半、８時半、１０時ということがあります。６時以降の体制で、すまいるスクールで相談を受けたことはありますか。","respondent":"市川庶務課長","answer":"常勤の指導員の不在の場合の対応ですけれども、常勤の指導員のほかに、非常勤の職員、特に教員資格を持った、私ども通常Ａ非常勤と呼んでいますけれども、その職員を１名ないし２名、配置しています。","voiceIndex":163,"id":"exchange-072"},{"speaker":"川西委員","kind":"質問","question":"品川区内全部わかっているわけではありませんが、近隣の学校では、苦情があってという今回の質問ではありません。内容の充実をさらに進めていきたいという立場から質問をさせていただきました。次に移ります。先ほどの説明のときに、通学安全経費、３０１ページですが、項目は別にないですよね。通学安全経費というのはあるんですか。８３運動、３１７ページの関連でしょうか。これを先に伺います。","respondent":"市川庶務課長","answer":"交通安全指導と通学路の巡視、この２つで通学安全監視という事業を構成しています。","voiceIndex":165,"id":"exchange-073"},{"speaker":"川西委員","kind":"質問・要望","question":"平成１８年度から始められたということですね。次に移ります。ですけど、小学校入学以前のときに、一貫校の特色は大分宣伝していますからいいんですけれども、小規模校と普通の学級との違い、小規模校のよさ、特色ある教育活動がそれの１つなんでしょうか、そういうものを区としてもＰＲをしてほしいと思いますが、その辺についてどういう努力をしていらっしゃるか、伺います。","respondent":"吉村小中一貫教育担当課長","answer":"今委員がおっしゃったように、小規模校のよさについては、教育委員会も十分に認識しております。学校選択制が始まったときから、小規模校のよさをいかに保護者に理解してもらうか、地域の方に理解してもらうか、この点についてはかなり学校が努力しています。","voiceIndex":167,"id":"exchange-074"},{"speaker":"川西委員","kind":"質問","question":"そこへ参加した親たちは、やっぱり行ってみてよかったと言っています。次の幼稚園の預かり保育、全園実施なんですが、平成１８年度の人数と、それから、この人員体制の中で、１園何人ぐらい預かれるのかということと、預かり保育が、親が困って預けているという印象のないような、差別感を子どもが持たないような預かり保育の実施を期待するところなんですが、いかがでしょうか。","respondent":"高橋幼保一元担当課長","answer":"平成１８年度から始まりました幼稚園における預かり保育の実績ですが、こちらのほうは、平成１８年度９月から実施した園が４園、１月から実施した園が３園あります。その中で、昨年度９月から実施しましたところは、総数はありませんけれども、平均でよろしいでしょうか。","voiceIndex":169,"id":"exchange-075"},{"speaker":"大沢委員","kind":"確認","question":"２９５ページ、教職員研修、３１７ページ、文化財保護事業について聞きます。教職員研修、今ここに書いてあります、学校経営研修、生活指導主任研修ほか９研修と書いてあります。大体１０個の研修があると。ほかには研修がないということか、確認をさせてください。","respondent":"河野指導課長","answer":"研修は、今委員ご指摘のほかにもまださまざまな研修があります。","voiceIndex":172,"id":"exchange-076"},{"speaker":"大沢委員","kind":"質問","question":"さまざまな研修、そうすると、大体どれぐらいの研修が行われているのか、数がおわかりになれば、教えてください。","respondent":"河野指導課長","answer":"ざっと十五、六の研修項目があります。１回で行う研修もあれば、数回に分けて実施する研修もあります。","voiceIndex":174,"id":"exchange-077"},{"speaker":"大沢委員","kind":"質問","question":"１回に分けて、そして継続的にやる研修ということで今伺いましたけれども、小中一貫校の推進に向けてという準備、平成１８年に小中一貫教育が始まったということで、品川区の教育、今、助走段階、これからいろいろな検証をし、煮詰まっていくところだと思いますけれども、この研修、本来先生方、学習指導、生徒指導、また進路指導ということで、さまざまな指導があるわけですけれども、先生方の研修、頻度は。","respondent":"河野指導課長","answer":"ただし、初任者に関する研修につきましては、長期休業日中だけで集中して行われる研修ではございませんので、月に２回ないしは３回程度、どうしても研修に出なければならないという実態があります。","voiceIndex":176,"id":"exchange-078"},{"speaker":"大沢委員","kind":"質問・要望","question":"配慮をされているということなんですけれども、研修を受けるとなると、先生方、いろいろな研修を受ける上で、授業時間のコマをいろいろと工夫をされなければいけない部分もあるんじゃないかと思います。中には、自習になったり、短縮になったりするような状況も見受けられるんですが、そこのところ、確認をさせていただきたいと思います。","respondent":"河野指導課長","answer":"したがいまして、その研修に出る教務主任、あるいは生活指導主任については、その時間帯は授業を入れないように通常から時間割を組んでいるのが原則です。なお、このような研修については、開始の時間を午後３時ということで、子どもたちの授業に支障がないように配慮しています。","voiceIndex":178,"id":"exchange-079"},{"speaker":"大沢委員","kind":"質問・要望","question":"多忙であるという事実は否めないわけですから、子どもたちの授業、勉強を教える先生方の準備の時間に支障がないような研修の持ち方をお願いしたいと思います。次に移らせていただきます。それに対して、文化財保護という観点から、品川用水、１冊だけでクローズアップされているように思われますけれども、その重要性、どこら辺ぐらいまでとらえていらっしゃるでしょうか、お答えください。","respondent":"富田生涯学習課長","answer":"品川用水、また品川用水にかかっていた橋というお話でございましたけれども、私どもも、そういった冊子を出すのも１つでありますし、また地域史をおこしていく中で、品川用水が、現在はないわけですけれども、歴史の中に占めていた。","voiceIndex":180,"id":"exchange-080"},{"speaker":"大沢委員","kind":"質問","question":"広く調べていただいているんですね。ここに一覧表が、これは資料ないんですが、調べてあるんです。広く区民の皆様に知らしめるように資料としてあります。確かに数は多いですけれども、お猿橋から始まって、平塚橋、こっちの蛇窪の２つに分かれていくわけですけれども、それを表現できるような方策というのは、考えてはいらっしゃらないでしょうけど、何かアイデアはお持ちでしょうか。","respondent":"富田生涯学習課長","answer":"品川用水の橋等につきましては、品川の史跡めぐりの付図の中の一覧として残しています。それをまちのサインの１つとして表示するということにつきましては、今後検討課題とさせていただきたいと思います。","voiceIndex":182,"id":"exchange-081"},{"speaker":"大沢委員","kind":"質問・要望","question":"今後検討していただきたいと思います。子どもたちは、小山台小学校、後地小学校、荏原一中、そういう意味では文教のまちの１つでもありますし、まさに通学路にかつての用水が通っていた部分もあります。そこのところをぜひとも啓発運動をしていただきたいと思いますし、検討していただけるに値するのであれば、お願いをして終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-082"},{"speaker":"山路委員","kind":"質問","question":"最初の小学校におけるカウンセリング事業ですが、スクールカウンセラーは、先ほど何件かお話もありまして、若林委員の質問に対しても、特別支援教育にも配置するというお話もございましたが、本年、平成１９年度は７名増加して、合計１４名でカウンセリングに当たられることだと思いますが、増やされたということは、学校内でそれだけいろんな相談、問題が多いのかなと。","respondent":"河野指導課長","answer":"スクールカウンセラーの役割としては、子どもたちの悩み事あるいは相談事に乗るということももちろん職務の１つではありますが、実際に一番重要な役割として私どもがスクールカウンセラーに期待している部分は、教員に対するコンサルテーション。","voiceIndex":186,"id":"exchange-083"},{"speaker":"山路委員","kind":"質問・要望","question":"過去にプライバシーの件で、ほかに漏れるんじゃないかということもございましたけれども、それは磐石に今後体制を整えられていかれると思いますけれども、よろしくお願いします。それと、相談の内容ですけれども、いじめが今、社会問題になっていますよね。やっぱりこういう問題が多いのでしょうか。ほとんど言えないと思いますが、データがあったら、言える範囲で何点か教えていただきたいと思います。","respondent":"河野指導課長","answer":"これが現状ではスクールカウンセラーのところに一番多く寄せられております。なお、教員からスクールカウンセラーへの相談については、不登校問題、あるいは発達障害に関する助言を求めるというケースが圧倒的に多数を占めております。","voiceIndex":188,"id":"exchange-084"},{"speaker":"山路委員","kind":"質問","question":"続きまして、情報教育についてですが、毎年私は情報教育について、新聞の社会面を読んでおりますと、ＩＴの推進に伴って、子どもたちは特にＩＴ技術は早く、どんどん覚えて発達していくと思うんですけれども、一方、情報教育についてどの辺まで、もう少し情報教育がしっかりなされていれば、こういうことは起こらなかったのにという場面があるんですけれども。","respondent":"吉村小中一貫教育担当課長","answer":"ＩＴにかかわる情報教育ですけれども、通常は、まず社会科という教科の学習、それから中学校部分でいきますと、技術家庭科、技術の部分、こういった部分でＩＴに関するさまざまな事例を取り上げるわけですけれども、今、委員ご案内のとおり、昨今の情勢を見ますと。","voiceIndex":190,"id":"exchange-085"},{"speaker":"山路委員","kind":"確認","question":"大体昨年と同じような答えだと思うんですけれども、分野がどんどん広がってきましたよね。理科とか社会とか、今、実例を挙げられましたが、分野が広がってきまして、専門家のお話によりますと、それぞれの年代に応じた情報教育を進めていくことが大事だと言われているところが気にとまったのですが、この辺に関しましては、年代に応じて共通の情報教育が行われているのかどうか、確認をしたいと思います。","respondent":"吉村小中一貫教育担当課長","answer":"先ほど市民科の例で申し上げたんですけれども、１つの柱という部分で、１年から９年まで設けるということも実は考えたんですけれども、やはり１、２年生の場合には、まだその辺の理解はかなり難しい。","voiceIndex":192,"id":"exchange-086"},{"speaker":"山路委員","kind":"質問","question":"さらに情報教育の徹底によって、ＩＴ技術の発達でのバランスがとれるということも言われておりますので、今後ともよろしくお願いいたします。次にまいります。３１１ページの品川地区一貫校基本設計委託等として計上してありますが、その「等」というのは、どういう意味をなすのか。これから設計されて、平成２３年ですか、その推移についてお伺いします。","respondent":"市川庶務課長","answer":"ここにあります「等」の中身ですけれども、基本設計に伴いまして、例えば地中調査等が必要な場合、こういったことで関連経費、基本設計をするに当たっての関連経費ということで「等」という言葉を使わせていただいてあります。","voiceIndex":194,"id":"exchange-087"},{"speaker":"沢田委員","kind":"質問・要望","question":"これまで議論があったところと若干重複するかもしれませんけれども、２月７日に平塚中と平塚小の母体校で統廃合するというプレス発表があって、その後、２月９日から説明に入っていったというんですが、一体この方針を品川区教委として決定したのはいつの段階なのか、もう一度聞かせてほしいのですが。","respondent":"古里学務課長","answer":"この件につきましては、私ども、るる申し上げてありますが、予算編成をする過程の中で、荏原西地区の平塚中学校、荏原第二中学校、この両校の今後のあり方を多方面から検討した中で、予算編成の過程の中で、二中と平中を１つの学校として新しくスタートさせるということを決定し。","voiceIndex":199,"id":"exchange-088"},{"speaker":"沢田委員","kind":"意見","question":"私が聞いているのは、その方針を、いつ、どういう期間で決定をしたのか。予算編成の中で決定したというのはわかったんですが、どこで決めたのかと聞いているんです。","respondent":"古里学務課長","answer":"決定のプロセスですけれども、平成１９年度予算要求案の作成につきましては、平成１８年の１１月の教育委員会の中で予算要求の概要ということでご説明をし、ご審議をいただいてあります。その中には、統合の問題も当然入ってあります。","voiceIndex":201,"id":"exchange-089"},{"speaker":"沢田委員","kind":"質問","question":"教育委員会として決定したんですか。何となくはっきりしないんですが、平成１８年の１１月の予算要求の概要を議論したときに、決定したのだか、その中に入っていたのだか、さっぱりわからない。要するに、教育委員会で、これを議案として提出して、決定したのはいつですかと私は聞いているんです。","respondent":"古里学務課長","answer":"１１月の教育委員会には議案として提出していますから、当然議案として教育委員会として決定したものと考えています。","voiceIndex":203,"id":"exchange-090"},{"speaker":"沢田委員","kind":"質問","question":"私ども、文教委員会で聞いたときには、２月１３日と聞いているんですけど。そうすると、その前に決まっているんですか。これは一体どういうことなんでしょうか。議案として入っているんじゃない。教育委員会の皆さんに、荏原二中を荏原西地区に入れるということは、鮮明化していなかった。そこを飛び離れて、どんどん教育委員会事務局が進めているのではないかと思うんですが、いかがでしょうか。","respondent":"古里学務課長","answer":"文教委員会のときにもご説明申し上げましたけれども、平塚中、平塚小の場所にでき上がる荏原西地区一貫校についての建設準備会での地域での説明についても、教育委員会のほうに適宜ご報告を申し上げてきているところです。","voiceIndex":205,"id":"exchange-091"},{"speaker":"沢田委員","kind":"質問","question":"今言っているのとこれと、どっちが正しいんですか。文教委員会でもそうですけど、いつ、どこで、だれが、どう決めたのか、くるくる変わっちゃう。今日聞いたらば、１１月何日の予算のときに決めたと言うけど、そこで決まっているなら、なぜ学校選択のときに皆さんに、「こういう方針を決めました。いかがでしょうか」とやらなかったんですか。手順が全然違うじゃないですか。方針を決めてきた。","respondent":"古里学務課長、市川庶務課長","answer":"１点目のご質問の内容ですけれども、手順ですけれども、２月９日のプレス発表時にこれをあえてつけ加えなかったです。６校構想の決定に関しては、平成１８年度の予算査定の中で最終的に決められたです。","voiceIndex":207,"id":"exchange-092"},{"speaker":"沢田委員","kind":"質問","question":"去年の夏ぐらいから説明会でもって十分説明をしてきたと言うんですけれども、荏原二中を３校の中に加えると言ったんですが、いつ、何人ぐらい参加して、どれぐらいの意見が出たのか、具体的に説明してもらえますか。それからもう一つ、小中一貫校を６校構想に新たに展開するときに、予算査定の中で決めたと言うけど、教育委員会ではいつ決めたんでしょうか。その点、お答え願いたいと思います。","respondent":"市川庶務課長","answer":"このことはぜひご理解をいただきたいと思います。それと、１点目のご質問ですが、荏原西地区の一貫校についての計画説明の場ですけれども、昨年の７月、１０月、１１月、それぞれ１回ずつ、計３回説明会を実施してきてあります。","voiceIndex":210,"id":"exchange-093"},{"speaker":"沢田委員","kind":"質問・要望","question":"）の管理に関すること」。ちょっと前後しますけれども、１項で、「教育委員会の所管に属する第３０条に規定する学校その他の教育機関の設置、管理及び廃止に関すること」と、明確に教育委員会のこれをうたっているじゃないですか。その点をもう一度お答え願いたいと思うんですが、去年私どもで、小中一貫校６校構想を決めたファイルを提出してほしいと情報公開を求めました。いかがでしょうか。","respondent":"古里学務課長","answer":"再三同じ回答で申しわけございませんけれども、平成１９年度予算の編成をする過程で、昨年１１月に教育委員会で議案として審議をいただいてあります。この中には、平塚中学校、あるいは荏原第二中学校の改修費用、平塚中学校の移転費用等、こうした経費も含んです。","voiceIndex":212,"id":"exchange-094"},{"speaker":"沢田委員","kind":"質問・要望","question":"正規の議案としてあるなら、改めて情報の公開なり資料の提供を求めたいと思います。例えばある教育委員は、平塚中、二中を統合するということは、一方が廃校になるんじゃないかと発言しているんです。３,２００の反対運動があったけど、押し切っちゃった。教育委員会は、子どもたちに地方自治、住民参加をどう教えるんですか。こういうスタンスで言ってきましたけれども、今後これは変わらないでしょうか。","respondent":"古里学務課長","answer":"学校選択制にかかわって、区が過去申し上げてきたことは、委員がおっしゃるとおりです。このことについては何ら変わらないと考えています。","voiceIndex":214,"id":"exchange-095"},{"speaker":"沢田委員","kind":"質問","question":"だけど、平成２０年に統合するということについては、ちょっと待ってくれ、今の１年生がせっかく小規模校を選択したんだから、３年間待ってくれという点では、大方一致していると私は思います。先日の文教委員会で私は以上のようなことを質問して、地域が反対をするのなら、政策の見直しもあるのかということを質問いたしました。せめてこの立場で貫いてほしいと思いますけれども、いかがでしょうか。","respondent":"長田教育次長","answer":"私の文教委員会での発言ですけれども、これはすべて、あるいは大半の方々がそろって反対をするということについては考えますけれども、私ども、こういった説明の中で、十分必要性については理解が得られるだろうということで、今、進めているところですので。","voiceIndex":216,"id":"exchange-096"},{"speaker":"沢田委員","kind":"質問・要望","question":"仮校舎やいろんな問題を考えてというのなら、なぜそれを決めた去年の１１月から説明しなかったんでしょうか。改めて私は、みんなの意見を聞いて考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-097"},{"speaker":"伊藤委員","kind":"質問・要望","question":"場合によっては、そういうところからいじめの兆候につながるような、歯科医師の観点からも見れたらと言っていましたので、ぜひそういうことを生かしていっていただきたいと思いますので、確認したいのが、医師会、歯科医師会との関連の中で、こういう健康管理の中から、いじめの発見につながる仕組みを構築しているかどうかということをまず確認ください。","respondent":"古里学務課長","answer":"来年度以降、保健委員会の活動の充実ということについて話し合うということを予定していますので、委員がおっしゃったような内容も、その中で検討させていただきたいと思います。","voiceIndex":220,"id":"exchange-098"},{"speaker":"伊藤委員","kind":"確認","question":"今、少し答弁がありましたけれども、もう少し先をにらんだ対処の中で、毎年何千人の子どもたちを診察しているわけじゃないですか。その中で、この子はというのがもしあった場合に、その情報をちゃんと教育委員会がつかまえて、いろんなところで対処できる仕組みをつくっていけば、広い意味でいじめ撲滅につながっていくと思われますので、そのことについての再度の確認答弁をお願いいたします。","respondent":"古里学務課長","answer":"委員がおっしゃった、その他の情報、それから児童課との連携、教育委員会との連携等々もその中で検討させていただきたいと思います。","voiceIndex":222,"id":"exchange-099"},{"speaker":"伊藤委員","kind":"質問","question":"家庭教育支援ネットワーク講習について質問します。おそらくそういう中で、このネットワーク講習が１つの事業としてできたと思われますが、まず、家庭教育支援ネットワーク講習の目的、内容、対象者、どこで行われるかということについてお聞かせください。","respondent":"富田生涯学習課長","answer":"参加者につきましては、保護者を中心に関心のある区民の方々ということで呼びかけをしておりまして、会場といたしましては、文化センターですとか、児童センター、中小企業センター等々で実施しています。","voiceIndex":224,"id":"exchange-100"},{"speaker":"伊藤委員","kind":"確認","question":"ただ、非常に難しいのは、そういうところまで行政が手を突っ込むことができるか。ですから、確認したいのが、今回親育て施策を打ち出しました。つまり、家庭教育学級ではなく、さらにプラスアルファしたものを少なくとも講座としては講習としてやっていって、妊娠から中学校卒業までの間はある程度一貫して、品川区は親育ちにかかわる施策を構築していくべきと思うんですが、いかがでしょうか。","respondent":"富田生涯学習課長","answer":"委員ご指摘のように、教育委員会主催講座に手を挙げてきてくださる方々ではなくて、それぞれ悩みを抱えた方々にどうそういった親育ちの部分の講習等をしていくかというところでは、家庭教育委託学級ではなくてとおっしゃられたんですけれども、家庭教育委託学級の中でも。","voiceIndex":226,"id":"exchange-101"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、１点だけお願いしたいのは、学校単位で将来は開いていっていただきたいということをお願いだけしておきます。それから、親育ち施策というふうに堂々とうたっていますけれども、これはとてもテーマが広いじゃないですか。つまり、ここからここまでが親育て施策であるということを初めから打ち出して対処していくべきと思いますが、そのことについての品川区の考えをお聞かせください。","respondent":"日下部企画財政課長","answer":"これが１つの出発点でありまして、そういった意味では、いろいろ施策の取り組み分野が広がってまいりますので、そういう意味では、生涯学習の関係はもちろんですが、これから、児童課のほうでも児童センターを中心にした相談体制でありますとか、あるいは、保健所でありますとか。","voiceIndex":228,"id":"exchange-102"},{"speaker":"三村委員","kind":"質問・要望","question":"すまいるスクールへ移った後、とても大きい落差があると考えられますけれども、実際、そういった保護者の声も去年、新聞記事になっておりましたけれども、そういったことを考えますと、すまいるスクールが全児童対策としての事業として行われているということは理解しておりますけれども、ご両親が共働きの家庭の子どもたちが利用した場合の課題やその対策についてお考えをお聞かせいただきたいと思います。","respondent":"市川庶務課長","answer":"ご質問にございました、就学前から小学校入学にかけての環境の変化ですけれども、すまいるスクール、現在６時まで利用時間を設定しております考え方は、１年生も含めて、小学生になったら、１人で親の帰りを家で待てる。","voiceIndex":234,"id":"exchange-103"},{"speaker":"三村委員","kind":"質問","question":"会社の労働時間が大変長くなっているという現状の中では、品川区としても、こういった小学校、特に低学年の子どもたちに対して積極的な支援対策が必要かと思いますけれども、決算特別委員会のほうでもそういった質問をさせていただきましたけれども、その際、いろいろ検討していきたいといったお答えをいただいたんですけれども、その後どういうふうな検討をされたのか、お伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"個別の事情等がおありの場合は、平成１９年度、さらに相談体制等も、児童センター等を中心に進めておりますので、そういった中で、事情事情に応じて個別にご相談いただいて、その後またアドバイスできることですとか、ファミリーサポートですとか、そういった部分、ご紹介したり。","voiceIndex":236,"id":"exchange-104"},{"speaker":"三村委員","kind":"質問・要望","question":"そういったいろいろな状況が考えられると思うんですけれども、今まですまいるスクールへの移行の経過については十分承知しておりますし、そういった中で、おやつのあり方についていろいろ議論があったということは十分承知しているんですけれども、学童保育クラブからすまいるスクールへの事業移行の直後は、現場も大変混乱していらっしゃったと思いますし、そういった中で。","respondent":"市川庶務課長","answer":"ただ、事情のある子どもは、特に保護者の方からの相談があって、その子が補食をとらざるを得ないときには、必要な対応を既に現場でもとってあります。そういった個々の子どもの事情に応じた対応ということは、今後ともとってまいりたいと思ってあります。","voiceIndex":238,"id":"exchange-105"},{"speaker":"堺委員","kind":"質問","question":"私からは、２９９ページの特別支援教育費にあります心障学級経費に関連して１点。３点目が、３２１ページにあります戸越体育館大規模改修費に関連してお伺いをしたいと思います。このように記載されております。そこで、これの中身なんですが、この改修に当たって、利用者にとって使い勝手のいい改修をぜひお願いしておきたいと思うのですが、その中身、内容についてお知らせいただけますでしょうか。","respondent":"河野指導課長","answer":"特別支援教育に関連する施設の充実という点ですが、宮前小学校におきましては、現在、通級ということで対応していますが、これからは、できるだけ個々の子どもたちへの対応というのが中心になってまいりますので、現在ある教室を改修いたしまして。","voiceIndex":241,"id":"exchange-106"},{"speaker":"堺委員","kind":"質問・要望","question":"私もかつてこういう方々といいましょうか、関係者の人から強い要請がございまして、教育長にも直接会って要望させていただいた経緯がございましたので、この件について確認させていただきました。次に、３１９ページのスポーツ関連です。今現在、特に少年野球、少年サッカーのチーム数とか人数は把握されておりますか。","respondent":"富田生涯学習課長","answer":"手元の資料によりますと、少年野球につきましては、大井西、品川、荏原、大井、荏原東、それぞれ地区がありますけれども、小中学生合わせまして５８チーム、１,５００人強の選手の方がいらっしゃるということでありまして、少年サッカー連盟につきましては、小学生３３チーム。","voiceIndex":243,"id":"exchange-107"},{"speaker":"堺委員","kind":"意見","question":"こういう中でも、先ほどご答弁いただきましたように、野球についても、５８チームで１,５００人、サッカーについても、３３チームで１,３００人。登録されている、あるいは利用されている人数にはそんな大差はないですが、お尋ねをしておきたいのは、サッカーをやっている子どもたち、現状、練習等については、どこでどういうふうにやっているか、お知らせいただけますか。","respondent":"富田生涯学習課長","answer":"少年サッカーにつきましては、主にそれぞれの小学校のグラウンド、校庭で放課後等に練習をしている。あるいは土曜、日曜も少年野球と調整しながら使っているチームもあると聞いております。","voiceIndex":245,"id":"exchange-108"},{"speaker":"堺委員","kind":"質問","question":"小学校の校庭、野球と調整しながらということですが、さっき申し上げた事務事業概要の５２ページによりますと、例えば公園運動施設として、少年野球場、これはこどもの森公園１面、しながわ区民公園２面、多目的広場、しながわ中央公園１カ所、ここは多目的ですから、野球やサッカー等もできるんでしょうか。ある学校の監督をやっている人からそんな話があったんですが、そういう現状は把握されておりますか。","respondent":"富田生涯学習課長","answer":"そのような学校もあると聞いております。","voiceIndex":247,"id":"exchange-109"},{"speaker":"堺委員","kind":"意見","question":"どちらかというと、野球をやっているチームはそれなりの歴史がありますから、こういうことを言うとおしかりを受けるかもしれませんが、優先的な形で使われるというか、使っているというか、やむを得ない部分があるかなと。関係者の人たちから、そういうところがないので、何とかしてほしいという要請があったんですが、そういう声は届いていますか。","respondent":"富田生涯学習課長","answer":"日常の練習の場面でサッカー場をという声は聞いておりませんけれども、例えば大会等の場合には、しながわ中央公園の多目的広場、これは野球の使用ではなく、サッカーを含めた多目的使用になりますが、それですとか、最近改修しました天王洲公園の野球場のＣ面の部分等ですとか。","voiceIndex":249,"id":"exchange-110"},{"speaker":"堺委員","kind":"質問・要望","question":"重ねて、さっき申し上げた、少年野球場というのはある。少年サッカー場というのは明確に冠をつけたところがないので、できれば、今後いろんな形で、例えば小中一貫校の施設であくところが出ますね。そういう場所であるとか、いろんな形で、冠をつけても使えるような場所を、ぜひ創意工夫しながら設置をしていただきたいと思うんですが、もう１回ご見解をお伺いできますか。","respondent":"富田生涯学習課長","answer":"サッカー人口が大変増えてきているという状況等を踏まえ、今後の課題ということで受けとめさせていただきたいと思います。","voiceIndex":251,"id":"exchange-111"},{"speaker":"堺委員","kind":"質問","question":"ぜひひとつご検討をお願いしておきたいと思います。３点目に、戸越体育館の大規模改修についてですが、あそこにあるアスベストについても、今回除去作業の対象に入れた上で、大規模改修されるんだろうと思うんですが、この辺について、どこをどう改修されるのか、簡単で結構でありますが、教えていただけますか。","respondent":"富田生涯学習課長、宍戸施設担当課長","answer":"戸越体育館の大規模改修、約３億円ほど予算計上していますが、改築から２０年ほどたちまして、雨漏りですとか、水回りの不具合が大変出てきておりますので、雨漏りの補修ですとか、あるいは。アスベスト除去も当然入ってあります。","voiceIndex":253,"id":"exchange-112"},{"speaker":"堺委員","kind":"意見","question":"ぜひその辺について、対応をお願いしておきたいと思います。それから、あそこの現況なんですが、駐輪場と駐車場、たしかあそこは駐車場はないですよね。どのような認識を持っておられますか。","respondent":"富田生涯学習課長","answer":"戸越体育館の駐車場は２台分ございまして、１台は障害者用ということで、あとは、指導員用ということで、一般の方には駐車場はございませんということで、ご案内をさせていただいておりました。駐輪スペースについては、４０台程度分ということで確保しております。","voiceIndex":256,"id":"exchange-113"},{"speaker":"堺委員","kind":"質問","question":"駐車場は２台しかありませんから。駐輪場も４０台あるとはおっしゃっていますけれども、あの辺も、かなり駐輪場も大変な状況になっている。そこで、まちづくりという視点で、今後の戸越体育館の駐輪場、あるいは駐車場対策として、国文学研究資料館の跡地の有効活用等も含めて、全体的に戸越体育館利用者のための利便性向上のための創意工夫もお願いをしておきたいと思うんですが、その辺はいかがでしょうか。","respondent":"日下部企画財政課長","answer":"土木費でも出てまいりましたけれども、資料館の跡地を取得する。戸越公園との一体的な整備ということで検討を平成１９年度する予定になっておりますので、今のご指摘の点は、その中の課題の１つとして受けとめさせていただきたいと考えます。","voiceIndex":258,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問・要望","question":"短く４点聞きたいと思います。２９５ページ、小学校におけるカウンセリング事業、３,５７９万。この３校がどこにいっちゃったのか、どうなっているのかを聞きたいと思います。校長先生、３月３１日で退職されますけれども、校長先生、退職されないで、その学校に残って校長をやるんだといううわさを聞いたのですが、それの真偽をお聞かせいただきたいと思います。","respondent":"河野指導課長、古里学務課長、日下部企画財政課長","answer":"そこで、退職される校長先生方の中で、特に優秀で、なおかつ継続して仕事を務める意思のある校長先生方の中から、都のほうが再度選考いたしまして。議案説明会の資料の２９ページ、確かに１０校から２３校と書いてあります。要するにカウントの仕方が違うものをそれぞれ別立てというのは、説明する点からすればいろいろ問題がありますので。","voiceIndex":261,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいは、これがまた数が将来増えていくのかどうかについてお伺いをしていきたいと思います。それと、いじめ、不登校、今大変に問題になっているんですけれども、昨年はいろいろなアンケートもとったというんですけれども、プラン２１が行われる中でというのは、大変に申しわけないですが、傾向として、いじめ、不登校というのはなくなっているのかどうか、最近の傾向と対策をお伺いしたいと思います。","respondent":"河野指導課長、古里学務課長、長田教育次長","answer":"このスクールカウンセラーの役割ということで、心の悩みに対応するのか、あるいは発達障害、特別支援に対応するのかですが、実際問題といたしまして。これは、価格面、業務の提案面、それぞれを評価して契約するというものです。制度そのものについては、４月から始まる内容ですので、制度についての報告はすべきであったかなと考えているところです。","voiceIndex":265,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"一番の問題は、中毒を起こしたり、あるいはそのときに給食を休むわけにいかないので、どうするかという問題なんですけれども、それもいろいろ組合関係でケアできますので、そういうものから見ると、やはり大企業ばかりじゃなくて、できるだけ地場産業の育成ということで、区内にある業者にも開放すべきだ。すべてとは言いませんけど、そう思っておりますので、その辺の考えをお聞かせいただきたいと思います。","respondent":"本間助役","answer":"すべて区内の契約事務につきましては、区内業者の育成という視点をしっかり持って事務に携わっているわけですが、ただいまいただきました意見も、そういう業者が少しでも多い中で選定できる状況が好ましいわけですから、どのような形で取り入れるか。","voiceIndex":269,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"２９５ページ、カウンセリング事業、２９７ページ、すまいるスクール運営費について、３０５ページの教育振興費、２９７ページのプラン２１関連で、特に学校選択について、２９３ページの学校適正規模検討経費について、それぞれお聞きします。その中で、カウンセリングを個々の学校でするときの部屋の確保はどうなっているのかをお聞きしたいと思います。","respondent":"河野指導課長","answer":"かなりの学校に相談室が整備されておるんですが、小学校について、まだ一部不十分なところがありますので、これから年次を追って整備していくということで、今、予定を立てているところです。","voiceIndex":272,"id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"ソファ等々、備品等についてもきちっと設置をしていただきたいと考えています。次に、すまいるスクール運営費ですが、学習はある程度、全小学校のすまいるスクールで統一的に取り入れているとなっておりますが、イベント的な行事は、地域の方にお願いしたりということで、いろいろ確保されていると思うんですが、各学校によっての状況はどのような形になっているんでしょうか。","respondent":"市川庶務課長","answer":"４０校の実情から申し上げますと、かなり盛んなところもあれば、そうでないところもあるというのが実情です。","voiceIndex":274,"id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"そういうことであるならば、今年度も、政策の中に取り入れていますボランティアとか、ＮＰＯというのが出てきていますけれども、そこの団体の方たちと全体的なつながりを持って、例えば指導員の方たちがこういうことをやりたいと言った場合に、じゃあ、ボランティアセンターに行って、そこと共同して、派遣していただくとか、そういう共同作業ができるのではないかなと思いますが。","respondent":"市川庶務課長","answer":"特に私どもが通常の手段ではなかなか指導者を探し得ない文化、芸術、こういった分野の方について、今後そういう方の人材確保というか、私どもの事業の充実に向けてご協力をいただける、そういったことについて検討していきたいと考えております。","voiceIndex":276,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう意味では、いろんな知恵があると思いますので、いろんな部署との関係の中から、より学校の中でのすまいるの中で、子どもたちと触れ合うことで、いろいろな教育にもいい方向につながると思いますので、有効的にいい関係をつくっていただきたいと思っています。経済的に困難だという方はいると思うんですね。その方たちに対して何か区として手立てができないものかなと思いますが、いかがでしょうか。","respondent":"古里学務課長","answer":"委員がおっしゃった小中一貫校の標準服の問題ですが、標準服はあくまでも学校と保護者の間で、小中一貫校の中で取り決められたものです。就学援助は、国の基準等々で決まっておる内容ですので、現在の段階でそうした個別の学校の事情に応じた支給は大変難しいかと考えています。","voiceIndex":278,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"今の制度の中では確かに難しいというのは重々存じ上げている状況なんですが、なぜ日野学園、伊藤学園が標準服を採用したかということは、どういう一貫校にしていくか。その中での標準服という位置づけがあるわけですよね。着たいけれども、着ることができないというのは、教育上よいとは思いませんので、品川区として何かの手立ては今後考えていただきたいと思いますが、いかがでしょうか。","respondent":"古里学務課長","answer":"就学援助という枠組みで考えれば、これは法律で決まっている形です。これの施行については、平等、公平ということが原則になりますので、この制度の中での検討は非常に難しいということ、繰り返しですが、そのような言い方をするしかないかなと思ってあります。","voiceIndex":280,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、強く要望をさせていただきたいと思っています。次に、プラン２１関連について、特に学校選択についてお聞きしたいと思います。ですから、今、入学をしている子どもたちは、すべて学校選択によって入学しているという状況になっていると思います。それが現実なんですね。ですから、そこから外れてしまうと、当然抽選になってしまうという現状があります。","respondent":"古里学務課長","answer":"私どもも、その深刻な声を聞きながら、検討を進めてまいったわけですけれども、学校選択制の中で、制度設計上、品川区は当初から兄弟枠を設けないということでスタートしてきております。","voiceIndex":282,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"選択制というのをどういうふうにとらえられているのかなというところだと思うんですね。選択をするという行為は、いろんなリスクがあるということだと思います。ただ、学校を学区外から選んだのにはそれなりの理由があるわけですね。その理由をきちっと考えた上で、じゃあ、兄弟関係をどうするか。そのリスクの中で保護者が判断するべき内容だろうと思っています。原点に立ち返ってお聞きしたいと思います。","respondent":"古里学務課長","answer":"これは、特色のある教育活動を見て学校を選ぶという行為が年々増加をしてきているというところから、学校そのものの教育活動の評価、あるいは、学校の指導方法の評価、こうしたものから学校を選択しているということだろうと類推できるかなと考えています。","voiceIndex":284,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問・要望","question":"学校をよくしようと。そのための１つの方法。デメリットもいっぱいあります。学校がよく見えるようになったというところでは、将来的に保護者が、隣の子も、自分の子も大切にしていくという形の１つとして、もっと学校選択の意識から持っていけないだろうかなと考えますが、学校選択の考え方についての今後の考え方を教えていただきたいと思います。","respondent":"吉村小中一貫教育担当課長","answer":"したがいまして、今、委員がおっしゃったように、学校選択制においては、そういうそもそもの親の意識を変えることにおいて、今まである程度の成果を上げてきておりますので、これを継続して、さらなる学校教育の質を高めるために努力していきたいと考えております。","voiceIndex":286,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"凍結してほしいというご意見が多いというお話は、その気持ちはわからないでもないんですが、じゃあ、凍結するということは、平塚中の子どもたちがプレハブで過ごさなきゃいけなくなるということですよね。それだったら、どうぞうちの学校に来てください、もっといい施設を私たちと一緒に使いましょうというふうな地域のつながりをつくっていただきたいと思いますが、その考え方についてはいかがでしょうか。","respondent":"古里学務課長","answer":"今回伊藤学園、伊藤中学校の子どもたちが仮設の校舎から本校舎へ戻ったときに、「仮校舎ありがとう」と黒板にたくさん書いてくれました。そういうこともありますけれども、それよりもっといい環境があるのであれば、それを出すべきだと思ってあります。","voiceIndex":288,"id":"exchange-126"},{"speaker":"木下委員","kind":"質問・要望","question":"おわかりになるんだったら、教えていただきたいと思います。それから、それに対する対策等をやっていること、品川の教育というのは、全国から注目されておりますので、いろいろ努力されていらっしゃると思うんですけれども、やっていることですとか、また、今後子どもたちに対する取り組みとして考えていること等ございましたら、お伺いしたいと思います。","respondent":"河野指導課長","answer":"ただ、それによって意欲がどう身についたのかということについては、現在、区として調査しているわけではございませんので、またさまざまな調査結果を分析しながら、検討してまいりたいと考えます。","voiceIndex":291,"id":"exchange-127"},{"speaker":"木下委員","kind":"質問","question":"スチューデント・シティですとか、ファイナンス・パークですとか、将来そういう経験を通じて、自分のやりたいことが、漠然となりながらも目標が決められれば、意欲も増していくのではないかなと思いますので、これからも取り組みのほどをよろしくお願いします。この間の新聞発表で気になったものですから、質問させていただきました。","respondent":"河野指導課長","answer":"発達障害のある子どもたちというのは、例えば自分が特に興味、関心を持っているものについては、その場の状況に合う、合わないにかかわらず、そちらのほうに動いてしまうとか、あるいは、特定の分野、例えば数字的な認識ができないとか、言葉の文字認識ができないとか。","voiceIndex":293,"id":"exchange-128"},{"speaker":"木下委員","kind":"質問","question":"ただ、ＬＤ学会ですとか、そういう報告によると、そういうベースを多く持っていらっしゃる方があるという発表が出ていますから、それに対する対策として、将来的にそういう問題等を起こすということは、その子にとっては二次災害みたいなものでしょうから、そういうふうにならないように、そういう治療というか、指導という部分だけではなくて、これからもう一歩踏み込んだ形での。","respondent":"河野指導課長","answer":"先ほども答弁させていただきましたけれども、さまざまな見解がありますけれども、私どもは、障害がある、なしにかかわらず、必要最低限度の社会性といいますか、そういうものが身につけられて、障害がある、なしにかかわらず、だれとでも仲よくできるような人間関係であるとか。","voiceIndex":295,"id":"exchange-129"},{"speaker":"木下委員","kind":"質問・要望","question":"品川区の場合、東北大学の加齢医学研究所、脳の専門家の先生ですとかに、こちらのほうは認知症の問題ですけれども、監修してもらったりなんかしているわけですから、そういう専門家と協力してというか、もしできましたらば、前もってゆがんだ部分を直していく、そういう教育の部分にも光を当てていただきたいと思いますので、これは私の要望ということで、よろしくお願いしたいと思います。","respondent":"工藤品川図書館長","answer":"小学校で、標準というふうに考えてみますと、８５.５％ということになってあります。中学校でも８５.３％ということで、標準には届いてございません。小学校で実際標準に達している学校ですけれども、小学校でいいますと１１校、中学校でいいますと８校です。","voiceIndex":297,"id":"exchange-130"},{"speaker":"木下委員","kind":"質問","question":"文部科学省、１,０００億円増額ということなんですが、品川には大体どのぐらいが来る予定なんでしょうか。いろいろなネットワークですとか、いろいろな部分で補っているというのはあるのかもしれないですけれども、そこら辺、どのようにお考えになっていらっしゃるのか、お聞かせ願えますでしょうか。","respondent":"工藤品川図書館長","answer":"今、整備事業、先ほど申し上げましたように、展開していますので、学校図書館整備をやっている学校に関しましては、小学校で５５万円を３年から５年間で増配でつけておる。中学校に関しましては、７５万円を数年間で補強といいますか、余分につけている状況です。","voiceIndex":299,"id":"exchange-131"},{"speaker":"木下委員","kind":"質問","question":"独自でやらなきゃならないということなんですけど、標準ということは、このぐらいあったほうがいいというのが、国の定めた基準でしょうから、今、活字離れというのが、お子さん方、進んでおりますので、本を借りていただくというためにも、本のレパートリーですとか、蔵書がいっぱいあったほうが子どもたちも選べるでしょうから、それに向けてひとつよろしくお願いいたしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-132"},{"speaker":"石田委員","kind":"質問・要望","question":"これは非常に難しいんですが、先ほど伊藤委員からもお話があった、悩みを抱えた保護者というところが、これでいろいろ力を入れていくと言うんだけど、ここはこれとして、教育のほうで、学校で保護者会というのがあると思うんですが、小学校と中学校の保護者会の、平均的でもいいんですが、保護者の出席率がわかれば、教えていただきたいと思います。","respondent":"吉村小中一貫教育担当課長、河野指導課長","answer":"２点目の、プログラムをつくるに当たって教育委員会がどこまでということなんですけれども、これについては、もともとのプログラムがアメリカのプログラムですので、アメリカのまま実施することはできませんので。学期が進むにつれて、学年が進むにつれて、だんだん出席率が下がってまいりまして、特に２年生、３年生の４月の保護者会というのは、極端に出席率が下がります。","voiceIndex":303,"id":"exchange-133"},{"speaker":"石田委員","kind":"質問","question":"この子どもの親と会う機会、保護者会では会えないわけですから、会う機会をいかにつくるのかというのは、校長先生に任せるのか、担任に任せるのか、逆に教育委員会として、こういうことをしろと。それだったら、家庭訪問は絶対強制でやるとか、学校に任せるのでなくて、教育委員会として、こういう指示を出して、必ずやれとか、必ずそういう親には会える機会ができるわけじゃないですか。","respondent":"吉村小中一貫教育担当課長、河野指導課長","answer":"そういったところについては、あの中で工夫をしなきゃいけないということで、かなりの人数が入ると活動がしにくくなるという部分がありますので、その辺は、各学校の教員なり、ボランティアに最初から。教育委員会として、各学校に対してそういうことを強制できないかという話ですが、逆の立場で考えてみますと、教育委員会にやれと言われても、親御さんのほうがなかなかそれに応じてくれないという実態も一方ではありますので。","voiceIndex":306,"id":"exchange-134"},{"speaker":"石田委員","kind":"質問・要望","question":"実際今の話で、教育委員会がどうとらえるか。学校の校長先生とか、副校長でも、大変です。もう１回そこのこと。８０人から１００人だったら、２回に分けてやるとか、そういうことをやっていただきたいなと。それはお願いだけしておきます。","respondent":"河野指導課長","answer":"特に問題行動を頻発に起こすようなケースについては、家庭訪問ということではございませんが、警察あるいは児童相談所、カウンセラー、あるいは民生委員、児童委員、主任児童委員等を交えたサポートチームを編成いたしまして、そこには私どもの指導主事も参加して、当該校の担任。","voiceIndex":309,"id":"exchange-135"},{"speaker":"三上委員","kind":"質問","question":"２９５ページ、区教員採用事務費、２９７ページ、すまいるスクール、それから、３１１ページか、３０１ページにかかっているんでしょうか、第一日野小学校の改築、同じく八潮地区の一貫校、３１７ページ、８３運動ということで、簡単に伺ってまいります。平成２０年度に要綱を定めて、採用するということになるということですけれども、通常の教員採用試験というのは、通年いつごろ行われているんでしょうか。","respondent":"河野指導課長、市川庶務課長","answer":"県費負担教員の選考ですが、東京都の場合には、まず申し込みが大体４月の中旬から５月の中旬ぐらい、それから、１次選考が７月の第２日曜日。１次選考合格者に対する２次選考が８月の第３土曜、第３日曜あたりです。ただし、昨年の１２月からこの１月にかけて、私どもが全児童の保護者を対象に実施したアンケートの中で、その他の要望ということの中で、少ないながらも、幾つか意見、要望としては上がってきているです。","voiceIndex":312,"id":"exchange-136"},{"speaker":"三上委員","kind":"質問・要望","question":"３０分で行けるかどうか。こういうことについてお伺いしたい。若干そこのところをお伝えいただきたいと同時に、室内プールについても、温水プールになるわけですから、しっかりとした、どうせプールとしてつくるならば、水質のいいプールをつくってあげるということも大事だろう。それは、北区の西が丘にあります国立スポーツ科学センターでしょうか、ここで導入している水というのは非常にいいですよね。","respondent":"河野指導課長、市川庶務課長、吉村小中一貫教育担当課長","answer":"それより前にするのか、後にするのかということについては、今後、さらにさまざまなメリット。１つには、同じ方向に帰るお子さんたちがいれば、下校指導という形で、すまいるの職員が対応している場合もありますし。","voiceIndex":315,"id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"最後に、８３運動のところで、せっかく子どもが通る中にあって、町会としてあいさつ運動をやろうと。そうすると、自分たちの顔を知ってもらうということについて、子どもが声をかけても、逃げ出しはしない。そこのところをしっかりと受けとめていただいて、これは答弁していただく時間はないので、要望だけしますけれども、そういう形でもしっかりと取り組んでいっていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":319,"id":"exchange-138"},{"speaker":"南委員","kind":"質問","question":"八潮の小中一貫校の関係で伺いたいと思います。八潮の一貫校は、当初は八潮小学校と八潮中の２校で一貫校教育を行うという計画でしたが、一挙に５校にしたのは、どういう理由なのか。地域に反対の意見はなかったのか、まずここから伺います。","respondent":"古里学務課長","answer":"地域からの反対の声ですけれども、それぞれ説明をしてきている中では、個別の保護者の方から反対のご意見はございましたけれども、全体的に私どもは、５校で八潮の小中一貫校を設置していくことについて、八潮地域全体の方々の大きな反対はないと判断しています。","voiceIndex":321,"id":"exchange-139"},{"speaker":"南委員","kind":"確認","question":"それと、反対の声が個別にはあったけどという説明でありましたけれども、私はこの間の八潮の小中一貫校を急遽５校にして統合していくという方針の一連の動きの中で、改めてずっと調べてみますと、個別の意見はあったということですけれども、少なくとも品川区の教育委員会が設定したさまざまな説明会、あるいはＰＴＡの会長会議、協議会、そういうレベルであったと考えていますけど。","respondent":"古里学務課長","answer":"八潮の場合は、それぞれの小学校、中学校での保護者会にも私ども出向き、ご説明を申し上げ、一人ひとりのご意見を聞いてまいりましたから、その中で、１人、２人、反対という声があったということは、私ども承知していますが、全体では。","voiceIndex":323,"id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"ですから、この間の父母の説明の中でも、一貫校といったら八潮中、八潮小、こういう認識でずっと父母はいたはずです。指摘をしておきたいと思います。自治会連合会がこの間、何回か一貫校をつくったらどうか、あるいは統合したらどうか、そういう趣旨の要請をされていたやに聞いておりますけれども、そういう中で、教育委員会の答弁はどうだったんですか。平成１７年度までの教育委員会としての見解は。","respondent":"古里学務課長","answer":"昨年、平成１８年２月７日にプレス発表した際のものですが、八潮地区における小中一貫校と教育環境整備という文言の中に、新入学者の減少が著しい中学校の現状のもと、中学校の統合も視野に八潮地区における学校のあり方について、地域、保護者と協議し。","voiceIndex":325,"id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"それを急に５校統合だと言って、先ほども申し上げたように、レールをぐっと敷いていくのは、私はいかがなものかと。事実がそうですから、事実をよく見てください。こういう状況ですから、こういう事態ですから、どっちかをとらなきゃいけない。しかし、それが結果的にだめだったんじゃないですか。区民の声を聞く努力はどういうふうにしてきたんですか。されたんですか。どういうふうに検討したんでしょうか。","respondent":"古里学務課長","answer":"それぞれ学校関係者のご心配、地域のご心配、こうしたことを受けながら、状況の変化、新しく施策をご提供申し上げ、一貫校を設置するという状況の流れの中で、必要な対応をとってきているです。私どもは、八潮地区から学校という教育環境をなくすわけにいかない。","voiceIndex":327,"id":"exchange-142"},{"speaker":"南委員","kind":"質問","question":"４月４日の、これはＰＴＡ会長協議会第２回目、ここにはＰＴＡ会長が、「保護者の間には戸惑いもある。それが高じて不信感になっている場合もある。そのためには１カ月は短い」、こういうふうにも発言しているんですね。これは、区長が今年の施政方針でお述べになった見解とも全然違いますよね。こういうことに対して、区長は教育委員会のやり方をどういうふうにごらんになっておられるでしょうか。","respondent":"濱野区長","answer":"ただいまご指名いただきましたし、先ほどもタウンミーティングのお話がありましたので、お答え申し上げます。タウンミーティングの中でも感じましたけれども、今、八潮の皆さんの思いは、人口が大きく変わってきた中で、学校をどうやって地域のために活用していくんだろうか。","voiceIndex":329,"id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"私は、そういう意見もあることは承知しています。しかし、進め方について言っているんですよ。区長にそのことを質問したんですね。そこが出発点だと言っておきながら、区民の声を聞いてないじゃないですか。そういうことに対して見解を求めたのに、全然違うことを答弁する。もう少し時間をかけて、住民の声をしっかり受けとめて、平成２０年度の一貫校開始はやはり見直すべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":331,"id":"exchange-144"},{"speaker":"須藤委員","kind":"質問","question":"２９５ページの教育事情視察、２９７ページ、プラン２１関連事業に関連しまして、市民科と各教科の充実に関連して質問します。そのときに親御さんも生徒と一緒に見たときに、親御さんも非常に感動した。そういうしきたりというか、伝統というものを知らなかったというお話があったんですが、こういった江戸しぐさに関しては、市民科の教材として、品川区ではどういうふうにお考えでしょうか。","respondent":"吉村小中一貫教育担当課長","answer":"実際、私どものプログラムの中に江戸しぐさを教科書の中に入れているわけではありませんけれども、教科書はあくまでも教科書ですので、基本的な生活習慣であるとか、そういった内容を勉強するときに。","voiceIndex":333,"id":"exchange-145"},{"speaker":"須藤委員","kind":"質問","question":"江戸しぐさというのは、格好だけじゃなくて、言葉遣い、基本的には江戸の時代、百何十万人という、世界第一の都市で、皆さんが平和に暮らしていくための人のつき合い方というのを、いわゆる商人のまちだったから、商人の方々がいい形で生活していこうということからスタートしているというお話を聞いているんですけれども、そうすると、単に格好だけじゃなくて、言葉の使い方、隣近所とのつき合いの仕方。","respondent":"吉村小中一貫教育担当課長","answer":"実際、教科書は今つくったばかりですので、今すぐこれを改訂して、その部分を入れるということは難しいんですが、この市民科の教科書も当然何年かたっていきますと、改訂をしてまいります。","voiceIndex":335,"id":"exchange-146"},{"speaker":"須藤委員","kind":"質問・要望","question":"同じ２９７ページのふれあい教育、３００ページの学校管理費に関連いたしまして、今、小学校等ではペットを飼う、いわゆる小動物を飼って情操教育の一環でされていると思うんですが、区内ではどの程度、大抵は水槽の中にいたり、カメを飼ったり、ウサギを飼ったり、鳥を飼ったりというところを見るんですけれども、そのあたりは、区内ではどんな状況になっているんでしょうか。","respondent":"古里学務課長","answer":"学校における飼育動物ですが、現在、鳥類、爬虫類、魚類、哺乳類も当然ありますけれども、小学校２３校ぐらい、中学校でも二、三校、そうした飼育の状況があると把握しています。","voiceIndex":337,"id":"exchange-147"},{"speaker":"須藤委員","kind":"質問","question":"動物を飼うことによって、命の尊さとか情操教育ということで必要だろうと思うんですが、ただ、今、ペットを飼うと、この間テレビでやっていたんだけど、ペットの中で、小動物でカエルを飼ったら、ペット用のカエルにツボカビとかというのがはやっていて、それが表へ出ちゃうと、野性のカエルも全滅しちゃうよということが放送されていたんですけれども、そういったペット等についても。","respondent":"古里学務課長","answer":"生きるやさしさを育むという点でも、そうした獣医師の先生方のご指導、あるいは学校の中での授業等々、そういうこともトライしている学校も幾つもあると聞いております。","voiceIndex":339,"id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"今はボランティアでいろいろな応援をいただいているというお話でありますけれども、そのあたりを生かしていって、そういう仕組みづくりをされたらと思うんですが、いかがでしょうか。","respondent":"古里学務課長","answer":"委員ご発言の件につきましては、制度としてこうしたものがしっかり学校、それから獣医師の皆さんのご協力を得てできるような研究、検討を始めてまいりたいと思います。そういう意味で、ご提案について受けとめてまいりたいと思います。","voiceIndex":341,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問・要望","question":"ほかの地区でこういった仕組みづくりをされているというのは聞いてないので、そういったいろんな形で、獣医師会の先生方と連携をとって、まして、今言った学校でいろんな小動物を飼ったり、ペットのいろんな病気が出てきたりというような時期にあっては、そういった仕組みづくりを品川区でもつくられていったほうがいいと思うんですが、そのあたり、そういう方向性でというお話をいただいたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":343,"id":"exchange-150"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":115696,"voices":344}},{"id":"h19-20070319-3","meetingId":"h19-c-budget","date":"2007年3月19日","dateIso":"2007-03-19","committee":"予算特別委員会","time":"午前１０時０３分～午後６時３０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を102件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田委員","kind":"質問","question":"私は、来年度策定が予定されている新基本構想と平成２０年度に策定が予定されています第四次長期基本計画について伺います。基本構想は、昭和５１年７月、また昭和６３年４月に策定されていますが、今回の構想は、何年後をめどに将来像を考えて今いらっしゃるのか、期間を含め、どのように考えて策定していくのかをまず伺いたいと思います。","respondent":"新美企画部長","answer":"このような状況のもとで、これから策定をいたします構想、計画につきましても、この加速する環境の変化に迅速かつ柔軟に対応できるようにすることが重要ではないかと考えております。","voiceIndex":2,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"長期基本計画については、１０年間というと、めどの部分ではほとんど一緒ということがあります。これは要件がもしかすると大きく変わってくる話なのかなと思っておりまして、前提が変わってしまうわけでありますので、ここで何点かお伺いをしたいのは、ほかの委員会でもいろいろお話がありますが、都区のあり方で、今何に問題があると区長はお考えなのか、そこら辺の点をまずお聞かせを願いたい。","respondent":"濱野区長","answer":"今、委員お話のように、この１０年あるいは２０年、３０年後を視野に入れてということであれば、当然に今これから開始されようとしている都区のあり方検討会、これの結果の反映というものがその期間に入ってくるということになろうかと思います。","voiceIndex":4,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問","question":"次に質問しようと思っていたところに大分触れていただきまして、ありがとうございました。それを伺ってから、改めて聞きますが、今お話になった水平調整の話であります。それがある区は嫌だというのは当たり前であります。その引き受ける、嫌なものまで引き受ける体制をどうとるかというお考えが一つこれからあり方検討会、区長会でもお話をしていくんだろうと思いますので、そこの考え方が一つ。","respondent":"濱野区長","answer":"そしてまたもう一つは、財源の問題でありますけれども、これは議論が非常にこれから難しいことになってくるんだと思いますけれども、理想的にはやはり調整三税のうちの固定資産税を２３区が自前で徴収して。","voiceIndex":6,"id":"exchange-003"},{"speaker":"石田委員","kind":"質問","question":"この二つの関係をどう整理されていくのか。期間も伺うと、基本的には１０年、その中で長期基本計画は見直しをしていくということ、長期基本計画５年というのは、ちょっと私は見直しはもっと早くていいんだろうと考えていますが、そういう形の中で、その二つの関係をどう整理していくのかというのが、これから問われてくるのかなと考えています。","respondent":"新美企画部長","answer":"基本構想につきましては、理念、品川区の将来の都市像、そして、その達成に向けての基本方針など、大綱にとどめ、施策体系ですとか具体的政策、施策につきましては、長期基本計画の中でお示しをする、そういった関係でこれから検討を進めてまいりたいと考えているところです。","voiceIndex":8,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"そうすると、検討委員会というのが必ず双方、名前はどうあれ、検討委員会が持たれると思います。我々区議会、前回は両方入っておりましたけれども、私どもの須藤幹事長の質問の中でも、議決案件なので構想についてはというお話も少しありましたが、改めてそこら辺の、区議会がどうかかわっていくということを、双方どういうふうにお考えなのかというところもあわせてお聞かせ願いたいと思います。","respondent":"新美企画部長","answer":"そういう意味では、基本構想は、まさに１０年後の品川区像、それを幾つの都市像にするかということもありますが、そういった集約をして、それを実現するためにはどんな考え方でいくのか、施策の中身というよりは、基本的な方針といったようなもの、そこにとどめておき。","voiceIndex":10,"id":"exchange-005"},{"speaker":"石田委員","kind":"意見","question":"今、長期基本計画のほうの構成がちょっとなかったと思いますので、もう一度長期基本計画には議員が入っていくのかどうかというところもあわせてお聞かせ願いたいのと、あと、構成のメンバーの中で、長期基本計画のほうは行政側が委員として助役という名前で明確にうたって参加をしているわけでありますが、事務局は、もちろん事務局として入っていく部分と委員として入っていかれるという部分。","respondent":"新美企画部長","answer":"検討組織ですが、この２年間の検討の進め方を考えてみますと、基本構想と長期基本計画は、同一の検討組織で検討していくことが一番スムーズであり、効果的なのではないかと考えているところです。","voiceIndex":12,"id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"これはこれからまた皆さんと話していく話でしょうから、これは私の個人的な考えにもなるかもしれませんが、構想自体は、議員は議決という一つの我々区議会に与えられた権利があるわけですから、それについては、私は議員が入らなくてもいいと考えていますが、計画については、私は議員が参加をやっぱりするべきだろうと考えていますし、先ほど言ったように。","respondent":"濱野区長","answer":"一つは、これは議会のことですから、私から申し上げるのは越権かもしれませんが、特別委員会なりというものが設置されるのかどうなのかわかりませんが、１０年に１度のことでありますので、議会としてもいろいろな検討の体制がとられるのではないだろうか。","voiceIndex":14,"id":"exchange-007"},{"speaker":"石田委員","kind":"質問","question":"こういう言葉を使うと、１００年単位で考えているのかなというふうに読める形だなと考えています。ここら辺の「５つの都市像」、今言った全体の「平和で」という部分を含めて、ここら辺を前提にやっぱり今考えていこうとされているのか、やっぱり、これは一から構想も計画ももう一度つくり変えるんだという強い意思であるなら、１回さらにして考えていこうとされているのかをお伺いしたい。","respondent":"新美企画部長","answer":"今後の主要な、特に７つのプランに当たりますような横断的なテーマについて、どのようなものを重要と考えているかというご質問ですが、まず一つは、やはり少子社会への対応、それから、高齢社会への対応、少子高齢化ということにどう向かっていくかです。","voiceIndex":16,"id":"exchange-008"},{"speaker":"石田委員","kind":"質問","question":"ですが、子どもを育てるという部分をしっかりとらえる。未婚化が進む中、今、子育て支援はたくさんやっていますけれども、未婚の方の部分にも、ある程度今は行政側が手を入れているのはたぶんゼロに等しいぐらいのところがあると思いますが、未婚の方々の精神的、ソフトの部分で変えていけるというところも入れ込んでいくべきだろうと考えていますが、そこら辺の点はどう考えていらっしゃるのか。","respondent":"新美企画部長","answer":"その際、結婚に対するといいますか、未婚の方への結婚への支援といった部分をどう考えているかということかと思いますけれども、これから具体的にはこれからの第四次長期基本計画の中で具体策を考えていくわけですが、そういう意味では、第四次長期基本計画は。","voiceIndex":18,"id":"exchange-009"},{"speaker":"石田委員","kind":"質問・要望","question":"高齢者の部分は、もう一点お聞きをしたいのは、今地域でよろず相談所も含めて、介護予防、お元気で高齢者の方も常にいていただきたい。介護予防等の、そういう施設等も地域で頑張ってやってくださいよというのもあるでしょう。それから、不幸にしていろいろご病気になったり、認知症とかになった。","respondent":"新美企画部長","answer":"そういった中におきまして、区として公的な介護施設、これをきちんと計画的に増設していく、これは当然必要な重要施策であるというふうに考えているところです。","voiceIndex":20,"id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"そうなってくると、私は今回のマウント品川も含めて、都会の人はたくさんいるわけだから、都会の人がそういう早川町なり、山北町なりに出ていって、一つそういう品川区の施策として打っていくことによって、それで国を動かしていくんだ、都を動かしていくんだ、そういうきっかけづくりの施策をこれから環境については、啓発以外のところでやっていかざるを得ないんだろうと私は思っていますが。","respondent":"新美企画部長","answer":"具体的には、まさにこれから今までやってきたことを踏まえつつも、新たな展開をどう考えていくかということについては第四次長期基本計画の中で検討をしてまいりたいというふうに考えております。","voiceIndex":22,"id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"最後に聞きますが、これからその構想等を考えていく中で、計画もそうですが、私はやっぱり自助、共助、公助、これは区長もよくおっしゃっていますが、その役割分担、そこの部分にどれだけ入れていくんだ。ここら辺の役割分担について、区長も施政方針でも述べられておりますが、最後にどのようにここら辺を明確に役割分担していくというお考えをお持ちなのかお聞きして、私の質問を終わりたいと思います。","respondent":"濱野区長","answer":"そういう意味では、非常に難しい分野だというふうな認識をしておりますけれども、しかし、これからの時代は、自助の欠けた部分をいきなり公助が働くということではなくて、共助の力をどれだけ発揮できるか、これが自治体としての大きな試金石というか。","voiceIndex":24,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"確認","question":"年齢はそうかもしれませんが、その多くの方々がお持ちの知識や経験やノウハウを次にどうつなげていくかということを考えてまいりますと、このアンケートの結果の集約、それから評価、分析等については、一つのアイデアとしては、企画財政課の中に係を設けて、そこの中で全庁の方々がかかわり合いをする中でこのアンケートを評価すべきと思いますが、いかがでしょうか、お答えをお願いいたします。","respondent":"木下福祉高齢事業部長","answer":"手法については、いろいろな面で確立している部分もありますので、その専門的な調査機関、あるいはコンサルタントを活用しながら進めてまいりますけれども、今ご提案がございましたように。","voiceIndex":27,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この世代の方々の中には、非常に優秀な知識と経験をお持ちの方もたくさんいらっしゃると思います。例えば、そういうところに非常に自治体というノウハウにたけた方をお迎えしていくとか、あるいは場合によっては、品川区の非常勤職員の中で対応していくとか、いろんな分野でこういうパワーを生かす体制を構築していくべきと思いますが、いかがでしょうか、答弁をお願いいたします。","respondent":"新美企画部長、本間助役","answer":"現在そちらでボランティア、ＮＰＯ法人等との連携協力の仕組みづくりというテーマで検討を全庁的に進めておりますが、その検討テーマと今回の調査は大変共通する部分が多いわけでございまして。後段のほうの団塊の豊富な知識経験を区政に生かしていくべきではないかというお話ですが、まさに私どももそういう観点でこれから非常に重要になってくるというふうな認識を持ってあります。","voiceIndex":29,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"その中で、例えば趣味であるとか、スポーツサークルのこと、それから、コミュニティビジネスのこと等々たくさんの要望なりニーズを引き出した上で、具体的にそれを例えば定年後の総合的人生設計、それからボランティアやＮＰＯ、コミュニティビジネスの参加等々のシンポジウムを足立区が主催で開催をしたということを聞いております。ご答弁をお願いします。","respondent":"新美企画部長","answer":"これからの施策、それからご質問にありましたように、仕組みといった全体的な体系的な取り組みといったことにつきましては、調査結果を踏まえて、ちょうど第四次長期基本計画の検討をするときでもあり、地域のこれからの戦力、ボランティアであれ、就業をしていただくのであれ。","voiceIndex":32,"id":"exchange-015"},{"speaker":"伊藤委員","kind":"確認","question":"団塊の世代の方々としては昭和２２年から２４年生まれなんでしょうけれども、つまりこれだけの方々が今で言う定数の４割前後が品川区の職員は入れ替わるということでありますので、それに伴いまして確認したいのが、長年品川区にお勤めで知識があり、経験ある方が退職なさっていかれるわけでありまして、その知識や経験、区民サービスへの具体的な継続についてはどのように担保されていかれるのかということ。","respondent":"本間助役","answer":"２点目の新規採用職員ですが、当然ながら、これからこういう団塊の世代の退職に当たりまして、必要な人員につきましては新規採用してまいりますが、いずれにいたしましても、少数精鋭で効率的な組織運営をしていくということは今後も維持をしてまいりますので、今いる若手の職員。","voiceIndex":34,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それから次に、指定管理者制度につきまして、質問をします。このことについては、一つの経過であると考えていますし、そうしなければいけないということもあったわけですから置いておきまして、むしろ、これからのことを考えていかなければならないと考えています。つまり、民間の視点でそれを行う仕組みづくりは、どうしも必要だと私は思っております。お願いします。","respondent":"新美企画部長","answer":"ただ、ご質問の品川文化振興事業団とか福栄会という従来の管理委託の受託法人につきましては、当然継続性の部分とともに、区のその他の政策、つまり施設管理のみならず、それに伴う文化政策ですとか、あるいは福祉政策ですとか。","voiceIndex":36,"id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確認したいのが、そうなってまいりますと、民間の市場をある程度行政は勉強し把握しながら、区が求めるサービス水準、費用、事業内容等について公開をし、民間企業が対等の立場で入札しやすい環境整備といつも書いてあるんですけれども、こういうことになる前提のところが、非常に品川区の対応がもう少しという感があります。","respondent":"新美企画部長","answer":"４点目がその同じ業務も、例えば会議だったり、打ち合わせだったり、書類を作成するといったいろいろな実際の活動を含んでおりますので、その中で職員が必ず実施する必要があることなのかどうかというような観点から現在。","voiceIndex":38,"id":"exchange-018"},{"speaker":"伊藤委員","kind":"確認","question":"それはそれで評価するんですが、当然指定管理者制度全体の見直し、先ほどもお話しした入り口から出口までの間の見直しは、例えば３年後と５年後と区切って行っていくと思われますので、そのことについての確認の答弁をお願いしたいのと、それから指定管理をした後の業者の評価、これも同じように５年、３年とあるわけですけれども、業者の評価をどのように行って。","respondent":"新美企画部長","answer":"指定期間の中で、年々以外にどのような見直しをするかということにつきましては、経営会議の中で、それぞれの指定期間が３年間終了した時点で３年間をトータルに評価し、今後の方向について検証検討する機会を設ける予定です。","voiceIndex":40,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"質問","question":"部長の答弁の中に難しいというお話がありましたけれども、確かに難しいことだと思います。次に都市型水害対策等について質問をします。ご承知のように今年は暖冬でありまして、非常に気象がおかしいということとか、それからあと、地球温暖化とか叫ばれております。そういうことを考えてまいりますと、目黒川、立会川と二つの川を品川区は抱えています。すぐにはもちろんできないと思います。","respondent":"岩田まちづくり事業部次長","answer":"今後もケーブルテレビというような媒体も使ったり、あるいは防災無線を活用したり、今後いろんなメディアが開発されてまいりますので、そういったものを使いながら、区民の方の情報提供というのは検討してまいりたいと思います。","voiceIndex":42,"id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"日本共産党品川区議団を代表して、総括質問を行ってまいります。今私ども区議団でもアンケートをいただいておりまして、この中で特別養護老人ホームなど、高齢者施設、これらにかかわる問題についても多くの要望やあるいはそれぞれの生活にかかわる記載が行われています。記載をされた文章の一つをまず紹介したいと思います。品川区内で収入に合った施設をつくってほしいと思います。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホームに関するお尋ねですけれども、私どもといたしましては、やはり高齢者施策、サービスを必要とする高齢者の方々に対しまして、適切なケアマネジメントのもと。","voiceIndex":49,"id":"exchange-021"},{"speaker":"菊地委員","kind":"質問・要望","question":"今の年齢構成、それから介護度を聞く限り、よほどの事情がない限りは相当高齢になっていかない限りなかなか特養には入所できないというのがよくわかる数字になっていると思います。もう一点お聞きしたいのは、今お知らせをいただいたこの９４名の方で、在宅から入所された、こういう方が何名いるのか、このことも教えていただきたいと思います。","respondent":"木下福祉高齢事業部長","answer":"特別養護老人ホーム、区内の施設に９４名の方が入られましたけれども、その方々の入所前の居所ということで、在宅の方が６５人、約７０％弱です。それから、申し込みをされた方ですけど、約４５０名の申請がある中で、在宅の方は約１５０名という数字になっているところです。","voiceIndex":51,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、今の入所基準で見ますと、病院や老健に入っている方、かなり在宅介護の状況そのものが現実的にはないわけですから、介護の困難性、こういったものも今の入所基準で見ますとないことになりますけれども、こういう状態だと、入所というのはよほどの事情がない限りは、永久に不可能になるというふうに考えますけれども、ちょっとその辺をお聞かせ願いたいのと、在宅の入所希望者。","respondent":"木下福祉高齢事業部長","answer":"それからあと、いわゆる入所、既に病院等に入っている方については、最近胃瘻とか、それから鼻腔栄養、経管栄養というような医療行為が必要な方が非常に増えてきているというのも。","voiceIndex":53,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"老健なんかに入っておられる皆さんにとってみれば、最初からいわゆる最高基準でもその時点では８０点という基準のところから審査がされるということになると思うんですけれども、病院や老健に入っていらっしゃる方は、実際に今の私が申し上げているこの四つの項目の中で、２項目で審査をされるのか、それとも３項目で審査をされるのか、それとも４項目で審査をされるのか。","respondent":"木下福祉高齢事業部長","answer":"入所調整基準は大きく四つの柱があるわけでありますけれども、いわゆる老健等に入所されている方については先の三つの項目、この部分で評価をしています。","voiceIndex":55,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"三つの項目だということであれば、在宅の方は１００点を基準にして点数がつけられていくと。鈴木（ひ）委員が以前に本会議の一般質問で紹介をしていましたけれども、介護を要する父親と、３人のお子さんを抱えて、特養に入所ができずにやむなく老健に入院させましたけれども、結局は半年ごとに転々とせざるを得ない。これでどうして基盤整備が済んでいるのか、その辺をお聞かせ願いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"三多摩を含めますと、今９８０人の方が特養に入っておられるような状況の中で、私どもはやはり多様な選択肢を用意するという考え方で、この間ケアホームも進めてまいりました。これは有料老人ホームとは性格が私は違うというふうに思っております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"ですから、品川区の整備率で言えば、高齢者人口の比率で、東京２３区でこれまで１８番目というふうに話をしてきましたけれども、これがさらに低くなって、２０番目になっています。約４割ぐらいですか。むしろ基盤整備をしたんではなくて、他の自治体に、ちょっと言葉は悪いですけれども、他の自治体へ放り投げた感じになっているんじゃないでしょうか。そこをぜひお聞かせを願いたいと思います。","respondent":"木下福祉高齢事業部長","answer":"特養の整備率のお話がございましたけれども、特養はどちらかというと、かなり広域的な施設だというふうに私思っておりまして、そういう点では、三多摩のほうも確かに時間的には多少かかりますけれども、適切なケアをしている施設、そういう部分については紹介をさせていただいて。","voiceIndex":59,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"今広域的な施設というふうな話をされましたけれども、広域的な施設だということであれば、例えば品川区内にある５７２床ですか、ここには他区からの皆さんを受け入れておられるということなんでしょうか。そこを１点お聞きしたい。こういう答弁がありましたけれども、品川区だけが行政として２０万円から３０万円ぐらいかかる、こういうケアホームを建設しているんだということになると思うんですね。","respondent":"木下福祉高齢事業部長","answer":"ケアホームについての考え方でありますけれども、私ども特養の基盤整備は平成１２年まで、これも２３区の中では非常に早かったわけですけれども、基盤整備をしてまいりました。","voiceIndex":61,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"特別養護老人ホームはある程度、７万円、今の状況で７万円ぐらいあれば入所ができるという施設ですけれども、ケアホームについて言えば、高優賃を使って安くなったにしても、２０万円からかかるというふうに聞いていますので、何らかの制度を使って特養にしか入るような収入がない、こういう皆さんが入所できるのかどうか、そこのところを先ほどお聞きしたので、その辺を明確にお答え願えますか。","respondent":"木下福祉高齢事業部長","answer":"私ども、やはり特別養護老人ホームあるいはケアホーム、グループホーム、それぞれのご家族の方の収入の状況あるいは身体状況、それらを踏まえまして適切な施設のほうにつないでいくという考え方に立っているです。","voiceIndex":63,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問","question":"収入に応じて施設のほうにつないでいく。それができないのに保険料をとっているわけですから、私は今のご答弁というのは、区民の信頼を大もとから崩すものだというふうに思います。お金がないんだから、お金がないんだったら、在宅でぎりぎりまで我慢をしろと。お金のあるなしで高齢者福祉に、介護の提供に差がつくのは当たり前だという考え方なのかどうかをお聞かせ願います。","respondent":"木下福祉高齢事業部長","answer":"その辺のバランスを見ながら、すべての方にご満足いただけるような介護保険制度の運営について、これからも私どもは努力をしていきたいというふうに考えているところです。","voiceIndex":65,"id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"私、住民の皆さんと一緒に都南病院跡地に特別養護老人ホームをつくってほしい、こういう運動を進めてきましたけれども、この運動の中で、成人式の日に振り袖姿の新成人がたくさん署名してくださったことがあります。それでお聞きしたいんですが、北品川以外に６９０億円に含まれていない新しい補助金などがありましたら、お聞かせを願いたいというふうに思います。","respondent":"福田まちづくり事業部長","answer":"住宅ですが、これは品川区が関与している再開発でございまして、現在竣工済みのものが４,７００戸、それから、これから竣工または計画中のものが４,６００戸、合計で９,３００戸です。","voiceIndex":67,"id":"exchange-030"},{"speaker":"菊地委員","kind":"意見","question":"北品川五丁目の第一地区でも先日の答弁で、３００名からの居住者がいるということですけれども、住民がいなくなっていくまちの中で、公共施設整備を理由に膨大な補助金が投入をされる、こういう開発を続けることは、私は数十年先を全く見ていないのではないか、このように思いますけれども、この点についても考えをお聞かせ願えればと思います。","respondent":"福田まちづくり事業部長","answer":"緑道と歩行者通路が２,８００ｍ、公園は２万４,５００m2、歩道上空地は、長さで言いますと２,５８０ｍ、累積換算では１万１,８００ｍ、こういうような公共事業が整備をされてまいりました。","voiceIndex":69,"id":"exchange-031"},{"speaker":"菊地委員","kind":"意見","question":"品川区は、開発が行われてきた地域へ、やっぱりもっともっと品川全域も含めてですけれども、もっときちんと目を向けるべきではないかなというふうに思っています。今、規模の小さなオフィスなんかでは、空き部屋が目立っていますし、商店街では款別でも述べたように厳しい状況、これがさらに悪化をしている。商店も、それから工業の事業所も減少の一途をたどっている。","respondent":"福田まちづくり事業部長","answer":"緊急整備地域ですが、これは大崎、五反田、あの辺に限られた地域ではありますけれども、品川区といたしましては、あの指定を受けまして、大井町駅との都市軸の形成に努めていきたいというふうに思っておりますし、それ以外にも、あの地域において発生する雇用や消費。","voiceIndex":71,"id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"このことは意見として述べておきます。合意形成の問題についてお聞きしますけれども、私はこうした開発に対して合意形成のシステムをきちんとつくるべきなんだというふうに思っています。政府資料によると、再開発事業単体の場合、素案から都市計画決定まで平均で約２年、それから決定後の事業認可に８カ月を要するということだそうです。","respondent":"福田まちづくり事業部長","answer":"この現状を通しまして、周辺の方たちの意見は吸い上げられていると、このように認識しております。","voiceIndex":73,"id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"要は自分の権利を縮小してでも、住みよい地域であってほしい、こういう願いが込められているんだというふうに思いますけれども、区民の皆さんの真のニーズにこたえた本来のまちづくりを進める、こういう意味で言えば、民間のビジネスになるような再開発事業の進め方ではなくて、区民がまちの将来を論議し合える、こういうシステムづくりをぜひ進めていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-034"},{"speaker":"中島委員","kind":"質問","question":"質問は大きく分けて子育て支援、中高年者の健康増進および予防、税について、建築行政、そして交通安全の５点に関連して質疑を行います。初めに、子育て支援の中の親育ち支援についてお伺いいたします。そうしたことを踏まえ、私は親育ち支援の中にも、単なる子育ての精神的負担を軽減するだけでなく、親子ともにたくましく成長する支援を工夫していくべきと考えますが、区のご見解をお伺いいたします。","respondent":"古川児童保健事業部長","answer":"行政がややもしますと、大変行き過ぎてしまう部分もありますけれども、この状況をとらえたときに、区といたしましては、親が育っていくためにどのような支援ができるか、こういう観点から新年度、新しい事業として立ち上げたものでありまして。","voiceIndex":79,"id":"exchange-035"},{"speaker":"中島委員","kind":"提案","question":"私は平成１４年第４回定例会において、お茶の水女子大学藤原正彦教授の「桜を自分の命とつなげて見ることができる日本人の他の国の人にはない繊細な感覚、力は学校だけではなく、子どもが外で遊び、自然に触れることによって育つ」と言われた言葉を紹介しながら、生きる力や感受性を育てるセカンドスクールの創設について提案したことがありますが、今部長がおっしゃられました親と子が生きる力をつける。","respondent":"山田区民生活事業部長","answer":"今回私どもが導入しております早川町における「丸山」事業におきましても、区民の皆様方からどんな活用ができるか調査を含めて、自分たちが考えていく、自主的な活動を主体にした区民参加型の事業としてとらえておりますので。","voiceIndex":81,"id":"exchange-036"},{"speaker":"中島委員","kind":"質問・要望","question":"中学３年修了まで拡大されました子どもすこやか医療費助成制度でありますが、公明党は、昭和６１年から乳幼児の医療費に対する助成制度の創設をどこよりも早く要望し、平成４年３月には我が党の浜四津敏子参議院議員と女性の代表が高橋前区長に会い、直接その制度の創設を要望しました。ところで、子どもすこやか医療費助成の財源についてでありますが、東京都の補助金から財調へ振り替わったと伺いました。","respondent":"古川児童保健事業部長、濱野区長","answer":"したがいまして、今後は区の一般財源としてこの医療費助成制度については支出をしていくと、このように変わってあります。いずれにいたしましても、こういった問題は、財源の問題を十分に考慮しながら進めていく事柄でございまして、そういう時機に応じた財源の手当を考えながら、物事を決めていきたい、こんなふうに思っているところであります。","voiceIndex":83,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"ところで、すこやか子ども医療費助成では、外来、入院を問わず、すべての保険医療の自己負担額が助成されますが、先日区民の方から子どもの歯の矯正には適用されないのですかという質問がありました。相談された方のお話では、早期治療でも２０万円ぐらいかかるそうです。区として、品川の子どもたちの現状をどのように把握されておられますでしょうか。","respondent":"宮本品川区保健センター所長","answer":"平成１７年度のデータで申し上げますと、３歳のお子さんで約１０％、小中学生ですと５％ぐらいが歯並びとか咬合が悪いと、そういう異常のある方が指摘されているところです。","voiceIndex":86,"id":"exchange-038"},{"speaker":"中島委員","kind":"質問・要望","question":"歯並びが悪いと物を食べるときだけでなく、話をするとき、またときには精神的にも自信をなくすなど、多くの影響が考えられます。子どものうちに矯正すれば、比較的治しやすく、将来健康な歯を維持するためにも大事であると聞いております。今後、保険適用について国や都に働きかけるとともに、区としても公費助成も幾分か考えていただきたいと思いますが、いかがでしょうか。","respondent":"宮本品川区保健センター所長","answer":"そうは申しましても、区といたしましても、やはり、予防は大事というふうに思っておりますので、今後ともその観点で事業の充実あるいは普及啓発に一層取り組んでまいりたいと考えています。","voiceIndex":88,"id":"exchange-039"},{"speaker":"中島委員","kind":"提案","question":"いろいろな形でご検討いただきたいことを要望しておきたいと思います。次に、子育て支援の立場から、妊産婦無料健診についてお伺いいたします。こうしたことを受けて、愛知県の大府市では、早速これまでの１回から一気に１５回に増やす予算を編成するなど、動きが出てまいりましたが、品川区では、この変化をどうとらえておられるか、お考えをお聞かせいただきたいと思います。","respondent":"古川児童保健事業部長","answer":"その中におきまして、今後原則５回の実施に向けた検討をしてまいりたいと、このように考えてあります。","voiceIndex":90,"id":"exchange-040"},{"speaker":"中島委員","kind":"提案","question":"私は平成１３年３月の予算特別委員会において、学校の建て替えやプール改修の折に、子どもたちの運動量不足を解消するためと、元気な高齢者づくりのために屋内プールの設置を要望してまいりました。幸い、このたび、二つ目の小中一貫校伊藤学園に屋内プールが設置され、一般開放もされると伺っております。そこでぜひここでも水中散歩教室の開設を要望したいと思いますが、ご見解をお聞かせください。","respondent":"古川児童保健事業部長","answer":"私どもといたしましては、既に先行している他のプールでの水中散歩教室と同様に、この伊藤学園のプールを使った教室を今後可能な限り開設していきたいと、このように考えてあります。","voiceIndex":92,"id":"exchange-041"},{"speaker":"中島委員","kind":"質問・要望","question":"多くの方が参加しやすい運営を要望しておきたいと思いますが、同じく高齢者の健康ということに関連しまして、款別審査でも出ておりましたが、肺炎球菌ワクチン接種の公費助成、これが出ておりました。そこで公費負担を実施している自治体の様子などを積極的に確認され、有効とあれば、品川区におかれましても公費助成を検討されることもあってもいいのかなと考えていますが、ご見解をお聞かせください。","respondent":"青山品川区保健所長","answer":"今後予防接種の効果や費用助成につきましては、国の予防接種に関する検討会での検討を見守ってまいりたいと思いますが、口腔ケア等の予防策の普及啓発を含む取り組みについては、さらに強化してまいります。","voiceIndex":94,"id":"exchange-042"},{"speaker":"中島委員","kind":"質問・要望","question":"高齢者の健康ということがやはり医療費の削減にもつながると思いますので、検討をよろしくお願いしたいと思います。単純に読んでしまいますと、区が求める税負担は基本的には変わらない。そこで明確にしていきたいのですが、そもそもこの定率減税は、いつどのようなときに、どのような目的で設定されたのか、そして、今回なぜ廃止されるようになったのか、まずご説明いただきたいと思います。","respondent":"早津区民生活事業部次長","answer":"定率減税の廃止にかかわるご質問です。平成１９年度に廃止を予定しております定率減税につきましては、導入されたのは平成１１年度です。","voiceIndex":96,"id":"exchange-043"},{"speaker":"中島委員","kind":"質問・要望","question":"しかも、これは臨時特例の減税、すなわち景気が安定するまでの特例的な措置であったと認識しております。現実、私もこれまでの不景気の中で、定率減税によって随分助かったという声も聞いております。ところで、この定率減税の見直しで生じる財源が、基礎年金財源に活用されると聞いておりますが、それは私たちの生活の上で、どのように反映されるのか教えていただきたいと思います。","respondent":"早津区民生活事業部次長","answer":"定率減税の見直しに伴います国庫増収分の取り扱いですが、現在基礎年金の国庫負担分の引き上げが段階的に実施されております。","voiceIndex":98,"id":"exchange-044"},{"speaker":"中島委員","kind":"質問・要望","question":"はい、わかりました。続きまして、建築行政についてお伺いいたします。現実に、私のところにも相談が幾つかありました。ところが、その解決を求める場合、売主が不動産会社だったりして、その対応は決してスムーズではありません。このような確認審査は民間でも行えると聞いておりますが、区としてはどこまでの責任があるのでしょうか。昨年国の基準も変わったようですので、あわせてお知らせください。","respondent":"岩田まちづくり事業部次長","answer":"欠陥住宅の対応につきましては、委員ご指摘のように平成１２年に建築基準法が改正になりまして、民間においても建築確認ができるということになっておりまして、当然民間の確認検査機関が確認をした物件について、何らかの問題があった場合には、その責は。","voiceIndex":101,"id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"本当に若い方たちで一生懸命家を購入しているという方たちのためにということで、今回国のほうでも先ほど言われたんでしょうか、特定住宅瑕疵担保責任履行確保等法案、すべての新築住宅の売主に対して、欠陥が発覚したとき、確実に補償ができるように保険加入か法務局への補償金供託を義務づけると、こういったものが今年の秋ごろに施行の兆しが見えていると伺っております。","respondent":"岩田まちづくり事業部次長","answer":"区のほうの人材確保ですけれども、特に建築関係の技術的な人材を確保するのは、短期的には非常に難しいものですので、長い時間がかかりますけれども、私どものほうの建築職員の人事異動や配置等を工夫いたしまして。","voiceIndex":103,"id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"今後ともどうぞよろしくお願いしたいと思います。次に、交通安全についてお伺いいたします。品川区交通安全対策会議では、平成１８年度から２２年度までの第８次品川区交通安全計画を示されております。ここ数年の区内で発生した交通事故の状況およびその主な原因、またこれからの見直し等も含めた対策があればお知らせいただきたいと思います。","respondent":"岩田まちづくり事業部次長","answer":"これは、いわゆる統計上表に出てこない、いわゆる交通事故として扱われていない軽微な接触事故とか、こういったものが特に裏通りでは多いものですので、私どものほうでは、こういった裏通りの交通安全対策として交差点改良とか、あるいはカーブミラーの設置等。","voiceIndex":105,"id":"exchange-047"},{"speaker":"中島委員","kind":"質問・要望","question":"集中して幹線道路に多いということで、最近幹線道路でも信号の時間が短過ぎて渡り切れないという、そうした要望も出ておりますが、そうしたところの見直し等も今後されていくのかなと思います。それとともに、区内には幅員が狭くて、あまり車が通らないところに信号がしっかりついているところがあります。あわせて区としての対策とお考えをお聞かせください。","respondent":"岩田まちづくり事業部次長","answer":"それで、３番目に若者による暴走運転、どれも問題なわけですけれども、やっぱりそれぞれこういう実態をきちっと警察はとらえておりますので、そのターゲットに合ったところへうまくＰＲをしていかないと、なかなか浸透していかないということもありますので。","voiceIndex":107,"id":"exchange-048"},{"speaker":"中島委員","kind":"質問・要望","question":"ぜひ運転される方にもそういったことも頭の中に入れて運転していただきたいなと、こんなふうに思っております。次に、通学路についてでありますけど、本年は品川区小中一貫校６校構想のうち、既に２校目、伊藤学園が４月の入学を待っております。こうした通学路の設定に当たっては、どのようなプロセスを踏まれているのかお知らせください。","respondent":"長田教育次長","answer":"この最終原案に基づきまして、１月、２月には町会長会議での説明あるいはスクールゾーンにかかわる方々に対する説明と協力要請を行ってあります。","voiceIndex":109,"id":"exchange-049"},{"speaker":"中島委員","kind":"質問","question":"相談がありました。ですから、やはり、地域や学校、そしてこういったところと協議されてきたことはわかりましたけれど、その際、教育委員会と管理工事課、また特に交通課との連携というのは、しっかりとっていくべきではないかなと思います。そのために、しばらくの間見守りを強化してほしいという声も届いているわけなんです。この点については、どのようにされるか、ご見解をお伺いします。","respondent":"長田教育次長","answer":"学校が始まって慣れる間、３カ月程度の見守りの箇所を増やしてというようなことの要請が来ております。これについて、現在できるだけそうした対応ができるように前向きで検討していますので、期待をしてもらってよろしいかというふうに思ってあります。","voiceIndex":111,"id":"exchange-050"},{"speaker":"中島委員","kind":"質問","question":"そこで、今後見守り体制をお考えいただけるということで、それでいいのかなと思いますが、一定期間、やはり制服を着た人が立っていないと、通ってはいけない車が、父兄の方だけだとどうしても車がそれを無視して通ってしまうということなので、緑のおばさんとか、制服を着た方がそこできちっとここは通学路ですよと言っていただくことが大事かなと思いますので、その点はお考えいただいていますでしょうか。","respondent":"長田教育次長","answer":"それから先ほど一つ忘れましたけれども、まちづくり事業部のほうとも連携をしていまして、この通学路にかかるガードレールですとか、巻き込み防止の新設、それから危険箇所を知らせるマーク等、これにつきましては、３月いっぱいですべて完了される予定です。","voiceIndex":113,"id":"exchange-051"},{"speaker":"中島委員","kind":"質問・要望","question":"いろいろ通学途中の痛ましい事故から児童・生徒を守るために、十分に安全を確保していただくことを強く要望いたしまして、私の総括質疑を終了いたします。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-052"},{"speaker":"大西委員","kind":"提案","question":"そういう点で、私は少し先ほどいろんな区がいろいろ団塊の世代の方々にかかわっていくということがありましたが、私は区が大きな土俵みたいなものを準備される、要するに団塊バンクのようなものですかね、団塊の皆さんがどんどんそこに集まってきて、そして、その団塊の皆さんで自分たちがこれからの生活をどのようにやっていくか、地域にどう貢献できるか、濱野新区長が言われておりました品川。","respondent":"山田区民生活事業部長、木下福祉高齢事業部長","answer":"５歳刻みですので、昭和２２年から２４年生まれを団塊というふうにくくってはありますが、この統計によりますと、５５歳から５９歳ということで、２万７,１９０人、こちらが品川区の人口です。スタートしたばかりでありますけれども、今後そういう方向で拡充をしていきたいというふうに考えております。","voiceIndex":118,"id":"exchange-053"},{"speaker":"大西委員","kind":"質問・要望","question":"ひったくり、空き巣、さまざまな形で起こる。そういう意味で、その独自の、その人たちにどうぞという形での、少し私はシニアネットとは違う、本当にその方たちだけで考えてもらう、それだけの能力のある人たちが私は先ほどの答弁で２万７,０００人とあったでしょうか、それだけの方々がおられれば、すばらしい能力集団になってくるんじゃないかな。例えば１日３,０００円でもいいんじゃないでしょうか。","respondent":"山田区民生活事業部長","answer":"これは私ども想像していなかったんですけれども、ここまで防犯リーダーとして、本当に自主的な、ボランティア活動が生み出された、ここに着眼いたしまして、やはり。","voiceIndex":121,"id":"exchange-054"},{"speaker":"大西委員","kind":"質問・要望","question":"配食制度にしてみても、今までは週に２回だ。そして、そこに行ったとしても、もし６人の定員枠でしょうか、今は。先般保育課長が言われていましたが、私は耐震問題とかで増設できるところはスペースを拡大しようということ等もあるように聞いていますが、その２点、３日前という原則の見直し、それとオアシスルームの増設、要するにサービスを開始するかどうかということについてお伺いしたいと思います。","respondent":"山田区民生活事業部長、古川児童保健事業部長","answer":"まさに団塊の方たちが受け皿となるような年代層が既に動いて、自分たちのアイデアで自分たちの１３８団体をつくり、５,０００人を組織したという力を持っているというふうに私どもも認識をしています。児童センターを使うことによって、若干定数の増も図れるし、基本的な教育環境、保育環境もよくなるだろう、こう思っておりますので、今後ともこのオアシスルームについては、在宅子育て支援の主要な柱として内容は充実させていきたい。","voiceIndex":123,"id":"exchange-055"},{"speaker":"大西委員","kind":"質問・要望","question":"１点どうも気がかりなのが、やはり配食サービスでありまして、８割の方々が今ので満足している、もっと満足する部分があるんじゃないかなということと、２割の方々がひょっとして欲しているんじゃないかなと。その２割の方々からすると、まさしくその配食が、ひょっとしたら食の意味においてのライフラインかもしれない。別に８割の方々で要らないという人たちには２食でいいんじゃないでしょうか。","respondent":"山田区民生活事業部長","answer":"あまり欲しいからすべてやるということが、その方おひとりおひとりの将来の体力的なこと、予防のことを考えたときに望ましいかどうかという観点もありますので、新しい問題提起については、これからも研究はしてまいりますが。","voiceIndex":126,"id":"exchange-056"},{"speaker":"大西委員","kind":"質問・要望","question":"私が言いたいのは、いいですか、残存能力といいますけど、２１食中の５食を提供する用意をしたらどうかということを言っているので、２１食中全部を配食してくださいということを申し上げているんじゃないんですよ。思いやりがないとは言っていない。一つ、今後課題にしておいていただきたいと思います。そして、何らかの新しい収穫があったかどうかをお尋ねしたいと思います。","respondent":"濱野区長","answer":"私が出かけていったということですので私からお答えをさせていただきたいと思うんですが、タウンミーティングを始めたいというふうに思ったときに、どこからということを考えたときに、私一つのことを思い出しまして、それはかつて八潮の自治会の会長から。","voiceIndex":128,"id":"exchange-057"},{"speaker":"大西委員","kind":"質問","question":"続きまして、教育の問題に入ります。本日は若月教育長が欠席で、大変教育次長には厳しい質問になろうかなというふうに思いますが、ご容赦いただきたく存じます。ＣＡＰについてお尋ねします。いじめ、自殺等があります。先般、私が決算特別委員会でしたでしょうか、質問では、中学生のＣＡＰがないということで、その後他の委員から中学生でもＣＡＰはありますよという指摘をいただきました。","respondent":"長田教育次長","answer":"その三つの理由というのは、まず１点目は内容的に過激な部分があるというのが１点目です。それから、２点目は、このＣＡＰに要する時間ですけれども、かなりの時間数を要して、今の教育課程の中に取り組むことがなかなか難しいというのが２点目です。","voiceIndex":130,"id":"exchange-058"},{"speaker":"大西委員","kind":"質問","question":"今ちょっと答弁で抜けていたのが、まずどの学年でそういう学級崩壊のような形が起こっているのが一番多いのか。それと、どれぐらいのクラスの数で、そのような形が存在しているのか、それと、出席停止はどちらなのか、この点が抜けているのでお願いします。","respondent":"長田教育次長","answer":"出席停止にして問題は解決しないというような考え方から、今品川区では出席停止というような方法はとっておりません。","voiceIndex":132,"id":"exchange-059"},{"speaker":"大西委員","kind":"質問・要望","question":"こういうことで呼びかけて、土曜日にやったっていいじゃないですか。こういうところは先ほど言った団塊の世代の大きな土俵の中の２万７,０００人からのプロフェッショナルがいて、その部分についての教えを少し補助のような形でもできるんじゃないかというふうにもいろいろ考えていますが、とりあえず環境とリサイクルについてどのような形で市民科を通じて行っているんでしょうか、教えてください。","respondent":"長田教育次長","answer":"それから次に、環境の教育ですけれども、これは市民科の学習として、１年生から９年生まで指導要領によりますと８３時間程度予定をしています。","voiceIndex":135,"id":"exchange-060"},{"speaker":"大西委員","kind":"提案","question":"それと、子どもたちが教員の努力によっても、副校長の努力によってもなかなかうまくいかない。教育委員会が親を呼び出しなさい。それと、今平成１５年、１６年、１７年、１８年と学級崩壊、１校、４校、４校、７校、右肩上がり。なぜ、教育委員会はこのことを強制しないんですか。土曜日でもいいじゃないですか。強い指導じゃなくても、当たり前のことじゃないですか。それをやったらどうですか。","respondent":"長田教育次長","answer":"これは週五日制になったときの話にもさかのぼるわけですけれども、やはり、子どもの余暇の時間ですとかゆとりの時間、これは見直しの検討もされていることは確かですけれども、そういった形で週休二日というようなことになってきたわけです。","voiceIndex":137,"id":"exchange-061"},{"speaker":"大西委員","kind":"質問","question":"その前に問題を起こさないために家庭訪問をしておくべきなんだ。そして、親と教員との信頼関係をつくっておくんだ。そして、親の状況、そして家の状況、子どもがどういう環境で育っているかも認識した上での教育、指導をすべきなんです。私は座席譲りの会の会員なんですから、あなたに座ってもらわなきゃ困る」「それじゃあ、ありがとう。座ります」。ぜひ始めてもらいたいですが、この点はいかがでしょうか。","respondent":"長田教育次長","answer":"ただ、そのかわり、委員もご指摘ありましたとおり、「まもるっち」のストラップの中にマークを入れて実施をしていますので、そういったことでご理解をいただければというふうに思います。","voiceIndex":139,"id":"exchange-062"},{"speaker":"大西委員","kind":"質問","question":"いいですか、もっと積極的にやってくださいよ。家庭訪問を事前にすべての新しい学年が始まったときに家庭訪問させるかどうか、させてくださいと言っているんです。その答弁をお願いします。","respondent":"長田教育次長","answer":"こういったものが一律にできるかどうかというのは、社会情勢、それから先ほどお話をしました親御さんの状況、こういったものがあります。ですから、そういった意味では、必要があれば私どもも積極的にやっていくと、こういうことでご理解をいただければと思います。","voiceIndex":141,"id":"exchange-063"},{"speaker":"大西委員","kind":"質問","question":"それが必要があればというのが対症療法だと言っているんですよ。必要になる、その機会をなくすということなんですよ。要は、いじめや学級崩壊が起こらないように家庭訪問をしておいて、その子どもたちの現状とかそういうことをしっかりと認識させなさいと。だから、学年の初めに、しっかりと家庭訪問させなさいと言っているんです。その点はどうですか。","respondent":"長田教育次長","answer":"ただ、家庭訪問を含めまして、トータルにいじめの問題ですとか学校の問題、こういったものに対応していかなければいけないというようなことを私ども考えてありますので、そのトータルの一環としての家庭訪問をどうするかという観点で検討させていただきたいというふうに思います。","voiceIndex":143,"id":"exchange-064"},{"speaker":"大西委員","kind":"質問","question":"このバッチを教育委員会でつけるかつけないかということと、それともっともっと教育委員会は前向きに、もっと学校のほうに出ていって、もっともっと積極的な意思表示をしてもらいたいと思います。これで質問を終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-065"},{"speaker":"西本委員","kind":"質問","question":"私のほうからは３点行いたいと思います。それを踏まえて質問いたします。民間委託、それから指定管理者制度の中で、ＮＰＯの特徴をどうとらえているのでしょうか。どのように活用しようとしているのか。それをどういうふうな結果であったのか、分析をどこまでされているのかをお聞きしたいと思います。それに合わせまして、ボランティアとＮＰＯとの違いをどう認識されているのか、お聞きしたいと思います。","respondent":"新美企画部長","answer":"ということで、今後もさらにそういった領域が増大し、連携を組むＮＰＯも増えていくだろうということで、平成１８年度、１９年度にかけまして、庁内で連携協力をしている事業につきまして調査をし、今の事業連携についての成果や課題というものを分析し。","voiceIndex":147,"id":"exchange-066"},{"speaker":"西本委員","kind":"質問","question":"もう少しお聞きしたいところですが、平成１８年度でいろいろと庁内で調査をしたというふうにお聞きしておりますけれども、どういう調査をされているのか、それを踏まえて、では平成１９年度はどういう流れでしていこうとしているのかお尋ねします。","respondent":"新美企画部長","answer":"来年度はこれに基づきまして、庁内検討委員会をつくっておりますので、これから進めていく上で、職員としてきちんと身につけるべきノウハウあるいはマインドといったことも含めたものをまとめたマニュアルと。","voiceIndex":151,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問","question":"もう少しここのところでお聞きしたいところがあります。今１１０ピックアップされたと。それで、業務委託という形で３０のほう、されているということですが、この民間委託との関係ですね。民間委託とＮＰＯというところで、いわば企業のほうに委託をするという場合と、ＮＰＯに委託するという場合とでは、やはり違うんではないかなというふうに思いますが、その分析はいかがでしょうか。","respondent":"新美企画部長","answer":"こういうことを含めて、来年度はもう少し民間企業の委託する事例はどういうものが適当で、ＮＰＯはどういったところで有効なのかということも庁内で検討しながら進めていきたいというふうに考えております。","voiceIndex":153,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問","question":"その方たちにＮＰＯを取得していただいてという流れだと思うわけですけれども、既存のＮＰＯの活用に至っては、その選別といいますか、相手側をどういうふうに評価していくのか、これは非常に難しいところになると思いますが、そのお考えをお聞きしたいと思います。","respondent":"新美企画部長","answer":"今ご質問にありますように、一緒に立ち上げて、ある事業を実施していこう、一緒に立ち上げるときはおっしゃるとおりです。","voiceIndex":155,"id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"今実績というお話がありました。どういうふうな形にその実績を求めていくのか、その評価、実績の評価、では、庁内の中でやっていくのか、専門性からいうと、やはり自分たちの直営ではできないところをお願いするわけですから、その情報、それから評価の仕方というのは非常に難しくなってくると思いますが、その仕組み的なところはどのようにお考えでしょうか。","respondent":"新美企画部長","answer":"そういった事例が選定の仕組みを一定つくっているところですが、それ以外の、例えば子育て支援ポータルサイトとか、空き店舗の活用の子育て支援というのは、どちらかというと、区として事業をしようといったとき、あるいはＮＰＯ側から事業提案があって。","voiceIndex":157,"id":"exchange-070"},{"speaker":"西本委員","kind":"質問","question":"そうなると、責任の所在はどうなってくるんだろうかというところが出てこようかと思います。そのＮＰＯならではの特徴でもあり、デメリットでもあるというところをどういう形で活用されようとしているのか、平成１９年度のいろいろ検討される中で、どういう項目として検討しようとしているのかをお聞きしたいと思います。","respondent":"新美企画部長","answer":"そういった類型を踏まえながら、もう一つはプロセス別に、事業の立ち上げ段階、それから実際に事業、サービス、運用へ移った段階、その中から反省点を再調整する段階、それから、スムーズにいく段階、そこではモニタリング評価という、そういったことも含めて区と。","voiceIndex":159,"id":"exchange-071"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりしっかりとしていただきたい、考えていただきたいなというところでは、区の関与をどこまでしていこうとしているのかなと。やはり、資金という面では、非常に苦しい立場にあると思いますので、その区の関与、それから方向性、将来性として、どういうふうに発展をさせていこうとするのか、お考えがあれば、最後にお聞きしたいと思います。","respondent":"新美企画部長","answer":"区の関与ですが、そういう意味では、例えば事業委託というような緊密な形での連携があったときに、特に財政的な支援というのを、基盤が弱いわけですから、立ち上げ期はそれなりに求められるところがあることも承知しておりますが。","voiceIndex":161,"id":"exchange-072"},{"speaker":"西本委員","kind":"質問・要望","question":"ＮＰＯの方たちは、非常に活力があると考えています。次に、小学校と幼稚園・保育園の連携についてお尋ねします。これは今まで小中一貫校という部分では、連携という形では前面に出してきたわけですけれども、この問題をどのようにとらえているのか、それで、品川区の実態からこの問題に取り組むというふうな形になったのかをお聞きしたいと思います。","respondent":"長田教育次長","answer":"保護者の要望に細かく対応できるよう、平成１９年度から区内の小学校に入学予定の就学前幼児がいる全保護者に対しまして、就学支援シートという新しいスタイルですけれども、これを配布しまして、親として望みたい配慮事項について。","voiceIndex":163,"id":"exchange-073"},{"speaker":"西本委員","kind":"質問","question":"品川区では小中一貫教育ということを打ち出しているわけですけれども、その小中一貫校、小中というところの連携に対して、この施策の位置づけとはどういう形になってくるんでしょうか。幼保になるんでしょうか、幼保、小中という形の連携した形で今後考えていくということなのか、お答えをお願いいたします。","respondent":"長田教育次長","answer":"平成１９年度は、品川区就学前幼児教育プログラム、これを開発してまいりますけれども、この中で、市民科との関連、こういった関連を重視して、学びですとか発達の連続性、こういったものを踏まえまして、小学校との連続に役立つ実践について取り組んでまいりたいと。","voiceIndex":165,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"今とらえ方が就学前をとらえた形で連携をしていくよというお話をいただきました。児童保健事業部としては、０歳から１８歳までを視野に入れて一貫した子育て支援の政策をかなり強く打ち出しております。情報の収集と仕組みもいろいろ考えていかなければならないのではないかなというふうに考えますが、その考え方、それから、具体的な作業レベルの話をいただきたいと思います。","respondent":"長田教育次長","answer":"先ほど申し上げましたけれども、平成１９年には就学支援シートというものを就学時前の保護者の方に全部お配りします。こういったシートの中に、自分の子どもの特徴ですとか、あと教育に要望する内容、こういったものを書き込んでいただけるように改善をしていく予定です。","voiceIndex":168,"id":"exchange-075"},{"speaker":"西本委員","kind":"質問","question":"教育委員会がいろんな委員会の中の窓口になるのか、それとも各学校、それから地域になるんでしょうか、そういう形でまとめていくのか、やはり私は教育委員会のほうがいろんな委員会等々を設置されているんであれば、そちらのほうで全部集約をして管理をしていく、それから発信していくということが必要ではないかなというふうに思いますが、その中心になっていく担当はどこになるのでしょうか。","respondent":"長田教育次長","answer":"どちらが中心になるというような話ではなくて、それぞれ教育委員会と児童保健事業部の持っている仕事上の性格の問題、こういった問題をお互いに理解をしながら共同して進めていくと、こういうような形にしてまいりたいというふうに思ってあります。","voiceIndex":170,"id":"exchange-076"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり、公立は関係の中でいろいろできようかと思いますけれども、私立となりますと、また別の組織になってきますので、その辺をどういうふうに持っていき、先ほどの１本の柱を立てるときに、その私立との関係をどういうふうにつくっていくのか、幼稚園の管轄は児童保健事業部のほうになっておりますので、その関係もあわせてお答えいただきたいと思います。","respondent":"長田教育次長","answer":"そういった意味では、まさにこの辺につきましても児童保健事業部との連携というのが必要になってこようかというふうに思ってあります。そういったワンクッションを置いた中でも、そういった十分な協議はできるものというふうに考えてあります。","voiceIndex":172,"id":"exchange-077"},{"speaker":"西本委員","kind":"提案","question":"一つの具体的な提案になりますけれども、小学校、幼保という形での連携の中に、一番とりやすいなというふうに私が思っていますのは、昨年の第４回定例会でも提案させていただきましたけれども、食物アレルギー対策、これは簡単にできるんではないかなというふうに思っています。保育園には長年の蓄積、アレルギー対策の蓄積があります。その蓄積が小学校に入学する段階で切れてしまう。","respondent":"長田教育次長","answer":"そういった意味では、先ほど申し上げました来年度から実施する就学支援シート、こちらのほうにつきましては、直接保護者が必要なことを書いていただくというようなことで、情報提供いただけるわけですので、これの効果というのは、大きなものとしてあらわれるだろうと。","voiceIndex":174,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"就学前シートというお話がありました。確かにこれは有効的なことかと思います。食物アレルギーが何ぞやというところも含めて、やはり認識の違いということが多々見受けられますので、ぜひその関係を築いていただきたいというふうに思いますが、再度今後の展望はありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。では次に、コミュニティ組織による子育て支援についてお聞きします。平成１９年度は親育ちという対策が非常に、これも大々的に打ち出されているわけですけれども、この親育ちの政策の背景、品川における課題について、まずこれを先にお答えをしていただきまして、後でまとめて質問させていただきたいと思います。","respondent":"古川児童保健事業部長","answer":"児童センターあるいは保育園、そして幼稚園も含めて、それぞれの地域に施設がありますので、そういう施設から在宅の子育てをなさっている家庭にまずは入り込んでいきながら、それぞれが抱えているさまざまな課題に適切な対応をしていきたい、このように考えてあります。","voiceIndex":180,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"これは過去のお話になりますけれども、過去において、各保育園には父母の会というのがありました。その上で、保育園ＰＴＡができたという経緯があります。この当時のコミュニティの一つであった父母の会に対して、保育園ＰＴＡができた経緯、その当時の父母の会をどうとらえていたのかということをまずお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"３カ年ですべての年にＰＴＡができたわけでありますけれども、新しい組織の中で、ＰＴＡのあり方、保育園におけるＰＴＡのあり方というものを保育課と保育園、そして親との一体的な共同の中で、新しい組織の運営を今後目指していきたい、このように考えてあります。","voiceIndex":182,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問","question":"当時の保育運動にかかわっている１人でございましたので、状況はよくわかります。ですから、ある一定の整理が必要だったという時期は仕方ないし、当然のことだったのかなということで非常に私もいろんな思いがあります。その内容と、それから保育園ＰＴＡをどのような位置づけをして、再構築をしようとしているのか、お考えをお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"平成１４年に保育園におけるＰＴＡを立ち上げたときに、たぶん当時の関係者は相当苦労しながら、このＰＴＡの規約をつくったんだろうなと、こう思っておりますけれども、改めて私が昨年４月に児童保健事業部長になって。","voiceIndex":184,"id":"exchange-082"},{"speaker":"西本委員","kind":"質問・要望","question":"何年続いたでしょうか、保育運動。特に組合との関係も含めまして、かなり変えていっていただきたいというふうに思っています。ブロックもしくは連合の設立の方向性があるのかどうか、それから、もう一つ、幼保一元化を推進しているわけですけれども、幼稚園と保育園の交流も非常に大切な問題だと考えています。そこの垣根を超えるための施策があれば、教えていただきたいと思います。","respondent":"古川児童保健事業部長","answer":"ご覧のとおり保育園のさまざまな保育の事業の実施状況、あるいは保護者との関係を見ていただきますと、少なくとも従前のような関係から大きく改善されておりますし、保育士自体が自らの仕事に対して極めて使命感を持って取り組んでいる、このように考えてあります。","voiceIndex":186,"id":"exchange-083"},{"speaker":"西本委員","kind":"質問","question":"保育園ＰＴＡ、いろいろ規約が変わって、それから保育士たちの意識も変わってきた。非常に私はこの保育園ＰＴＡの将来性に対して期待を持っております。やはり、そういうことは二度と起こすべきではないと私は思っております。この正しい情報を提供する、それから、ともに保育園をつくっていく、子育ての輪をつくっていくということに対しまして、区の見解をお聞きしたいと思います。","respondent":"古川児童保健事業部長","answer":"それは過去の不幸な点があったですけれども、将来に向けましては、先ほど来議論になっておりますこのＰＴＡが大きな核になるだろう、こう思ってありますので、ＰＴＡを中心に保育園と保護者の関係をより正常に持っていきたいと、このように考えてあります。","voiceIndex":188,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"私からは、第１に基本構想策定とパブリックコメント制度について、２点目に荏原西地区の小中一貫校建設にかかわる荏原第二中学校統合について、３点目は、まちづくりへの市民参加について伺います。１点目の基本構想策定について伺います。そこで伺います。１点目は濱野区長の思い描く基本構想が目指す社会はどのようなイメージなものなのでしょうか。以上、３点についてお答えください。","respondent":"濱野区長、新美企画部長","answer":"策定のプロセス等については、部長のほうからお答えします。区内の有識者の方のアンケートあるいはグループインタビューといった手法も考えているところです。そのような作業を進めつつ、５月末から６月の当初には外部委員の方による検討組織を立ち上げてまいります。","voiceIndex":192,"id":"exchange-085"},{"speaker":"井上委員","kind":"提案","question":"こういった分野ごと、課題ごとに市民が自由に参加をして行うワークショップ形式によって、積み上げていく作業を取り入れた素案づくりを提案します。５月末の組織編成をし、１１月に素案という非常にタイトな期間ではありますけれども、ここにぜひこういったワークショップの形式を盛り込んでいただきたいというふうに思っております。","respondent":"新美企画部長","answer":"安心・安全、これも欠かせない課題であると思います。コミュニティ、防災、防犯、あるいは地域経済、産業振興も入るかと思います。環境問題、都市基盤としてのまちづくり、いろいろあろうかと思いますが、これは検討の中でぜひ柱立てをお願いできればと考えています。","voiceIndex":195,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問・要望","question":"今説明されたように、大変多岐にわたる問題であって、区民の方の要望もたくさんあるということはそうかと思うんですけれども、でも、つくる基本構想というのは、品川区の区民がどんなまちにしたいかとか、どんなまちが望ましいのかということを示していくものですので、ワークショップも前向きに議論していただきたいんですが。","respondent":"新美企画部長","answer":"そのためには、具体的ないろいろな案等を区は説明をし、区民の意見を求めて、それを区政に反映させていくことが必要であり、そのための具体的な仕組みの一つであると認識をしております。","voiceIndex":197,"id":"exchange-087"},{"speaker":"井上委員","kind":"提案","question":"行政の施策形成過程を透明化することによって、区民が区政へ参加しやすくすること、また、区民が区政に参加をする権利が保障されるべきですが、この意味でも、市民協議会の設置などの方法を採用して、パブリックコメント手続の趣旨を生かしていくことがベストだと思いますけれども、ここでも素案づくりをどのようにしていくのかということが１点、策定のスケジュールをお伺いいたします。","respondent":"新美企画部長","answer":"早急にこの要綱案を検討いたしまして制定し、実施に移し、それぞれ事例を重ねながら、より趣旨に沿った、目的に沿った制度になるように運用を工夫していくことが大変重要なのではないかという認識です。したがいまして、できるだけ早く要綱を策定し、実施に移していきたい。","voiceIndex":199,"id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"２点目は、荏原西地区の小中一貫校建設にかかわる荏原第二中学校統合について伺います。昨年４月日野学園が開校し、今年の４月に伊藤学園が開校します。それで、荏原西地区の小中一貫校にかかわる平塚中学校と荏原第二中学校の統合について伺います。教育費の款別審査でも問題として指摘されていましたが、荏原西地区小中一貫校建設計画に急遽荏原第二中学校を構成母体校と変更した理由は何なのでしょうか。","respondent":"長田教育次長","answer":"それで、昨年の７月に平塚中学校と平塚小学校の一貫校の建設についての説明会に入っていったわけですけれども、この中では、町会関係者、地元から先ほどの背景から統合をしてほしいと、こういうような希望が出てきてあります。","voiceIndex":201,"id":"exchange-089"},{"speaker":"井上委員","kind":"質問・要望","question":"６校構想の学校の決定の過程で地域の声を聞きながら進めていくべきであるということを生活者ネットワークは一貫して求めてきましたけれども、計画形成過程に地域住民の参加がなかったということが、結果的には子どもたちに影響を及ぼしているんだということを指摘させていただきたいと思います。それから、今後どういう形で住民および保護者、生徒の声を聞いて合意形成を図っていくのかお伺いをいたします。","respondent":"長田教育次長","answer":"保護者への説明会ですけれども、これにつきましては、小中一貫校の構成校に荏原第二中学校を加えるというようなことと、それからそれに先立ちまして、平成２０年４月に中学校２校を統合するというようなお話をさせていただきました。","voiceIndex":204,"id":"exchange-090"},{"speaker":"井上委員","kind":"提案","question":"子どもの声を直接聞くようにという生活者ネットワークの提案に対しては、教育委員会は教師が日ごろ子どもの意見は十分に聞いているといつも答弁をされています。そこでこの計画に対して、子どもたちの声はどのように聞こえているのか、また、教師の声はどのようなものなのか、お伺いをいたします。","respondent":"長田教育次長","answer":"ただ、この問題につきましては、子どもの声だけではなく、やっぱり保護者の意見も十分反映していかなきゃいけないというようなこともございまして、２月９日、１０日以降、地域の方々、これはＰＴＡ、それから７年生に入学をする保護者、それから地域の方々。","voiceIndex":206,"id":"exchange-091"},{"speaker":"井上委員","kind":"質問","question":"すみません。私の質問が通じなかったかもしれません。今後子どもたちにどうするかではなく、現時点で子どもの声はどうなのかということをもう一度お答えください。","respondent":"長田教育次長","answer":"子どもの声も、もう中学生ですので、十分自分なりの考えは言えるという観点の中で、学校の中でそういった部分を取り上げまして意見を聞く機会、こういったものを設けたいと、このように思っているところです。","voiceIndex":208,"id":"exchange-092"},{"speaker":"井上委員","kind":"提案","question":"次は、市民の参加を保障するまちづくりについてお伺いをいたします。この件数や陳情の内容をどう分析して施策に生かしているのか伺います。そこで、こういった課題に対して、区として解決に向けた取り組みができるものがあると思われているかどうか、そういったところの感想と、また、まちづくりの専門家として、具体的な取り組みについて見解を伺いたいと思います。","respondent":"福田まちづくり事業部長","answer":"今後につきましても、区の市街地整備基本方針に沿うならば、そのような支援策を積極的に講じてまいりたいというふうに思っております。","voiceIndex":210,"id":"exchange-093"},{"speaker":"井上委員","kind":"質問・要望","question":"荏原地区では後継者のない町工場、商店街がどんどんワンルーム化しているということで、周辺区民の皆さんもどんどん人が回転をしたり、区民として地域活動に参加しないワンルームマンションの居住者には抵抗感があり、なかなかワンルームマンションの方々は地域に飛び込むということが実際ないという状況の中で、近隣の方たちの住環境の不安というのがたくさんあるわけですが。","respondent":"福田まちづくり事業部長","answer":"このことは区がその当時からワンルームマンションには、他のマンションには見られない固有の問題があるという認識を持っていた。そういうふうに言えるんだろうと思っています。","voiceIndex":212,"id":"exchange-094"},{"speaker":"井上委員","kind":"質問・要望","question":"ここで要望なんですけれども、形骸化した計画策定のプロセスを重視するあまりに、結果として時間がかかってしまって、そして住民の方たちも疲れてしまったり、住民の方の期待を裏切るというようなことにならないように、ぜひ適時適切な支援をして、この地区計画、住民主体の地区計画ができ上がることを要望して、総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-095"}]},{"id":"topic-02","title":"休憩前に引き続き、会議を開きます。 第５号議案、平成１９年度品川区一般会計予算に対する修正案","agenda":"休憩前に引き続き、会議を開きます。 第５号議案、平成１９年度品川区一般会計予算に対する修正案","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"日本共産党区議団の提案者を代表して、第５号議案、平成１９年度品川区一般会計予算案の修正提案を説明します。条例に関する提案説明は本会議において行わせていただきましたので、この場では予算修正説明のみを行います。お手元に配付をしてあります「平成１９年度品川区一般会計歳入歳出予算の一部修正に関する説明書」をご覧ください。歳入についてです。続いて、歳出です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-096"},{"speaker":"須藤委員","kind":"質問・要望","question":"昨年の秋に、我が会派が区長に２０５項目にわたり政策予算要望いたしました子育て支援の充実、教育改革の推進、高齢化社会の対応、障害者福祉の充実、健康課が中心となっての生涯にわたる健康づくりの推進、災害に強く、景観に配慮した安心安全なまちづくりの推進、施策の充実、地球温暖化防止を考慮した幅広い環境対策、商店街や中小企業の振興施策、品川区をアピールする観光施策の推進等に加えまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-097"},{"speaker":"宮崎委員","kind":"提案","question":"格差と貧困の原因に、パートや派遣社員の低賃金があると指摘されているのに、品川区で働く９００人のパート、派遣は１０万円から１４万円の生活保護基準以下、自治体自ら低賃金の不安定雇用を拡大するのは問題、均等待遇の原則を求めるものです。特別養護老人ホームの入所基準が、なぜ情報公開の手続がなければ公開できないのでしょうか。改めて区民への説明と関係者による損害賠償を求めるものです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-098"},{"speaker":"三上委員","kind":"提案","question":"以下、その理由について、幾つか要望を含め意見を申し上げます。ここで、今後の区政運営などについて主な要望を述べておきます。特に経済的負担軽減策として、今回子どもすこやか医療費助成制度の対象年齢が中学３年生まで拡大されることになっておりますが、すこやか児童手当についても現行の小学６年生までを中学３年生まで拡大することなどを含め、一層の負担軽減を要望しておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":224,"id":"exchange-099"},{"speaker":"土井委員","kind":"質問・要望","question":"品川区民連合を代表いたしまして、２００７年度予算特別委員会を締めくくる意見表明をします。すこやか医療費助成の中学までの拡充、就学前教育プログラムの策定、小中一貫校６校構想の着実な進展と適正規模の検討や子育て支援、親育ち支援などにも踏み込んだ施策展開が見られます。学校を転用して、地域要望の強い高齢福祉施設と幼保一元施設への改修など、今後の区政展開の方向をも示唆するものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-100"},{"speaker":"藤原委員","kind":"提案","question":"平成１９年度予算の基本テーマ、明日の品川区に向けて、区民と連携、協力のまちづくりの重点的な課題は、区民の要望と期待にこたえたものであり、品川区の特色と独自性を発揮したさまざまな施策が打ち出されています。最後に、我が会派委員の提案・要望した各項目について、積極的に受けとめていただき、区政運営に生かされていただくことをお願いするものであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":228,"id":"exchange-101"},{"speaker":"三村委員","kind":"質問・要望","question":"一般会計予算修正案には反対をし、以下、意見と要望を述べします。保護者や子どもたちの声に耳を傾けた計画変更を求めます。そうした区民の動きを支援し、区民の声を反映したまちづくりを求めます。２００７年度一般会計予算では、昨年度の予算特別委員会で違法性が高いため、廃止を求めた議員のＯＢ会である議員待遇者会への補助金が引き続き計上されました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-102"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=888#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":120462,"voices":237}},{"id":"h19-20070326-10","meetingId":"h19-cm03","date":"2007年3月26日","dateIso":"2007-03-26","committee":"議会運営委員会","time":"午前１０時０３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１９年請願第４号 政務調査費不正支出について真相を徹底調査し区民に報告を求める請願","agenda":"平成１９年請願第４号 政務調査費不正支出について真相を徹底調査し区民に報告を求める請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"審議をして、その後に意見陳述を受けるかどうかということですか。それは逆ではないかと思うんです。最初に請願の要旨はありますけれども、そのほかにもしっかり意見陳述の要請があれば、審議をする前に聞いて、それから審議に入ることが必要ではないかと思うんです。そのように諮っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"石田委員","kind":"意見","question":"今、委員長がおっしゃったように、今までは通常の請願審査もそうだと思いますが、請願書があるわけでして、請願書に基づいて我々がいろいろな意見・議論を交わした後、それを踏まえて意見陳述をしたいという申し出があったとき我々が諮るというのが今まで我々が行ってきた請願審査の流れだと思いますので、その流れで結構だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-002"},{"speaker":"宮崎委員","kind":"確認","question":"あまり通常と言われると、通常ではないというように思いますけれども、そこの申し合わせとか、こういうふうにやるという確認はありましたか。通常と言われると、通常ではないと思いますけれども、こういう確認だということであれば、その確認を示していただけばいいですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-003"},{"speaker":"土井委員","kind":"質問","question":"私も同じことを言おうと思ったんですけれども、私も何回か今までの委員会運営の形の中で意見陳述の話があって、実現した場合、しない場合いろいろありましたけれども、いずれの場合もそれぞれの議会の中で議員が請願書に基づいて議論した上で、その後、皆さんがいろいろ判断するにあたってご意見を伺うというスタイルでやってきたと理解していましたので、そのようにお諮りになったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"今回の問題は、私も含めて議員として非常に大きな問題として、区民の皆さんの中で扱われていると思います。今回、改めて請願を出された皆さんの声をまず前段で聞くことが極めて重要なものではないかと考えておりますので、まず先に区民の皆さんの声を聞くことで進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-005"},{"speaker":"宮崎委員","kind":"意見","question":"ここで請願審査をするにあたって、一番区民の皆さんの意見を反映した中での審査をするにはどういう方法が一番いいのかということを、まずしっかり議論することが大事だと思うんです。私はまず陳述を受けてからやることが大事だと思うんです。今、意見が違うということがはっきりしているだけであって、どういうふうにしようかという、いい方法が議論されていないのに多数決でやるというのは少し乱暴です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南副委員長","kind":"質問・要望","question":"とりわけ、今日は傍聴席いっぱいの方々が傍聴にお出でになっているわけですから、そういう方々の関心も高いという問題だけに、やはりその辺はきちんとした議会として信頼を広げていくためにも、そういうことを大事にして諮っていくべきではないかと思いますので、改めて表明して、委員長に早急に採択だけではなくて、趣旨をきちんとしていただけるようにはからっていただきたいと思います。","respondent":"須藤委員長","answer":"同じ会派の人から、片一方は意見陳述をやったことはない、片方はやっていますという話が出たので、なかなか難しいと思いますけれども、今までは委員長が話したように進めてきておりますので、これをやっていたら中に入れませんので、意見陳述につきましては。","voiceIndex":16,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、請願書に出されていない、ここに反映されていないいろいろな意見も出ているから、意見陳述の要請が出ていると思うんです。ですから、ぜひ皆さんにお願いしたいのですけれども、最初にお伺いして、それから審査に入るようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"菊地委員","kind":"意見","question":"当然、その話の中で、築舘議員が白紙の領収書をもらって、それに自分で金額を書き込んで政務調査費を請求したことに対して、事情聴取のようなことは当然自民党会派内でやられたと思いますけれども、その辺の明確な中身を私たちも知りませんし、区民の皆さんに自民党会派の皆さんが説明したわけでもないと思いますので、その辺の内容についてお聞かせ願いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"辞職をどうしよう、こうしようということですけれども、あくまでも我々議員の場合はみずからが決断するものであって、今の現制度では区民による選挙で選ばれている議員ですので、選挙の効果を我々が否定することにつながると考えていますので、今のお答えになっているかどうかわかりませんが、そういう制度があるわけですから、制度にのっとった中で我々はやっていこうと思っていますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"ただ、築舘議員に関しては、私もテレビの報道でしか見ていませんけれども、「政務調査費そのものが第二の給与だと考えていた」と、テレビの中でも発言されているわけですから、政務調査費がどういう性質を持ったものかということを明確にとらえないまま使っていた。築舘議員が所属した会派として、委員会の設置について同意されるのかどうかお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"石田委員","kind":"質問","question":"今のお話を分けていただかないと、話にならないのは、今は請願審査をしている中で、先ほども言いましたように、議会は制度上、ルールとして１００条委員会でも、任意の会議体でもいいわけですけれども、そういうものの制度があるわけですので、その制度を利用した中でやっていくことであって、今は請願審査をしているわけですから、今のお話が直接的に結びつく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"犯罪だということは議会が決めることではありませんけれども、やはりきちんとこれについて明確な意見を述べていくというのは、自民党会派にしてもそうですし、議会についても道義的責任として明確にあるわけですから、ぜひ請願の三つの項目について取り入れていくという論議を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-013"},{"speaker":"土井委員","kind":"質問・要望","question":"議会の場合は議会としてやるべきことだろうと思います。要するに、いろいろお聞かせいただいている中であっても、これからのあり方も議会としてきちんと出していくことによって、ここでの正式な答えになるのではなかろうかという思いを持っているものですから、それを目指していただきたいと思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"今の石田委員の発言で確かめておきたいのですけれども、真相究明というのは１００条調査委員会も含めて会議体の中でやるべきだということです。はっきりさせておきたいのは、それならばそういう会議体をしっかり設置するということで、自民党はそういう立場だということなのかどうか。そのための会議体をやるという認識があるのかどうか、そこのところを聞いておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":27,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"ご質問ですのでお答えいたしますが、議会としてのルールとしての会議体をどうつくっていくかというのは、また別な議論をしていかなければならないと思います。議会のルールとしての流れの中の部分としてやるとしたら、そういうものをつくってやるしかないというのは石田委員の意見もあったと考えていますし、そういう中に１００条委員会はふさわしいものではありませんということを申し上げたということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-016"},{"speaker":"石田委員","kind":"質問","question":"その前に段階があったわけですから、それをすべて真剣に取り組んでいないとか、だから任意の会議体でも１００条委員会でも性格が違うという考え方はありますけれども、特別委員会でも設置できるわけですから、それはどういう形の中で議会のルールの中でやりますかということを言っていることであって、その問題とこの請願を一緒にしたらおかしいですということを言っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私が言っているのは、真相を解明するための会議体を設置するということに賛成するかどうか態度をはっきりさせていかないと、この請願にかみ合っていかないということを言っているのです。これは真相解明を議会として行うことということを言っているわけです。どのような手口でもらってきたのか、そこのところはどうですか、わかっている範囲で説明していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"先ほど来、ご説明しているように、よく話を聞いていただきたいけれども、一つ一つのことについては、先ほども言っているように、我々は検察でも警察でもないわけですから、地検でも何でもない。それを議会がやるかやらないか。それは先ほど言った特別委員会や任意の団体でもあるわけです。違う場面で検察なり何なりが動くなら、それはその場で明らかにされる話でしょうということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"議会は何をやるところですかと言ったのです。今の築舘議員の手口というのは、この中で防止するだけのものをとらえているのかどうか、そこのところはどのような認識なのか。それが十分かどうかを調べるための真相解明じゃないですか。石田委員がこの場ではなくて別な会議体だということであれば、その会議体を設置することに自民党は賛成なんですかということを聞いているのです。そこのところをはっきりして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"確かに、区民の方から見れば大切な税金ですから、税金の使い道がどうなるか知りたいというのは、当然あると思います。確かに、私も区民の方からいろいろ話を伺っていると、やはり視察費用の透明化、どういうところに目的があって、どういう使い方をしたのかとか。それから印刷代も、何の目的の印刷であったのか、またどういう人たちに配られたのか、こういうことも必要ではないのかという声も聞いております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"政党の責任はどこなのか、そういうことでしょう。選挙民に責任に押しつけるわけにいかないのです。特に、築舘議員は２００万円を不正に領収書を偽造して受け取ったと認めていますから、どういう手口だったのか。この２００万円はどこにどのように使われたのか、私的に流用していたのか。諸活動というのは、一体何なのか、自民党は調査したのですか。調査したのだったら、ここで説明願いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-022"},{"speaker":"石田委員","kind":"意見","question":"同じことを何度も聞かれているので、考え方はご説明してあります。公表もしておりますし、公開もしている。公の場でも当該議員、原（雅）議員も含めて自分のお考えを述べていらっしゃるし、事実もお認めになっているということであります。それだけは言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-023"},{"speaker":"中島委員","kind":"質問","question":"一つ、質問したいのですが、今の辞職勧告決議という話が出たんですが、これは法的効果というものはどうなのでしょうか。","respondent":"市岡区議会事務局長","answer":"昭和２６年の少し古い行政実例ですが、辞職勧告決議を議会に議決すべき事件としてあたるかどうかということを問われたものですが、１１２条の議会の議決すべき事件には該当しない。","voiceIndex":39,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"透明性をつくり上げるということも、当然重要なことだと思います。ただ、先ほども宮崎委員が言っていたように、やはり過去に起きた事件をきちんと分析していくということが極めて重要だと思うんです。やはり、そういうコメントをしているわけですから、自民党会派として原（雅）議員にかわってこの内容について出すべき中身だと思うんですけれども、その辺はどうでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問・要望","question":"同じことだと言うけれども、中身は違うわけです。原（雅）議員は家族の分は間違いだったけれども、自分は政務調査費で行ったのは視察だと言っているわけですから、中身を一つ一つ明確にしない限り、新たに同じことが起こることを防げないはずです。そこはやはり明確にしていただきたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-026"},{"speaker":"石田委員","kind":"意見","question":"我々はその中で、そういうものも主張させていただいていると考えていますし、今、この請願審査の中で、先ほど来ずっと言っているように、個々のことがどうだという立場にも、そういうつもりもないですし、先ほど言っている真剣にその中で取り組んで透明性を高めるために全力を尽くしてやっているということでありますので、その中できちんと皆さんにご報告もしているつもりであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"一つ一つの問題点が明確になっていかない限り、やはり同じ流れがつくり出されていくというのは明確なのではないでしょうか。やはり、国会でも同じです。明確な方向性も生まれてこないと思います。先ほど来、石田委員がおっしゃっている１００条委員会があればということですから、ここでそういう流れが論議できないというのであれば、そういう委員会をきちんと設置することは必要だと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"個々の例は会派でという委員長のお話があったんですけれども、個々の例の積み重ねがここまで来てしまった。それが第１点目です。もう一つは、請願に出ているのは、真相解明をやってほしい、区民にも説明してほしいということです。そこの点が問われているわけです。個々の例の積み重ねなんですから。原（雅）議員は会派に返したと言うけれども、会派はどうしたのですか、そこのところは何かありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-029"},{"speaker":"石田委員","kind":"意見","question":"先ほども何度も言っておりますが、議長を含め改善策を出した中に、事例検討も継続していきましょうということも出させていただいて、あり方も含めて改めて継続して検討していきましょうということであって、そういう事例が個々にいろいろ持ち上がるのであれば、改めてやっていきましょうということで、我々も改善策を出させていただいたからといって。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-030"},{"speaker":"南副委員長","kind":"確認","question":"今年になって、１月２５日のホームページには、「区民の皆様に対し政務調査費の適切な運用と説明責任を果たす努力を行い」ということは書いてありますけれども、それ以外の具体的な中身はないし、その後のホームページを確認しても、全然具体的なところは書かれていないんです。いくらそれをおっしゃってもわからないです。そこを具体的に説明してほしいと聞いているわけですから、きちんと答えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-031"},{"speaker":"石田委員","kind":"意見","question":"それが会派としての対応でありまして、政務調査費は会派として受けておりまして、それに対する改善策にも踏み込ませていただいているということで、同じことの繰り返しになるので、私どもとしてはそれに対するお答えはできていると考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-032"},{"speaker":"宮崎委員","kind":"質問","question":"そこが見えてこないのです。党としての対応だというのであれば、今の私的な流用だったのかどうなのか、それは不正だと、私的な流用はだめだということなのかどうなのか、それは個々の事例、一つ一つをしっかりコメントしていかなければ責任を果たせないので、改めて伺いたいと思います。私的流用がだめなのかどうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-033"},{"speaker":"石田委員","kind":"質問・要望","question":"請願審査をして、最初からずっとそういう話ですけれども、何度もご説明をしているとおりでありますので、ご意見はどうぞ言ってください。委員長にもお願いしますが、その部分についてのお答えは同じことを何度をしておりますので、繰り返しになるようなことはやめていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"私は逆だと思うんですけれども、逆に今の議論を聞いてどう思うかということも含めて、やはりしっかり請願者の意見を聞くことが必要だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-035"},{"speaker":"土井委員","kind":"質問","question":"その辺からまとめてきちんとお聞かせいただくことも含めて、最初に議論をしてきた経緯もあるものですから、その意味では今の状況では時間的にもきつさがあると思います。したがって、特段、今の状況の中では、先ほど来からの議論も踏まえてもよろしいのではないかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-036"},{"speaker":"菊地委員","kind":"意見","question":"今、中身が伝わっているとおっしゃいましたけれども、自民党の発言の中で請願の趣旨に沿って説明があった、論議があったとは到底思えないのです。やはり、きちんと請願者の陳述を聞くべき中身があると私たちは思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"意見","question":"私どもは当然賛成です。特に、この請願の要旨の議会として真相解明を行うということは、議会として今後の再発防止にしっかりした対応ができるかどうか。そのためには真相解明がどうしても必要です。特に、私が気になっていたのは、先ほどの原（雅）議員の旅行代でも、私的な旅行だけれども自分はいいとなったら、政務調査費というのは一体どういう基準で使ったのか、自民党の基準が問われるのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-038"},{"speaker":"中島委員","kind":"意見","question":"先ほども申し上げましたけれども、視察の目的とか人数だとか、印刷代ではどこに何部配られてどういう印刷をしたのかとか、書籍は何を買ったのか、こういうことが明示できるようなシステムなっていなかったということが、私は問題だと考えています。それだけ申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":21057,"voices":71}},{"id":"h19-20070604-6","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"区民委員会","time":"午後４時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"番目、事務事業概要","agenda":"番目、事務事業概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"産業振興課のほうにいきまして、２０ページ、中小企業ワークライフバランス支援事業ということなんですが、タイトルに中小企業というのがついているんですけれども、仕事と育児とか、介護とのバランスを目指していると伺っているんですが、品川区内には、ソニーとか、リコーとか、大企業がありますけれども、やっぱり大きな企業の動向が、全体の流れにもかなり影響するというので、区内の大企業のほかには。","respondent":"鷹倉区民課長、高濱生活安全担当課長、金子産業振興課長、原国保年金課長","answer":"先ほど、レベルアップとおっしゃいましたけれども、平成１６年度から１７年度でちょっと下がっているわけですけれども、下がった理由は。五反田と武蔵小山の商店街において、助成をして、防犯カメラを設置しております。私どもの事業の趣旨は、比較的大きな余裕のある企業ではない中小企業について、こういったことを導入していただこうということで。上の現年度ですけれども、注釈のところに書いてありますように、平成１８年度ですと。","voiceIndex":59,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"中小企業の団体の皆さんからも、国民健康保険料だけではないですけれども、年金とかを払うのがすごく大変だというお話も聞くんです。やっぱり、何とか国民健康保険料をこれ以上上げないといいますか、むしろ下げる方向でやることが、滞納の悪循環といいますか、それを解消する一番の根本策になるんじゃないかと思うんですが、そこら辺の考え方はいかがでしょうか。","respondent":"原国保年金課長、高濱生活安全担当課長","answer":"そういった中では、収入のある方については、所得割ということで、住民税をもとに計算をさせていただいて、均等割については、今年でありますと３万５,１００円ということで、その中でも、収入の低い人については、７割減額。現在、設置されている防犯カメラの運営についてのご質問ですが、それぞれ、管理主体であるまちの団体のほうで、管理運営要綱をつくって運営していただいています。","voiceIndex":65,"id":"exchange-002"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"社会保険事務所に行っても長蛇の列で、何時間も待たないとわからないといった状況の中で、区民の皆さんの不安を取っていくという意味も含めてなんですけれども、５,０００万件のミスの問題というのは、１０年前にさかのぼって、一本化して番号を通しにしたときから１０年間ずっと続いている問題なんですけれども、その辺と、品川区の今までの事務のかかわりというんですか、どの程度かかわっていて。","respondent":"高濱生活安全担当課長、金子産業振興課長、原国保年金課長","answer":"３点目、今後の活用についてですけれども、今後は、区主体ということではなく、地域の住民の方主体で。三つ目の、武蔵小山全体のまちづくりとのかかわりですけれども、先ほど申し上げましたとおり、現在。区の援助ですけれども、やはり、区民が不安に思っているわけですから、どうすればその不安が解消できるかといったところで、これから、広報とか。","voiceIndex":68,"id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"古い書類に対して、国のほうから、厚生労働省のほうから、もう既に廃棄をしてしまった。あるいは、指示が出ていたりして、そういった面で、区で保有している書類があるのか、どうか、そういった面で援助できる書類があるのか、どうか、ちょっとその辺を。国のほうは、もう廃棄の指示が出ているとか、そういう話もちょっと聞いているんですけれども、その辺、どうなんでしょうか。","respondent":"原国保年金課長","answer":"ただ、そうは言いましても、一部区のほうに残っている書類もありますので、それは大事にとっておきながら、これからの調査の中で、協力できることについては協力していくという考え方です。","voiceIndex":72,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"確認","question":"一つだけ、ちょっと確認させてください。区民課の７ページの民間施設借上経費。これは区から、この施設に対して、利用者の人数分の経費を負担することになるんですか。金額的には、どのぐらいでしょうか。","respondent":"鷹倉区民課長","answer":"三つの施設は３部屋ずつ。それぞれの施設の借上料と、近畿日本ツーリストに受付代行業務、合わせて４,０００万円ちょっとという形になっております。","voiceIndex":74,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ということは、各ホテルに３部屋ありますけど、使わないときも、借上料として一定金額を払うという形になるんですか。","respondent":"鷹倉区民課長","answer":"今回、借上型という形をとっておりますので、そういう形になります。","voiceIndex":76,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ちょっと区のホームページの中の予約件数を見ていて、まだかなり空き室もある。まだ新しい施設だから伝わっていないので、区民もわかっていないのかもしれないんですけれども、借上料が出ているだけの形では、今の空き室が多いということで、７月あたりでも土日は入っているけれども、平日は、夏休みになっても空き室が多かったと思うんですけれども、ぜひ、有効に使っていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと多岐にわたるもので、年金の話が出たので、私も個人的な意見といいますか、伺いたいんですが、年金の話で、今、ものすごく多くの方が不安という状況だと思うんですけれども、先ほど、区民の皆さんの不安をどうやったら解消できるか考えて、区報などでお知らせしていきたいという答弁があったんですけれども、区民生活事業部という部があって、その中の国保年金課という窓口があるわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"３点なんですけれども、まず２４ページの、これは単純な質問で申しわけないんですけれども、環境ＩＳＯ運用管理経費ということで、認証されたのが平成１６年で、３年に１度更新ということなんですけれども、取り組みの成果もかなり上がっているということで、品川区が事業者として受けられたものだと思うんですけれども、どこまでの範囲ですか。","respondent":"田村環境課長、島袋品川区清掃事務所長、秋山資源循環推進課長","answer":"ただ、その学校を除いても、先ほど、事業概要でご説明したように、学校ＩＳＯというような別の取り組みで、内容的に取り組んでいるところです。実は、先ほど資源循環推進課長が説明しましたように、平成１７年７月から、全区的に各戸収集をやりまして、そのために分別を徹底させたものですから。拡大に至ったですけれども、平成２０年度の本格実施と書いてありますのは、これは１００％ですので、それに向けて、今年度、世帯数で１５％。","voiceIndex":87,"id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"これは区の負担でしたっけ。私はほんとうに、環境課というところにおいては、ここに載っている部分ではなくて、もっと広い意味で、品川区の環境、日本の環境も含めてだけれども、もっと大きくとらえた、環境をよくしていくという立場で、特にサーマルリサイクルなんかは、どう考えていらっしゃるのかというのを、ちょっとお伺いしたいんです。","respondent":"岩崎環境清掃事業部長","answer":"店頭回収につきましては、区が車を回しているです。それから、ダイオキシンですが、これは一部事務組合の事業でありまして、検証作業を、昨年度２回実施いたしました。","voiceIndex":91,"id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"やはりこの点に関しては、私は、廃棄物減量等推進審議会にずっといたんですけれども、環境課というセクトがちゃんとあるからには、ごみ問題と、地球規模の環境のところも一緒にセットにして考えて、広い意味での対策をしていただきたいなと思うところで、問題なしにということではなく、ぜひ、一緒にあわせたところで考えていただきたいなと思うんですが、ご意見をいただきたいんです。","respondent":"岩崎環境清掃事業部長","answer":"今、述べたとおりで、私は、環境も清掃も所管している立場から、ＣＯ2は、京浜島で燃やしているものを、きれないプラスチックに限りますけれども、それをリサイクルするわけですので、ＣＯ2は減るというふうにご理解をお願いしたいと思います。","voiceIndex":93,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"４３ページの東品川清掃作業所の件で、ちょっと忘れてしまったので、確認させてもらいたいと思うんですが、先ほどのご説明の中で、搬入、品川区、目黒区、世田谷区、渋谷区の各清掃事務所から搬入される粗大ごみの処理ですけれども、歳出予算の中で、中継作業所に５億円近くかかっている中で、他区の分担金があるんでしたっけ。それをちょっと忘れたので。","respondent":"島袋品川区清掃事務所長","answer":"一応、各区の負担金はありません。区のほうの持ち出しなんですけれども、実際は財調で補正されています。","voiceIndex":99,"id":"exchange-012"}]},{"id":"topic-02","title":"番目、報告事項","agenda":"番目、報告事項","exchanges":[{"speaker":"稲川委員","kind":"質問","question":"これは基本的に国がやったものに基づいてつくったものなんですか。","respondent":"斉藤防災安全担当課長","answer":"区市町村がつくる場合は、東京都知事の協議を受けなさいということになっておりますので、国のほうから段階的に落ちてきていると。その際に、モデル計画というのが示されてきておりまして、基本的には、そのモデル計画の指針にのっとった計画という形になっております。","voiceIndex":106,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、この協議会の中で、どのように想定しているのかというのを知りたい。それはそれでいいんですが、関係機関と連携して訓練や研修などを行いますと書いてあるんですけれども、現時点で、品川区の中で具体的な訓練は、いつ、どのように行われるかというのを、わかる範囲でいいんですけれども、ちょっと教えていただきたいなと思います。","respondent":"早津区民生活事業部次長","answer":"訓練については、具体的なものは、今後、検討します。","voiceIndex":108,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"テロと武力攻撃と、どういうふうに違うのか。日本には米軍基地もありますから、日米安保に基づいているわけですから、米軍基地を巻き込まない形での防衛的な軍事活動の具体化とかはあり得ないと思うんですけれども、そういう国際情勢の中で、こういう法律を具体化すること自体が、やっぱりちょっと違和感があるなという、私の思いはあるんです。現時点でのお考えはどうですか。","respondent":"早津区民生活事業部次長","answer":"例えば、武力攻撃の2)でゲリラ・特殊部隊による攻撃というものもテロになる可能性があるわけで、それと比べて、二つ目に大規模テロと書いてあるのが、どうしてなのかと、そういうご趣旨かと思ったんですが、そういうことではないんですか。","voiceIndex":112,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"一般区民の立場からいたしますと、こういう法律を具体化するときに、武力攻撃とは何なのかというのはわかりにくいし、テロというのは何なのかというのはわかりにくいので、この国民保護計画自体を理解するときに、非常に理解しにくいということなので、今のこの法律を具体化する上で、その定義をどういうふうにしているのかなというお考えをお聞きしたいということです。","respondent":"早津区民生活事業部次長","answer":"外国からのものだというのがはっきりしている場合は、１番の武力攻撃事態ということで、外国からかどうかがわからないような場合に、大規模テロ等といったジャンル分けをしているというふうに認識しております。","voiceIndex":114,"id":"exchange-016"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"前段の国民保護法のところの解釈から来ている計画なので、そこの論議を抜きにしては、地域の防災計画だけで、地域の避難訓練とか、そっちの問題だけで解決をするところではないと思うんです。法案からの流れもご説明いただいたんですが、しっかりととらえて、区の計画が今後どうなるのかというチェックもしたいので、これは時間をかけていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の委員長のお話の中で、報告はわかったんですけれども、議論は区民委員会でしないというお話ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-018"},{"speaker":"稲川委員","kind":"質問","question":"先ほど、説明の段階で、区民の皆様にお配りするという話があったと思うんですけれども、地域の人たちに危機感を促すということは大変必要なことだと思うんです。それは防犯防災上もそうですし、やっぱりこういうのは大切だと思っています。これは国から都に来て、都からまた落ちてきている段階の中で、さあっと見ただけでも疑問に思う点がいっぱいだと、私も思うんですが、いつごろお配りなるんですか。","respondent":"早津区民生活事業部次長","answer":"ちょっと私の説明の趣旨が誤解されているかもしれません。４月から、区民生活事業部のほうに移管してきましたのは、この計画を作成した段階で、今度は実施ということになってまいります。","voiceIndex":124,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"たしか、これは２年前ぐらいの総務委員会から始まったと思うんですが、去年の段階で中間報告を受けているということで、詰めていることは十分にわかりますので、この案件が出たのは総務委員会でやっているんです。その上で、この計画が東京都の承認をもらって品川区がつくったんですから、これは流れの中で、これはもう出していいと思うんです。","respondent":"田中区民生活事業部長","answer":"平成１８年度中に、区市町村でこれをつくって、法に基づいて実施していくということになっております。その点で、確かに選挙等がありましたが、議会に積み上げた中身、中間報告等を含めてやった中身を報告しております。ご意見も伺っております。","voiceIndex":129,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"確認ですが、総務委員会の中間報告をされたのが、いつの委員会なのか、後でも結構なので、教えていただきたい。〔「会派が知っている」と呼ぶ者あり〕それは個々に一人一人ですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":61391,"voices":135}},{"id":"h19-20070604-7","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"厚生委員会","time":"午後１時０３分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"宮崎副委員長","kind":"意見","question":"副委員長の共産党の宮崎です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"須藤委員","kind":"質問・要望","question":"自民党の須藤です。何もわかりませんので、よく教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護保険と障害者福祉のことをお聞きしたいと思います。介護保険は、いつも年度ごとに介護保険のまとめをつくられていると思うんですけれども、平成１８年度のまとめはいつ頃できるのかということと、今までもまとめができたときに厚生委員会で報告をいただいていますので、ぜひ報告をしていただきたいと思うんですけれども、そのことについてお聞かせください。","respondent":"上山介護保険担当課長、高橋障害者福祉課長","answer":"６月８日の介護保険制度推進委員会に運営状況を報告する予定ですので、今、準備作業を進めている状況にあります。実は、これまで介護保険制度推進委員会に先立ちまして厚生委員会にご報告をさせていただいておりました。先ほどの地域生活支援事業ですが、移行時期に８月の委員会で報告されているかと思います。今回、４月から移行されたものもありますので、調査項目になれば報告事項になるかと思います。","voiceIndex":57,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、介護保険制度推進委員会は傍聴できますけれども、傍聴者が意見を言うことはできませんし、介護保険制度推進委員会から報告されているものであれば、厚生委員会に資料を示していただいて報告をいただきたいということを要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-004"},{"speaker":"須藤委員","kind":"質問・要望","question":"教えていただきたいんですけれども、高齢者福祉の３７ページの介護認定審査の結果が出ているんですけれども、これは品川区内全体の結果という認識でいいのか。今、６５歳以上６万５,０００人という中で、要支援が０.７％、要支援１が２１.０％、これが現在の品川区の人数として把握していいのか。","respondent":"蓼沼高齢福祉課長","answer":"ご指摘ありましたように、これが区の認定者の状況です。","voiceIndex":61,"id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"特定高齢者は０.７％だけれども、こちらは０.０５％になっている。それから、要支援、要介護１から５という数がずっと違ってくるんです。１,０００人多いです。品川区として、そのあたりのチェックの仕方はどの程度、部局でも担当課長がよく見ていたけれどもわからなったという話が新聞に載っているけれども、そのあたりはどのように考えてチェックされているか、そのあたりを教えてください。","respondent":"蓼沼高齢福祉課長","answer":"実際に３月末現在で要介護認定を受けている方の人数というのは、１万７４人が実人数です。３７ページのものは審査の結果の内訳ですので、新規の方あるいは更新の方含めて延べ件数がここに掲載されているものではないかと考えます。","voiceIndex":63,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の手引きは２年に一遍変えるということで、今年度は変わる時期かと思っているんですけれども、変わるのか、変わるとしたらいつぐらいになるか教えていただきたい。それから、決算額を見ると、平成１８年度の決算が５３万円余に比べて、平成１９年度は９０５万円となっているんですけれども、この違いはどういうことなのかお聞かせいただきたいと思います。","respondent":"高橋障害者福祉課長、蓼沼高齢福祉課長、上山介護保険担当課長","answer":"区独自の軽減策についても、４月から実施しておりますので、当然、要綱で行っております。平成１０年からこの事業については開始されておりまして、事務事業概要にありますようなメンバーで。先ほども申し上げましたが、平成２１年度から第四期になりますので、第四期に向けての基礎的な調査を平成１９年度に実施したいということで。","voiceIndex":65,"id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"生活保護のところで伺いたいのですけれども、５ページの保護世帯・人員の推移のところで、平成１７年度から平成１８年度のところでは、品川区は１１.６％から１１.４％に落ちていますけれども、全都では上がっています。この要因といいますか、この辺はどのような評価をされているのか伺いたいと思います。私もいろいろ相談を受けるところで、そろそろ現実と矛盾が出てきていると思うのは住宅扶助です。","respondent":"志村生活福祉課長","answer":"ところが、平成１８年度は４９６件の開始に５００件の廃止ということで、平成４年以降統計を取って初めて開始より廃止が上回ったということがありますので、世の中の景気が若干兆しがあったのかなということもありますけれども。","voiceIndex":69,"id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問","question":"住宅扶助を品川区だけが上乗せというつもりで聞いているわけではないですけれども、現実的に例えば神奈川県と東京都は同じ基準です。もう少し、細かい対応を取られてもいいのではないか。生活保護のところで気になっている点が１点あるんですが、法外援助の件で伺いたいと思います。一方では生活保護の場合ですと、服の支給はこれだけですという逆をどのように考えているのか、そこのところはどうでしょうか。","respondent":"志村生活福祉課長","answer":"お尋ねの件ですけれども、実は昨年度から私どものほうでも対応について検討してまいりました。今、ご質問にありましたとおり、標準服という、いわゆる学則で定められた制服ではないということです。","voiceIndex":71,"id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"２万円の上乗せというのは、私は今初めて聞いたんですけれども、現実はもう少し高いのが現状のようなので、そこのところは品川区としても法外援護でいろいろ工夫できるところであれば、やはりいろいろ調整していただければと考えています。これも要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-010"}]},{"id":"topic-03","title":"続きまして、報告事項","agenda":"続きまして、報告事項","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞きしたいんですが、原小学校跡地の事業者の決定ということですけれども、指定管理者ではなく民設民営方式でやるということで、１月２２日の厚生委員会に報告がありました。もう一つは、インターネットで見ていましたら、個人情報保護の規定はありますけれども、情報公開の規定について書かれていなかったので、規定についてあるのかどうか教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"なぜ、指定管理者ではなく民設民営方式なのかというお尋ねですけれども、原小学校跡についての施設整備は、少子高齢化に対応するということで、高齢者の福祉施設、介護を受けながら住み続けられるための施設と幼保一元化施設、併せて西大井シルバーセンターの移転という。","voiceIndex":78,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"高優賃の制度で、新築は自治体も対象になるけれども、改修のほうがだめだということなんですけれども、ケアハウスの制度だったらばなれるんでしょうか。すると、そこら辺のケアハウスと高優賃の制度、高優賃というのは、多分初めてなんじゃないかと思うんですけれども、そこら辺の制度の違いについてもちょっと教えてください。","respondent":"蓼沼高齢福祉課長","answer":"ここの高優賃を活用する大きな理由は、当初はケアハウス制度ということも検討したわけですけれども、ケアハウス制度となりますと、いわゆる老人福祉施設という位置づけになりまして、避難路を２方向に確保しなくてはいけないというような基準が、縛りがかかってきます。","voiceIndex":80,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと詳しい設計だとか、建築基準法の関係だとか、そういうところはちょっとよくわからないんですけれども、福祉施設で２方向の避難路を確保しなくちゃいけないというところを、高優賃だと確保しなくていいというところで２方向確保がなくて大丈夫なのかということが１つと、それともう１つ、高優賃になると、所得によって減免があるというのもちょっと聞いたんですけれども。","respondent":"蓼沼高齢福祉課長","answer":"そのほかに、所得に応じて利用料が設定できるというところがあります。防災対策につきましては、そういう施設の中の区画ごとに防火扉を設置するという形で防災対策には万全な策を講じていきたいと考えています。","voiceIndex":82,"id":"exchange-013"},{"speaker":"宮崎副委員長","kind":"意見","question":"そういう中で、今度は、資金計画は弾力性があるということになると、何か言っていることがよくわからないなというのが実際のところなんですけれども、ここでは詳しいところまでは言えないにしても、大体わかりやすくそこら辺の考え方がどうなっていくのか、この４つの法人でもおそらくそこら辺の資金計画だとか、そういうのが出ていると思うんですけれども、私が見た感じでは。","respondent":"蓼沼高齢福祉課長","answer":"ただ、そういう意味でいえば、今回、地区を限っておりませんでしたので、対象は全国が対象ということになるわけですけれども、全国的に見ればこういう高齢者の施設と幼保の保育園等、子どもの施設を運営している事業者はかなりあるだろうということを聞いておりましたので。","voiceIndex":85,"id":"exchange-014"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと、あまりよくわからない説明だったんですけれども、私、ちょっと１点だけ意見を言いたいんです。そういうところですから、やっぱり区内の事業者からも非常に不満があります。ですから、こういう事業者との関係なんかも、もっともっと透明化を図っていくということをしないと、事業そのものが区民から、事業者も含めて信用を失っていくんではないかと、私はそういう心配を持っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":55951,"voices":91}},{"id":"h19-20070604-8","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"建設委員会","time":"午後１時０３分～午後３時１１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番目、幹部職員紹介","agenda":"の１番目、幹部職員紹介","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"自民党の石田です。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"井上委員","kind":"質問・要望","question":"どういう経過でそういうふうになったかということの説明と、きっちりと分けられるものではない部分について、それは所管は向こうだからというようなことにならないのかどうなのかというところを少し確認させていただきたいという２点をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-002"},{"speaker":"井上委員","kind":"提案","question":"それは議会の運営のことだと思いますから、そこは改めてそういう意見を申し伝えますけれども、それと緑化という部分に対して、道路公園課がされている緑化の部分というのは、到底八潮地域に関連した水とみどりのネットワーク構想の中のみどりということとは随分かけ離れたものだと思っているので、ぜひその辺はこの委員会で、委員長同士の協議が必要であればしていただきたいんですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-003"},{"speaker":"井上委員","kind":"提案","question":"だから、各派協議会とか、その辺の特別委員会設置について今私は言っているわけではなく、それはもう違うところの議論だと思いますので、緑化に対してこの建設委員会で必要な項目とか、そういうところがあって、その他の事項で多分問題が発生し、そのことについて調査を委員会としてすべきだという提案があった場合には。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":51,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"そうなると、品川区内には大きな建物をつくっている、いわゆる再開発事業も含めて、一番大きい事業者になってしまうのかなとニュースを聞いて思ったんです。２点目、それと概要の話でもう少し伺いたかったのが、いわゆる今期１年間、まちづくり事業部としてどこに一番力を入れたいというか、目玉というか、そこを何かお考えがあれば教えていただけますか。","respondent":"岩田まちづくり事業部長","answer":"物の考え方として、都市ですから、人間がここに住んで、生きて、動いて、仕事をするわけですから、そういった人間が生きていく上において都市はＣＯ２を出さないということはできません。","voiceIndex":53,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＣＯ２は発生を抑える工夫、努力というお話がありましたけれども、品川区として、今、再開発事業が次々と進んでおりますけれども、どれぐらいのＣＯ２が発生しているのか、それをどれぐらいまで抑えたいと思っているのか、そういう目標設定があるのかどうか、考え方を教えていただきたい。環境問題についてはそれです。","respondent":"青木都市開発課長","answer":"それを東京都とも連携いたしまして、個別の開発においては、それを例えば１割とか２割とか減らせるようにということは議論はしておりますけれども、現段階ではまだ技術的にどういった取り組みをすれば何％の削減が可能かということのデータが確立されておりませんので。","voiceIndex":55,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"住宅の方はお願いいたします。ＣＯ２のほうでデータの蓄積を待ってというお話でしたけれども、再開発事業に関しては、区も直接というか、主体的に動いているわけですよね。住宅の戸数の後、それを聞いた上でと思ったんですけれども、後で数だけ教えてください。販売価格はこの前の話の中で７,０００万円、適当だという話が出たけれども、販売価格というのはどういうふうにお考えなんですか。","respondent":"岩田まちづくり事業部長、青木都市開発課長","answer":"したがって、私が先ほどお答えしたのは、そういった最新の技術、こういったものを取り入れていくように行政としては指導をしているわけですから、隣の芝生を茫然と見守っているような、そういった立場では決してございませんで。住宅供給計画等につきましてはその事業のページでご確認いただきたいんですけれども、未定の部分も含めまして、私どもで現在報告を受けておりますものは、この大崎の６０ha囲んだ中では。","voiceIndex":57,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"要はどの住宅も高過ぎるんです。７,０００万円というのはあまりにも高いと思っていて、販売価格というのはどう考えているのか、先ほど伺ったけど直接ご答弁がなかったので、教えていただけますか。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"したがって、需要と供給の売り手と買い手の方々が需給のバランスで値段というのが設定されて、場所によっては７,０００万円台、場合によっては９,０００万円台というように価格が設定されて。一方で、国の統計調査によりますと、民間の賃貸住宅は１万５,０００戸空室になっている、ただ、高齢者、お子さんの多い世帯は貸し渋りに遭っている、こういった住宅困窮者の方を何とか今ある市場のあいている部屋に誘導できないか。","voiceIndex":60,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"ピークだった９４年のときに比べて平均の所得が５６３万８００円だと、下がっている、家計が苦しいと答える世帯が増えているという厚生労働省の発表がありましたよね。どういうふうに将来需要を図っているのか。ほんとうに一人ひとりの区民にとって必要な住宅と言えるのか、税金が投入されているわけですから、その点をちょっと伺いたいのが最後です。","respondent":"岩田まちづくり事業部長、齋藤住宅課長","answer":"委員のおっしゃった税を投入するからということですけれども、私どもは個々の分譲マンションにお金を投入しているわけではございませんで、いわゆる公共性のあるところ、共同部分とか、そういった部分に補助を出すのであって。廃止した後、住んでいる方は、新しく百人町、高田馬場の近くにロッテの工場がある新しいところか、港南にある都営住宅に引っ越してもらう、こういうことを東京都は計画しているということで、これは東京都が考えることでございまして。","voiceIndex":63,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうなったときに、まず区道、都道、国道というのがなぜ決まってきて、これは何で国道にしておかなくちゃいけない、これは何で都道にしておかなきゃいけない、これは区道になぜしておかなくちゃいけない、それにはメリット、デメリットがあるんだろうけれども、そこら辺の基本的な考え方というのを知らないので教えていただきたいのと、先ほど言ったように権限の移譲とか地方分権が進んでいて。","respondent":"松代管理工事課長、伊勢住環境整備担当課長、阿部都市計画課長、片田建築課長、齋藤住宅課長","answer":"そういったものの内容ですけれども、いろいろ切り口はあるかと思いますが、１つには道路の機能、役割分担、役割分類、そういったもので考えますと。そういうことも都市機構も、それから国もこの活用についていろいろとお話は出ていますので、これからはそういう活用を含めた形で研究していって。ただ、委員のご指摘がありましたけれども、一斉に地区計画を定める中で見直しをしていくという方向ですので。それともう１つ、体制的な部分では、専門家に対していろいろお願いをして、区民の耐震に対する相談とか。","voiceIndex":68,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だからそこで持っちゃったときのデメリットというのがあるのかなという気があるんだけれども、デメリットがもしあるなら教えてほしいけれども、私の感覚は、区民サービスをよくするのであればメリットのほうがあるような気がしてならないんだけれども、そこら辺の点の、国道はちょっと別として、都道の部分でお考えがあれば教えていただきたいのと、あとは細かいときにやりますが、ぜひひとつ。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"ただ、財源も含めて個々のケースで検証する必要があろうかと思いますが、都市計画道路等を見ましても、私どもも積極的に都道に通ずる整備等は区としてやっている状況にありますので、今後の広いそういった視点等の検討。いわゆる広域ネットを組む道路につきましては、幅員構成なり、意匠も含めて、統一性が保たれる必要があると思いますので、こういったものは今後の各２３区、東京都の話し合いの機会もありますので、私から意見をぶつけて。","voiceIndex":74,"id":"exchange-011"},{"speaker":"井上委員","kind":"意見","question":"１つは建築課のところで、多分、今回、まちづくり事業部で計画という形でつくっていこうというのは耐震のものだけだと思うんですけれども、ここは「策定し、助成対象の拡大を図っていきます」という大きな枠でしか書いていなかったので、これについてどのような、ちょっと中に入っちゃうかもしれませんが、スケジュールで、いつごろこれを出そうとしているのかということと、あと１つ。","respondent":"片田建築課長、松代管理工事課長","answer":"今のご質問で、木造住宅の耐震化の支援事業の、下のほうに、耐震改修計画の策定のスケジュールというか、ご質問でございましたけれども、実は４月の末に庁内の検討会、これを立ち上げまして、あと関係機関、消防署。今後ともそういった連携等を図りながら、最終的にはすばらしい商店街街並み等を進めていきたいと考えておるところです。","voiceIndex":77,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"地中化だと、その先のほうでは地中化事業があるので、また同じようにせっかくつくったあそこを掘り返して地中化をするということでは、同じことを倍の予算をかけて、そういう事業をすることが本当に区民のお金を使ってやることについてもあっていいのかなという、なかったのをやったのに、後からついてきた計画じゃなくて、計画があるにもかかわらず。","respondent":"松代管理工事課長","answer":"電線類地中化事業は当然掘り返して電線を地中に、それ以外のところでは、先ほど言いました旧東海道街並み整備事業というところで、新しい商店街灯をつけ、舗装も石畳にするといった区間でやっていますので。そういう中で当然今回の事業の１つの目標ですけれども、地元の負担も一定程度いただいて竣工すると、そういう中で北品川地区と戸越銀座地区の２カ所が電線の地中化ということで両商店街が手を挙げられて。","voiceIndex":80,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"商店街が、産業振興課がそこを管理しようとすれば、商店街ごとの議論になるわけですけれども、街並み再生といった道路整備を旧東海道整備をしていきましょうということになると、全体の所管がまちづくり事業部の道路管理、ハード面のところというふうに考えていかないと、あそこの道路のところを産業振興課がそこのところを担うという考え方では、でき上がったときに。","respondent":"岩田まちづくり事業部長","answer":"なぜなら、青物横丁商店街が非常に高価な石畳を地元で設置されてまだそんなに、１０年ぐらいしかたっておりませんので、あれをまた壊してつくり直すなんていうことは地元も望んでいませんし、区も望んでいないわけです。","voiceIndex":83,"id":"exchange-014"},{"speaker":"中塚委員","kind":"確認","question":"中身じゃないんですけれども、今、それぞれ目を通して、改めて今日確認するということですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"委員長から改めてこれをもう一回確認したいと思われる、その理由は何かございましたら。たしか前回の建設委員会では冒頭になかったので、今回はなぜかなという。ちょっと理由があれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":40503,"voices":94}},{"id":"h19-20070604-9","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"文教委員会","time":"午後１時０３分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"大沢副委員長","kind":"意見","question":"本年度、副委員長を仰せつかりました自民党の大沢です。文教委員会はいろいろと課題が多い、非常に重要なセクションだと考えております。一生懸命委員長を補佐し、また理事者の皆様方のお力添えを賜りながら委員会運営を進めてまいりたいと思いますので、よろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"山内委員","kind":"質問・要望","question":"こんにちは。自民党の山内晃です。この１年間、理事者の皆様とともに活発な議論をさせていただきたいと考えていますので、ひとつよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"},{"speaker":"金野委員","kind":"意見","question":"こんにちは。公明党の金野孝子です。今年１年、大変にお世話になります。品川の教育の向上に向けて一生懸命取り組んでまいりたい、頑張ってまいりたいと思います。どうぞよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-003"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そういう関係で耐震の問題も、校舎の耐震をずっと計画的に予算化されてきているんですけれども、あわせて担当の委員会として全体的なところをつかんでおきたいなと思うので、それもちょっとお伺いしたいと思います。それから、幾つかあるんですけれども、いいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"統計で全国的に統計をとっておられると思うんですけど、特に私が関心を持っているのは品川区の大気汚染との関係で、子どもたちの呼吸器の状況を、ちょっと調べていた資料を持ってこなかったので中途半端な質問になっちゃうと思うんですけど、学校の健康診断から見た子どもたちの呼吸器系の大気汚染等々による健康状況が、どういうふうになっているのかというのがもし具体的にあらわれていたら。","respondent":"市川庶務課長、古里学務課長、工藤品川図書館長","answer":"つまり基本的には平成２０年度までに必要な耐震補強工事を行いますということでこれまで説明を申し上げていました。私のほうからは学校基本調査に係るぜん息児童の状況、それから学級維持制度について説明を申し上げます。休館にあたりましては、７月２日から休館ですけれども、臨時窓口をぎりぎりまで、最大限７月２２日まで、工事期間に入っていますけれども。","voiceIndex":35,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"やりとりする場面ではないので、あまりこれ以上のことは質問するつもりはないんですけど、今の図書館もそれはそれで伺っておくということにしたいと思います。区民の声を伝えたということで、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"この仕切り方について確認したいということと、それからお願いごとがあるんですが、まずそれぞれの課のところで他課との連携というのがいろいろ出ているんですね。他課との仕切りがある程度決まっていって、この部分は文教委員会で議論しようとか、そういうところがあるのかどうか確認したいんですね。ただ内部的なところから５つの学校が２つになるというところにおいては、かなり議論しなければならない。","respondent":"市川庶務課長、富田生涯学習課長","answer":"それについて当委員会に報告をする際に、これは事前に委員長のほうに相談申し上げて、そのときに私ども教育委員会の説明だけでよいのか、あるいは補助的な何か説明をするのか、その辺は十分に事前に相談をさせていただいて。この辺はそれぞれのＰＴＡの方々の対象ですとか趣旨とかいったものがありますので、そういったところを踏まえて、どこの部分にお声をかけるのが望ましいのか等々といったことにつきましては、正副委員長ともよくご相談した上で。","voiceIndex":40,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"仕切りの件はいろいろ連携する中で、はっきり分けられない部分があると思いますので、その辺は十分にこちらのほうにも情報をいただきたいと考えています。いろいろ研究会とかをやっていますので、そういうのも私たちどんどん参加できるものなら、お知らせいただきたいなと考えていますので、よろしくお願いいたします。最後に指導課のほうで幼・保・小のところのくくりがどういうふうになっているのか。","respondent":"河野指導課長","answer":"ただ現在、保育課のほうが中心になっていわゆる就学前プログラムということで策定作業に入っておりますが、そういう部分については連携ということで、私どものほうからも委員ということで指導主事を派遣しておりますし、それから。","voiceIndex":43,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"その垣根を取り払って、スムーズに子どもたちの教育環境ができるようにというところで小中一貫校という形でできている部分もありますので、そこを幼・保・小という形での就学前と小学校との垣根というのを外しましょうというのが、今年の大きな大切なことではないかなと私は思うものですから、そこのところのかかわり方というのを、もう少しいろいろと議論していただきたいなというところがありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-009"},{"speaker":"山内委員","kind":"質問・要望","question":"私からは３つ質問をさせていただきたいと思います。勉強不足で、この文言についてまず１つお答えいただきたいと思うんですが、４８ページのＰＴＡ委託事業の中のＣＡＰワークショップというのを詳しく説明していただきたいと思います。これはそういう問題があるとなれば、この１年間しっかりと議論していかなくてはならないと考えていますので、その状況を教えていただきたいんですけれども。","respondent":"富田生涯学習課長、河野指導課長","answer":"１点目、家庭教育委託学級におけるＣＡＰの講習会についですが、これは全小学校で３年生と５年生を対象に、子どもたち、自分自身が暴力から自分を守るためのワークショップということで。学力定着度調査ですが、品川区で取り組んでいる教育改革が、子どもの学力向上にきちんと寄与しているのかどうかということをはかる物差しの１つとしても、活用させていただいたところです。","voiceIndex":46,"id":"exchange-010"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"２つお伺いさせていただきたいと思いますが、９ページに教育委員会の組織図がありますけれども、検討委員会がさまざまありますけれども、校長会代表２名、副校長会代表２名ということで、校長会なんかは代表が２名ということなんですが、この辺は委員構成で兼任をされるのか、それとも兼任はだめなのか、それを１つお伺いしたい。","respondent":"藤森小中一貫教育担当課長、市川庶務課長","answer":"今のご質問のまず１点目の組織、９ページの件ですけれども、もともと校長会とか副校長会自身にも組織がございまして、例えばいろいろな政策を立案していく組織だとか、あるいは各教科に分かれて、体育を専門に検討していく組織だとか。委員のほうからただいま２１ページのすまいるスクールの事業を引き合いにご質問がございましたので、確かに昨今、学力向上という面から、たしか平成１２年度から学校の完全週休２日制というのが始まったかと思うんですが。","voiceIndex":49,"id":"exchange-011"},{"speaker":"大沢副委員長","kind":"質問","question":"すまいるスクール、放課後全児童対策、子どもの居場所づくりということ、それと今の私のお話をさせていただいているゆとり教育の見直しでどのように、学力向上のために授業を開いていくという２つの階段の違うところにお話をさせていただきましたけれども、将来的に、学力定着度調査によって本区の学力は向上しているということは、わかるんですけれども。","respondent":"河野指導課長","answer":"今、教育再生会議等で学力向上策ということで週５日制見直し云々の議論が出ていることも承知しておりますが、最終的には今までの週５日制がまた新たに週６日制ということで、学習指導要領がその流れで改定されれば。","voiceIndex":52,"id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１つだけ質問させていただきたいんですが、４０ページのスクールカウンセラーの設置についてなんですが、区独自で区立小学校４０校を巡回するスクールカウンセラーを１４名配置すると。この１４名を配置する中で、どのくらいのスパンでその１４名が動いていくのかということと、いじめや不登校の未然防止などと書いてあるんですが、だれに向けてなのか。","respondent":"河野指導課長","answer":"スクールカウンセラーの実際の勤務が週１回ですので、このスクールカウンセラーが相当長期にわたる継続したカウンセリングというのはなかなか困難な点もありますので、そういう部分については区の教育センター等々と連携をして、場合によってはそちらのほうにつなぐ。","voiceIndex":54,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問・要望","question":"先ほど介助員制度の見直しというお話がありましたけれども、介助員制度は今までどういった形で介助員の方を採用していたのか、実際に私もその仕事をちょっとさせていただいたこともありましたので、実際のところ、専門的に発達障害のお子さんたちをどこまでわかっていて仕事をされていたのかというのが、お子さんを持つお母さんたちから、いろいろな意味でもう少し専門的にというお声もありましたので。","respondent":"河野指導課長","answer":"そのために、今度は特別支援教育の絡みになるわけですけれども、そういう子どもたちに本当に大切な支援は何なのかという視点、それから、従来の介助員はあくまでも非常勤、臨時の職員ということで対応しておりますので、継続的にお願いするというのが制度上難しいということ。","voiceIndex":56,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問・要望","question":"この発達障害児のお子さんは今、ちゃんと病名がついてこのような形でお子さんがふえている現状なので、今お話しいただいたのをぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"１点だけ、適正規模の関係なんですが、２６ページに平成１９年度に設置しますとなっているんですが、この基本的な考え方というか、なぜこの検討会を設置するのか、何を議論する予定にしているのか、ここだけだと読み取りにくいので、その説明をいただきたいと思います。","respondent":"古里学務課長","answer":"望ましい子どもたちの教育環境というのはどういうものかということを、これからは検討していかなければいけないですので、そういう方向で今、検討を進めているところでございまして、概要が出る中で当委員会に詳細は別途報告をさせていただきたいと考えています。","voiceIndex":59,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"これからのものですから、これからの検討というか、報告を待ちたいと思うんですけれども、大事なことは、関係者というか、教育を受ける子どもの側、親の意見、そして教育関係者、専門家も含めて、学校の現場の先生方はもちろんですけれども、そういう総合的な意見、いろいろな議論を活発にして、学校とはどうあるべきなのかということを検討していっていただきたいと思うんです。","respondent":"古里学務課長","answer":"先ほどお話ししたとおり、詳細については別途ということでお願いをしたいと思います。現在のところ、どうというプランはまだ描いているものではございませんので、論議の過程の中で、委員としてどのような方をお迎えするのかということも詳細を詰めてまいりたいと思います。","voiceIndex":61,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"１年とも２年ともこの検討期間は書いていないので、その期間をどのくらいの規模で検討していきたいと考えておられるのか、そこだけ最後に伺って終わりたいと思います。","respondent":"古里学務課長","answer":"そういう新しい状況も踏まえながら現在検討をしているというところで、ご理解をいただければと思います。","voiceIndex":63,"id":"exchange-018"},{"speaker":"若林委員長","kind":"提案","question":"ないようですので、今後の委員会運営につきまして、私のほうからご提案をさせていただきたいと思います。委員会の活性化のために、議案、報告事項の審査、調査以外にも所管事務について調査をしてはどうかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":37462,"voices":68}},{"id":"h19-20070604-5","meetingId":"h19-cm06","date":"2007年6月4日","dateIso":"2007-06-04","committee":"総務委員会","time":"午後１時０３分～午後２時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、幹部職員紹介","agenda":"の１、幹部職員紹介","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"自民党の伊藤です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"の２、事務事業概要","agenda":"の２、事務事業概要","exchanges":[{"speaker":"菊地委員","kind":"提案","question":"それと、総務のほうで一番最後にありますけれども、危機管理室のところで、国民保護に関する事務を今度から防災課に移管しますよという話で、条例ができたときには総務委員会で審議がされて、それから、この計画の案の段階で総務委員会で審議する時間がなかったというのもあるんですけれども、総務委員会に提案をされたという覚えがあるんですけれども。","respondent":"福島長期計画担当課長、桑村危機管理室長","answer":"基本構想ならびに長期基本計画の策定ですけれども、今年度６月からですけれども、策定委員会を設けまして検討に入ってあります。こちらの内容等の報告につきましては、総務委員会で適宜行っていきたいと考えています。今回、防災課に動かした理由ですけれども、１つは東京都との体制も基本的に防災の体制でやっていくということもありますし、また実際、その国民保護計画のつくり方ですけれども。","voiceIndex":54,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"今の保護計画のほうなんですけれども、これを策定をする段階で防災協議会の委員がそのまま横すべりというのか、そういう形でこの計画を策定されていくということですけれども、そうすると、この策定をされた時点で、この協議会そのものというのはこれで消滅をしたものだというふうにとらえていていいんでしょうかね。危機管理室との関係でちょっとそこを。","respondent":"桑村危機管理室長","answer":"その意味で、また協議会のほうで計画自体をもう一遍検討していただくときには、その辺の検討をしていただくのが適当だろうです。","voiceIndex":57,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"最後に、そうすると協議会そのものは生きていて練り直さなくちゃならないときというのは、また総務委員会にかかってくるという考え方でいいですか。","respondent":"桑村危機管理室長","answer":"協議会自体の今後の運営も防災課が基本的に主体にやってまいりますので、委員会の説明は区民委員会でお願いしたいというのが私どもの考えです。ですので、必要があったときには区民委員会のほうにかけさせていただきたいと思います。","voiceIndex":59,"id":"exchange-004"}]},{"id":"topic-03","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"それがまた平成１８年度にまた法律が変わったのかどうか知りませんけど、これが施行されて早くやりなさいよという話になっていますよということですから、そこはどういう基準でやって、そのときの判断の望ましい耐震性能というのは何なのというところです。というのは、それが変わると、がらりと変わる可能性だって出てくるわけなので、それがまず基本だろうと思うので聞かせてください。","respondent":"宍戸施設担当課長","answer":"したがいまして、小中学校等でいろいろ基準が幾つもあって、補強し直しているというふうな部分がありますけれども、今回につきましては最初からＩｓ値０.７５以上を目標としてやってありますので、そういったことは一切ないというふうに考えております。","voiceIndex":66,"id":"exchange-005"},{"speaker":"土井委員","kind":"意見","question":"それは要するにぐらぐら来てもひびはいってもつぶれないよ。しばらくしたら、上がってきたから０.８にしようなんていう話になってきたらどうするのかという話になりますから、これはこれで最終なんですねということで、国土交通省なり何なりで一応お墨つきをきちんと０.７５としたのか、それとも我々として１.２５倍にしておいたほうがもっといいだろうという数字なのかを含めて、もう１回お願いします。","respondent":"宍戸施設担当課長","answer":"免震工法という特殊な工法ということもございまして、国土交通省の耐震認定というふうなものを受けるということでございまして、そちらのほうからもきちっとしたお墨つきをもらうというふうなこともありますので、耐震上全く問題はないというふうに考えております。","voiceIndex":68,"id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"わかりました。上には上をというのはある意味では非常にいいことなんです。その意味での０.７５というのは、要するに今のところ国土交通省等も含めて相当レベルに大丈夫だということでお墨つきの出る中身のものですよということで、法で決まっているわけではないのかどうかということだけ聞かせてください。","respondent":"宍戸施設担当課長","answer":"法で定められているのはあくまでも告示ですけれども０.６以上というふうなことが、法律で言われているものでございまして、０.７５というのは推奨している数値です。","voiceIndex":70,"id":"exchange-007"},{"speaker":"土井委員","kind":"意見","question":"わかりましたというしかしようがない。これはやりとりしても仕方がないんだけれども、とある企業では安全率を、細かい金額を全部見ていったら、最後によくよく見たら３倍ぐらいの強度になっているというばかなことをやっているという結果があったものもあるわけですね。いずれにしろ、今のところこれだというならこれでやるしかしようがないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-008"},{"speaker":"原委員","kind":"質問・要望","question":"概算工事、これは約３４億円ということなんですけれども、これから詰めていくと思うんですが、漠然としておりますけれども、法務局、先ほどご説明がありました区分所有ということになっておりまして、そうすると、それがこの金額の中の全体の中に入っているか入っていないのか、お聞かせいただきたいと思います。","respondent":"中島経理課長","answer":"概算工事全体で約３４億円でございまして、区分所有というお話がございましたけれども、区分所有の率でもってこの工事費を東京都と国のほうで負担してもらうということです。","voiceIndex":73,"id":"exchange-009"},{"speaker":"原委員","kind":"質問","question":"当然これは法務局のほうは電子化になってきますので、ここに限らず法務局の場合には全部自分のところで持っているというのが基本的ルールですので、今後においてだんだんだんだんと役割先細りという表現をしていいのかわかりませんが、そういう形でなるべく小さくまとめていこうという国の考えになっていこうかと思うんですけれども、ですから。","respondent":"中島経理課長","answer":"法務局に関しましては、かつて平成１０年ぐらいに出張所の移転の問題がございまして、法務局との関係では当分の間、先送りするというお話がありまして、私どもつい最近、法務局でその辺の話を伺ってまいりました。","voiceIndex":75,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"確認","question":"参考資料の見方なんですけれども、一番左がこれが本庁舎です。真ん中が議会棟、第三庁舎ということでいいかという確認、参考資料の上のほうですね。ですから、確かに補強はわかるんですけれども、一定の損傷の可能性が高いというリスクを抱えたままでこの案を選んだ理由というのは理解できないんですが、ご説明をお願いしたい。その２つです、見方とそのこと。","respondent":"宍戸施設担当課長","answer":"図面の見方ですけれども、一番左側が第三庁舎も含めてすべて免震構造で。","voiceIndex":77,"id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"だから、もう一つ確認したいのが、なぜケースＡのほうにしなかったんでしょうかね、この第三庁舎を。同じやるのであれば、同じすべての品川区の庁舎を免震構造にしたほうが、単純に区民サービスが上がっていくだろうし、災害拠点として考えるということであれば、そちらよりよいと思うんですが、あえてこの第三庁舎だけを耐震構造にしたということをもう少し説明いただきたいんですが。","respondent":"田中総務部長","answer":"このケースＡ、Ｂ、Ｃを私どもで検討させていただいたわけですが、委員がおっしゃるように、Ａならば免震というのは、全部地震の波を逃がしますのでより望ましいということが、地震対策から言えば有効だというふうに考えております。","voiceIndex":81,"id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"さっき原委員からあった法務局との関係で工事費のお話がありましたけれども、例えば３４億円実際にかかりましたといったときに、国の負担割合、都の負担割合、その辺具体的に教えていただきたいのと、それからもう一つ、耐震工事をすることで庁舎そのものの、もちろん地震に対するものですから、老朽化を防ぐというものでは、また全然別問題なんだと思うんですけれども。","respondent":"中島経理課長、宍戸施設担当課長","answer":"１点目の国と東京都と区の負担割合ですけれども、まず国のほう全体の約２.２６％です。東京都が約２１.２５％、残り７６.４９％が品川区です。これは持ち分の割合によって定められた率です。ただ、躯体といたしましては設備と違いまして約６５年間もつということがありますので、そういった意味では通常の設備や何かの更新工事を地道にやることと組み合わせて。","voiceIndex":84,"id":"exchange-013"},{"speaker":"浅野委員","kind":"質問・要望","question":"どの方法をとったとしても大体３年ぐらいの工期がかかるかと思うんですけれども、この庁舎が最初建てられたとき、どういう状況だったか私も認識はしていないんですけれども、３年間にわたって工事を行うとなりますと、やはりかなりの物資の搬入ですとか、またいろいろな廃棄物なども出るかと思うんですけれども、環境にやさしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-014"},{"speaker":"林委員長","kind":"提案","question":"初めに、本年度の委員会運営について皆様からご意見をいただきたいと思います。それが委員会活性化という何年か前に出された形を具体化しているという点です。あるいは課題、調査事項等をあらかじめ決めおいて、皆さん方とあるいは理事者からの意見、説明等を受けながら委員会を運営していきたいと思いますけれども、そういう所管事務調査ということについてのご提案を、まずはいただきたいと思いますけど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"今年は品川議会全体として都区制度にかかわる特別委員会をつくらなかった経緯があります。これは我が品川区が前区長をはじめとして議会側も含めてこれの取り組みをがっちりとやってきたわけですから、この伝統を守っていくためにもこの後、この総務委員会でしっかりと審査、調査をしていくべき。最重要課題に近いんじゃないかなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1750#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":31798,"voices":105}},{"id":"h19-20070605-14","meetingId":"h19-cm06","date":"2007年6月5日","dateIso":"2007-06-05","committee":"行財政改革特別委員会","time":"午後１時０３分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"武内委員","kind":"質問","question":"先ほど、４番のほうで議決を要する契約ということで、これについては区の条例でというお話があったんですが、２番の契約方法の中の、例えば（１）の制限付き一般競争入札のところの例で、工事案件では１,０００万円以上が対象ですとか、また（２）番のほうの指名競争入札のところの例で、工事案件では１３０万円を超えるものが対象とか、いろいろこういった金額があるんですが、これについては。","respondent":"中島経理課長","answer":"基本的に地方自治法で定めている部分と、それを受けまして地方自治法の施行令で、例えば随意契約の１３０万円以下の金額とか、具体的に施行令のほうでそれを受けて実施しておりまして、さらにそれを品川区の契約規則で受けてやっているという、体系的に整理されたものです。","voiceIndex":30,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"この２番の契約方法の４種類を今挙げていただいたんですが、例えば品川区の昨年実績でも結構なんですけれども、大体の割合、例えば（１）番が何割ぐらいという、（４）番は多分ないと思うんですが、その辺のことを大体で結構なので、わかれば教えていただきたい。","respondent":"中島経理課長","answer":"工事案件で申し上げますと、随意契約、これは見積もり合わせ等を含めまして、全体の約４８％です。それと、指名競争入札、こちらが３４％、制限付き一般競争入札、これが１８％という構成になってあります。","voiceIndex":32,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、先ほど、（３）番の随意契約のところで、１３０万円以下のものと、それから緊急性があって入札の時間的な余裕がないような場合などというようなご説明があったんですけれども、比較的緊急性の高いもの、もしくは１３０万円以下ということなんですが、４８％ということで半分近くが随意契約という形になっているんですけれども、その理由としては、この１３０万円以下のものが占めているのか。","respondent":"中島経理課長","answer":"そのほか、いわゆる業者推薦というのが先ほど言われた緊急性があるとか、そこの業者でなければできないものとかいろいろあるわけですけれども、そういったものが３３件ということで、ほとんどは金額でやられているです。","voiceIndex":34,"id":"exchange-003"},{"speaker":"武内委員","kind":"意見","question":"それから次に、裏面のほうで一番下の＊４番の簡易型総合評価方式というところで、今年の４月から試行実施されたというお話があって、調理業務代行とか駐車場の管理ということでお話があったんですけれども、例えば、学校の調理業務のほうなんかも、もちろん金額だけではなくて、品質確保という部分とか、いろいろな仕事に支障を来さない、さまざまな要件があると思うんですけれども。","respondent":"中島経理課長","answer":"例えば、１,０００万円で入れたら８０点だとしますと、９００万で入れたところが９０点とか、要するに、安いほうが点が高くなるということです。","voiceIndex":36,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"だから、例えば契約のときに今の体制ですとか、実績とかということも留意点という形で、どれぐらいの割合かわからないんですけれども入れられているということなんですけれども、それがすべてではないと思うんですけれども、例えばそういうことも価格とバランスというんですか、例えば、仕事によってそれは違ってくると思うんですけれども、そういった仕事によっては。","respondent":"中島経理課長","answer":"ただいま給食のお話がございましたけれども、私ども、実は今回、駐車場の管理業務の委託を総合評価方式でやりまして、それは私も直接評定委員というか、面接委員になったわけですけれども、そのときには、当然先ほど申し上げました研修体制の問題とか、あるいは、今回。","voiceIndex":38,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"先ほどの総合評価方式のご説明の中で、価格と技術点をポイント化してということなんですけれども、このポイントというのは、工事あるいは契約ごとに何をどのくらいのポイントにするかということは変わっていくんですか。それとも一律のものがあって、それに当てはめていくのでしょうか。その配点によってかなり結果が左右されるかなと思うんですが、教えてください。","respondent":"中島経理課長","answer":"初めに、平成１８年度の契約方法ごとの件数ですけれども、先ほど、工事関係のご説明をいたしました。先ほどの数字は３月１日現在ということで、一月ブランクがありますけれども、３月はほとんど契約はしませんのでご了解いただきたいと思います。","voiceIndex":40,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"先ほどの契約の数字なんですけれども、ちょっと手がついていかなくて、今、１枚物を読み上げていらしたみたいなので、後で資料としていただければありがたいなと思います。今、それぞれ件数でのご説明でしたけれども、それぞれが結局、年間で金額では幾らになったのかということもわかれば、あわせて。後で結構ですので教えていただければ。大体で結構です。できればお願いします。","respondent":"中島経理課長","answer":"資料につきましては、委員会が終わってから委員長とご相談させていただきたいと思います。","voiceIndex":42,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"数字的なところは後から資料をいただければと思いますが、ちょっと１つだけ、４種類の契約の種類について伺いたいと思ったのは、先ほどの説明の中で、それぞれ工事案件に関する割合がありましたけれども、この契約の方法は、一番多いのは工事案件ということなんでしょうか。","respondent":"中島経理課長、田中総務部長","answer":"全体の件数で言いますと、圧倒的に多いのが物品の契約と、委託契約です。この先ほどのあれで、合計で約４,０００件弱あるんですけれども、そのうち約３,４００件が物品購入と委託契約です。各委員からいろいろご意見をいただいておりますが、きょうは実はこの枠組みといいますか、どんなものがあるかというところを概要説明させていただきたいと思いますので、次回以降、もしそういう意味での数字的な資料等。","voiceIndex":44,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこは不勉強なところもあるので、ちょっと教えていただきたかったのは、例えば、指定管理者制度であると、候補者として選定できない団体というのが自治体によっては条例で定められている場合もありまして、この今説明のあった４つの中で、４つ目はないかもしれませんけれども、契約としてできない団体というのか、そういうルールがあるのかご説明いただけますでしょうか。","respondent":"中島経理課長","answer":"そちらはできます。逆に言いますと、原則的な考え方で行きますと、それ以外はできないということになります。いろいろな各事業者でありますけれども、まずは登録をしていただくということが大前提ですので、登録をされていない業者につきましては契約はできないです。","voiceIndex":48,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、先ほどのやりとりの中で、この資料の一番最後のところで、今年の４月からなんでしょうか、簡易型総合評価方式が始まったということですけれども、これを導入するに当たっての背景などがございましたら、もう少しご説明いただけたらなと思います。","respondent":"中島経理課長","answer":"ですから、まだ準備段階です。そういったことで、工事がすぐにできないのであれば、委託契約関係で可能かどうかということで、平成１８年度に検討してきた結果、試行ですけれども、何とか委託であれば可能であろうということでやってあります。この４月からの契約で始めました。","voiceIndex":50,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどから契約できない団体について質問したのでそれについて教えていただきたいと思います。","respondent":"田中総務部長","answer":"例えば今度はまた指名をということの条件になりますと、いわゆる指名停止という談合をやらせて云々という、そういうこともいろいろございまして、欠格自体が一概に言えるものではないということで、一番基本的なところは。","voiceIndex":53,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"それを伺ったのは、今ちょうど大阪での清掃工場建設をめぐる大林組の談合のことがニュースになっておりまして、こうしたゼネコンが、ちなみにこの大林組というのは、談合事件は今回だけではなくて、過去にも和歌山県や名古屋市でも繰り返し繰り返しそういう事件を起こしているわけですね。","respondent":"中島経理課長","answer":"そういった意味では、その期間に入っている場合につきましては、もちろん契約できない。あるいは入札の参加資格もないということになりますので、その辺のまた細かい、具体的にこういう場合はこうですよというのは、今後の中でご説明させていただきたいと考えています。","voiceIndex":55,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のところのお話で、資格要件については、ぜひ今後、たくさん細かくあると思うので、今後教えていただきたいなと思いますけれども、あと、この契約のタイプによっても、選定基準とか、選定方法がどうなっているのかというところを１つ教えていただきたいのと、あと、資料の裏面のところの共同企業体へのＪＶのことなんですけれども、多分この昭和５３年からこの方式がとられて。","respondent":"中島経理課長","answer":"それで、出資割合ですけれども、基本的に厳密に決まっているわけではないですけれども、大体６対４、あるいは７対３ぐらいの割合で実施していることが多くあります。","voiceIndex":57,"id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"きょうは概要ということなので２点と、それからあと資料の件、時間が限られておりますので、１点だけお願いということで。ということは、双務契約という解釈で、片務契約自体はその程度のものだと解釈してよろしいのでしょうか。契約の基本的な概念として。きょうは概要なのであんまり深く入りませんけれども、基本的には双務契約をしていくよということでよろしいでしょうか。","respondent":"中島経理課長","answer":"そのとおりです。","voiceIndex":59,"id":"exchange-014"},{"speaker":"原委員","kind":"質問","question":"２つ目、概要として、裏面のところなんですけれども、基本的に簡易型という、平成３年６月、簡易なプロポーザルによる事業者の選定、この簡易型プロポーザル方式、これ、言葉が違うんですけれども、内容的なもの、あとそれから一番最後のところの＊４のところで、簡易型総合評価方式、簡易型というのを行政用語ということで解釈するのかもわからないんですけれども、ということは。","respondent":"中島経理課長","answer":"いわゆる公募型プロポーザルとかありますけれども、簡易でないプロポーザルはあります。それに対して、よく手続き等を若干簡略したものを簡易型あるいは簡易なプロポーザル方式と呼んでいるです。総合評価方式も基本的にはそういう概念です。","voiceIndex":61,"id":"exchange-015"},{"speaker":"原委員","kind":"質問・要望","question":"それに関連して、これは要望という形で、若干時間がかかろうかと思いますので。これ、反比例の状態になろうかと思いますので。","respondent":"中島経理課長","answer":"本委員会が終わってから、委員長、副委員長とご相談をさせていただきたいというふうに思っております。","voiceIndex":63,"id":"exchange-016"},{"speaker":"山内委員","kind":"質問","question":"（２）番指名競争入札になりますと、入札参加者を指名して入札を行うといった場合に、この（１）番の条件を満たしているところが、じゃあ、（２）番のこの指名競争入札に入札をしてきた場合というのは、結構やはり（１）番の条件を満たしている会社というか、そういうところが比較的入札をする可能性が高いのではないかなというような推測をするんですけれども。","respondent":"中島経理課長","answer":"済みません、私の説明の仕方が十分でなかったのかもわかりませんけれども、この（１）の制限付き一般競争入札というのは、いわゆる公募、応募してくる形です。","voiceIndex":65,"id":"exchange-017"},{"speaker":"山内委員","kind":"確認","question":"確認なんですが、（１）番は基本的には大手ゼネコンというか、いわゆる名の知れたゼネコンということでしょうか。","respondent":"中島経理課長","answer":"必ずしもそういうわけではございません。例えば工事で１,０００万円以上の工事は制限付きでやりますので、大きくない会社がやるのももちろん入ってあります。","voiceIndex":67,"id":"exchange-018"},{"speaker":"林委員","kind":"質問","question":"議決を要するところの話なんですけれども、土地については１件５,０００m2以上という、その５,０００m2という基本的な考え方はどこにあるんですか。","respondent":"田中総務部長","answer":"それを１億８,０００万円に上げる際に、この９,０００万円は、参考までにこう報告させていただこうというような経過を踏んできているです。","voiceIndex":69,"id":"exchange-019"},{"speaker":"林委員","kind":"意見","question":"５,０００m2、価格については４,０００万円。この数字をどうとらえますか。５,０００m2で４,０００万円はあり得ますか。","respondent":"中島経理課長","answer":"土地については、やっぱり場所にものすごく差がありますので、そういった意味で、土地につきましては、面積で規定して、建物についてはこの４,０００万円で規定していいのではなかろうかというふうに考えてあります。","voiceIndex":71,"id":"exchange-020"},{"speaker":"林委員","kind":"質問・要望","question":"非常に議決という我々にとって大事な問題なのでこれからやっていきたいと思いますけれども、さっきも５,０００m2という、それこそ概念としてはいわゆる時間がかかるというようなところでの判断で、今、議会がきちんと仕事をしていく上で、どういう数字を私たちが求めていくかというのは、これからこの委員会できちんとやっていかないといけないと思うんだけれども、もう少し答えを用意しておいてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-021"}]},{"id":"topic-02","title":"第２点目の財政（歳入）に関すること","agenda":"第２点目の財政（歳入）に関すること","exchanges":[{"speaker":"武内委員","kind":"質問","question":"この資料の一番上に、歳入の歳が年齢の「才」になっているんですけれども、これは何か意味があるんですか。単純な間違いなのか、これでいいのか、それだけ教えてください。","respondent":"日下部企画財政課長","answer":"失礼いたしました。そうですね、かなり簡略化した形で、略字とちゃんとしたものが混同しておりました。大変失礼いたしました。今後は気をつけたいと思います。","voiceIndex":78,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"何点かお伺いしたいといいますか、教えていただきたいと思っているんですけれども、歳入について、区の基本的な姿勢といいますか、考え方というか、もっと言えば、目指している姿というか、そういうところの何か考えていることが少し整理して教えていただきたいと思ったのが１つです。その辺をちょっとお伺いしたいのが１点目です。","respondent":"日下部企画財政課長","answer":"２つのご質問とも非常に難しいご質問でございまして、十分にお答えできるかどうかわかりませんけれども、１点目の目指している姿ですけれども、具体的に、例えばいろいろなものを私もまだ勉強途中ですから、いろいろなものを自治体の財政関係のものを読みましても。","voiceIndex":80,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺で、法人税のところの税率が定率減税がもとに戻ったというのと同じように、もとに戻った場合に、その辺の税収がどう変化をしていくのかというところを１点教えていただきたいのと、あと、株式等譲渡所得割交付金、このところも株の売買益のところなんですけれども、ここも増えているんですけれども、この株式譲渡の場合の税率についても、減税のまま推移していると思うんですね。","respondent":"日下部企画財政課長","answer":"株式の関係につきましても、税率が５％かかって、都が２％とか、３％という、その程度のことは承知をしておりますが、今ご質問にあったような点については、ちょっとわかりかねますので、これについてもご容赦をいただきたいと思います。","voiceIndex":82,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"庶民の定率減税が廃止されて、庶民はこの間、区の説明ではもとに戻ったという説明ですが、現実的には、年度別に比較していくと、増税になって負担増になっているという中において、法人税関係と株式譲渡に関しては、相変わらず減税のままでいるにもかかわらず、ここのところが伸びているということでは、もとの税率に戻ったら、区に入る税収がもっと増えるというような解釈でいいのかどうか。","respondent":"日下部企画財政課長","answer":"消費税のほうから申し上げますと、先ほどもちょっとご説明させていただきました。私ども、何か物を買えば５％消費税がとられます。そのうち４％は国税です。１％は地方消費税ということで、これは地方税です。ただ、国が一括してこれを徴収する。","voiceIndex":84,"id":"exchange-025"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"繰り返しにはなるところもありますけれども、先ほど議論のあった契約方式の種類、４つのところ、それぞれ具体的にどういうところがあるのか、件数や金額、必要なところの資料を用意していただきたいと思ったのが１点と、それと、指名停止基準があるというお話が理事者のほうからありましたけれども、そのほか例えば随意契約の中でもそういう基準があるのかなと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-026"},{"speaker":"林委員","kind":"提案","question":"契約のあり方ということで、行財政改革という視点からすると、さまざま今まで区が行ってきた契約案件について、さらに行財政改革という考え方からできること、あるいはやらなければいけないこと、あるいは、議会側からは、こういうことはできないのか、あるいはこういうことをしなさいというような、そういうやりとりをしていかなければ、行財政改革特別委員会でただ単に契約のあり方を取り上げていたのでは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-027"},{"speaker":"中塚委員","kind":"意見","question":"ちょっと意見を述べたいんですけれども、もちろん行革と言っても、いろいろな意味での行革があると思っているんですね。おのおのがそれぞれの行革の視点で語るのは大事ですけれども、そもそもこの行革というのは、住民サービス向上に向けたものというのは何なのかという、そもそもの議論をお互い深めていくのも大事な点かなと思いますので、意見だけ述べさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5818#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":34326,"voices":92}},{"id":"h19-20070606-16","meetingId":"h19-cm06","date":"2007年6月6日","dateIso":"2007-06-06","committee":"街づくり特別委員会","time":"午後１時０３分～午後２時４３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本間副委員長","kind":"意見","question":"副委員長の本間隆です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":3,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"自民党の石田です。どうぞよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-002"},{"speaker":"稲川委員","kind":"意見","question":"民主党の稲川貴之です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-003"}]},{"id":"topic-02","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"８ページでまちづくり検討会のほうが立ち上がっているというご説明がありまして、区としても連携していきたいということでご説明があったんですけれども、最後にこの検討会のほうが取りまとめた案を行政に具申したいとまとめているんですけれども、どういう形で具体的な連携、協力というのは行われるのかなということを伺えればと思ったのと、それから八潮に話を戻すわけなんですけれども。","respondent":"日下部企画財政課長","answer":"それからまちづくり検討会と区側との連携協力ということでありますけれども、今回、６月号にこういう形で自治会連合会としての提案が出ておりますけれども、５月に私ども八潮の連合会ともいろいろ意見交換しました際に、自治会のほうとしては。","voiceIndex":46,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"すみません、検討会のことなんですが、このメンバーの中には、区側の方はメンバーとして入られるものか、ちょっとお伺いしたいんですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-005"},{"speaker":"南委員","kind":"提案","question":"この八潮地区のまちづくりについての区の立場なんですけど、確かに私も八潮に住んでいますけど、子どもたちの数が減って、小中一貫校で学校が統合されていくという現状はあるし、住んでいても、私たち入居した当初に比べて、やっぱりまちの状況というのは違うというのは実感としてありますし、区のほうも心配していただいている商業施設の部分で、やっぱりさま変わりしているというのは。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"だって、具体的に説明しているからいいんじゃないですか。","respondent":"山路委員長、日下部企画財政課長","answer":"概要の説明だけをやってもらったんですが。企画財政課長、答えられる範囲で。概要説明の答弁ということで。やはりまちづくりを進めるときは、そういう地域の状況全体について、やはり行政がしっかりとらえて、例えば「さあ、皆さん、どうしましょうか」では、これはやっぱり意見はまとまらないわけですから。","voiceIndex":59,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"今はどちらをどちらということではないというお話なので、今後の議論、まちの方々の意見も踏まえて、この委員会として積極的に調査研究を進めていければいいかなと思っているんですけれども、やっぱり一番最初のところですから、確認しておきたいと思ったんですけど、住民自治ということで、大事にしていく、押さえなければいけないところだと思いますので、そこの点だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"内容については後で意見を言いますけれども、水族館まで入ったし、後で考え方は言いますけれども、１つだけわからないことを教えていただきたいんですが、新・水とみどりのネットワーク構想について、２枚目の「ものづくり」というところなんですが、これはパブリックコメントも出てくるということなので、もう一回しっかり読ませていただきますが、参考というところ。","respondent":"松代管理工事課長","answer":"ですから、この表現の仕方というのは次回、また詳しく細かなところを入れましてご説明をしますが、地球環境、そういったものの流れ、国の取り組み、東京都の取り組み、また区として何ができるのか。区が何をしなければいけないのか。","voiceIndex":68,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問","question":"別にあまり言うあれでもないんだけれども、みどり豊かなまちづくりのこういう項目は大賛成だし、非常にいいことだと私は思っていますし、いいんだけれども、今言った、大上段に振りかざすわけじゃないけれども、品川区のこの地域性を考えたら、この部分、４キロ四方を全部緑化にしたって、たかが知れている効果なわけじゃないですか。日本全体を見れば。思ったことだけ言っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-010"}]},{"id":"topic-03","title":"の３、その他","agenda":"の３、その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"八潮のことを考えると、もちろん地域の方々のお考え、要望、そういうものも大切だろうけれども、あそこの地域がそれだけで、また以前のような活気が取り戻せるのか。地区の要望として、要望の中で対応していくのか。それから、水とみどりの推進は、報告で我々が聞いて、それに対する質問をするような形じゃなくて、ぜひそこで議論をできるような進め方をぜひしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-011"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、学校の施設跡の有効活用ももちろん中心的にやって、それで今、基本的な考え方は説明いただきましたけれども、住宅の住み替えですとか、商業施設の再構築、地域の活性化に向けた取り組みと、地区計画への移行ですか、その辺全体をやっていくと、これだけでも相当なボリュームがあると思いますので、それをしっかりと企画、まちづくり、教育委員会の学務課それぞれの分野でしっかりとやって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"八潮地区の基本的な考え方でちょっとお聞きしたいんですが、住宅の住み替えや商業施設再構築という、地域の活性化に向けてさまざまな課題解決の方策について、具体的な検討を進めますと。逆に今度、商業施設の活性化を求める。ちょっと相矛盾しているような感じがするんですね。その辺もちょっと大きな論点の１つだと思うんですが、その辺、区のお考えをお聞かせいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-013"},{"speaker":"南委員","kind":"提案","question":"八潮は、いろいろな制約があったりしたという話があったように、一団地計画ということで、民間の所有地じゃないわけですから、非常に難しいですよね。こうやるべきだというのは、私はさっきも言ったように、住民自治ですから、まちの皆さんに２４年間住んでもらって、ここのところはこうしたいけれども、ならなかった。わからない。だから、正副のところでちょっと整理していただいてやっていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":78,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"意見","question":"住んでいるからどうという話じゃないじゃない。議会の話だもの。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問します。きょうの調査事項概要のことをお伺いしたいんですが、最初に八潮地区のまちづくりについてということで説明をいただきました。地区計画、そして水とみどりのネットワーク、松代管理工事課長までは一本の線が通っているんですが、ここでまた、確かに八潮地区ですから、水辺ということでわかるんですが、なぜこれは道路公園課の水とみどりが出てきて、立会川、目黒川という説明がされたのか。","respondent":"山路委員長","answer":"ご意見、ご要望をお伺いする時間ですので、いただいて、正副で調整をします。","voiceIndex":83,"id":"exchange-016"},{"speaker":"大沢委員","kind":"質問・要望","question":"このお二人の説明によって、私はちょっとあちこちでわからなくなってしまいましたので、絞って委員会を進めていただきたいと思いますし、ここの八潮地区の最初は、これは八潮かなと構えていたら、急に立会川の壁面緑化だ、目黒川の壁面緑化だというお話も伺いましたし、水とみどりのほうのしながわ水族館のことで説明をいただきましたけれども、上の課長の説明と、下段の２人の課長にお話しいただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう形で、付託された内容をもう一度理事者のほうで、確認していただいて、調整されていただきたいと思っています。要望ですが、八潮地区をする上で、やはり品川区にとって、この八潮地区というのはどうなのかという視点でやっていかなければいけないのかなと思っているんですね。ですから、その地域の方たちの要望というものも必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"いろいろ意見を伺うなんていう話になると、７月から平成２０年６月までの予定でやられるということと思うんだけれども、これはまちをどういうふうにしていきましょうかという、地域の方々のご要望、それからどういう八潮であろうということを検討されていく話ですけれども、先ほど言った地区計画の話、地区計画にしていこうということを考えていく上でいくと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ところが、全国に例がないということだから、非常に壁があるのであれば、もちろん行政側は行政として、いろいろ交渉されるだろうけれども、議会としても、そういう例えば対応をして、区としても、議会からも八潮地区のことを考えれば、これは特別委員会があるわけですから、今の網を外してくれというような、そういう議会側の動きも、八潮地域のことを考えれば必要だと、私は個人的には思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":31279,"voices":94}},{"id":"h19-20070625-6","meetingId":"h19-cm06","date":"2007年6月25日","dateIso":"2007-06-25","committee":"区民委員会","time":"午前１０時０４分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第５０号議案 品川区特別区税条例の一部を改正する条例","agenda":"第５０号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"どうして１年延長するのかという理由を聞きたい。これは区で実施するわけですから、その際に区の考え方というのをお伺いしたい。この２つの定率減税が１年延長されることによっての減税額というのは、大体区としては幾らぐらいと見積もっているのかなということをまずお伺いしたいと思います。","respondent":"武内税務課長","answer":"それとあと、このような税率とすることによって、どのように区のほうに影響が出るかというところですけれども、上場株式の区民税１.８％、本来は３％ですけれども、その水準については、あくまでも株がどのように動くかによって。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"やっぱりお金持ちの方にはものすごい減税があるわけですけれども、そういう減税措置だと思うんですけれども、区としては今回の減税の１年間の延長によって、どのような方が恩恵を受けると考えておられるんですか。","respondent":"武内税務課長","answer":"人によっても５万円、１０万円だとかという、楽しみながら株をやる方もいらっしゃるわけですから、その辺はこういう社会のシステムという中で、経済の活性化という部分では、私どもがそれをコメントするような立場ではないのかなと考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"この添付されています資料の付則１４条の４のところです。新と旧という形になっている中で、「条約適用利子等および」のところで、アンダーライン部分でもともと入っていたものがなくなっている部分ですね。この辺の違いといいますか、わかればいいなと思ってお聞きいたします。","respondent":"武内税務課長","answer":"そういう中で、その税のかけかたとしては、組合ができているとしても、組合から税をとるというのではなくて、それぞれ組合の中でも、個人の方に税がかかるわけですけれども、そういった意味で、今回は投資事業組合ということを中心の言葉として改正しておりますので。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼副委員長","kind":"質問","question":"４のところ、上場株式等譲渡益に係る１０％の特例のところなんですけれども、ちょっと私も税金のことはなかなか難しくてよくわからなくて、ある本を読んだら、配当とか譲渡所得の税率が１０％というのは、非常に低いというか、金持ち減税の批判を浴びているアメリカでさえも、地方税を含めると、２０％以上の税率なのに、この株に関して１０％というのは、すごく金持ち優遇ではないかと言われているのと。","respondent":"武内税務課長、田中区民生活事業部長","answer":"その辺は個人の考え方によって、そういう自分の持っているものをさらに増やそうという気持ちで、株をやる方、あるいはそのまま、同時にやっとためたお金を銀行に預けて、将来に蓄えようという。国の税制改正に基づいた対応ですので、これを品川区が株式譲渡益課税を本則どおりやろうとかいうことを規定することはできませんので、そこはまずご理解いただきたいと思います。","voiceIndex":12,"id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"景気は上向きだと思うんですけれども、この間、テレビやなんかでもまたいろいろなところで景気が上向いているという人は、あくまでも平均的なところでとっている。最も身近なところの行政としては、やはりそこで意見を言っていかなければ、今の状況は本当に改善されないというところなんですけれども、そこは揺るがないのでしょうか、もう一度そこだけお伺いいたします。","respondent":"田中区民生活事業部長","answer":"税の部分は細かい部分が非常に多いですから、その部分について、窓口等では的確にご説明するようにやりますが、これについて、今年度の税制改正についてどうしようかみたいな話は、私どもとして、個々にやるつもりは当然ありません。","voiceIndex":15,"id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"国の税制改正で、その中身に入ってきますと、非常に難しい。いろいろな中の突っ込みというのが非常に難しいような気がするんですけど、今回の改正によりまして、品川区としてはどれくらい税収を見込まれているか。その辺をお伺いします。","respondent":"武内税務課長","answer":"そういった中で、全体の中で、特にこの部分についてという部分については、上場株式の譲渡に対するということは先ほどご説明させていただきましたけれども、本則の本来の税率からすると、２億５,０００万円ぐらいのマイナスになるのではないかというふうに考えてあります。","voiceIndex":17,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"やっぱり、いわゆるマクロ経済をどうするかという話はやっぱり国ですることで、今回、個人のほうでは、主に家庭には一番恩恵がある定率減税、それが今回なくなってしまうということで、でも一方で、株式をやられる方に関しては、期限としては１年延長ということで、トータルで見ると、大きいかなという話だと思うんですけれども、やっぱり、率直に言って。","respondent":"武内税務課長","answer":"それと、定率減税を廃止していく中で、一方ではそういう株の税率をそのままにしていくという部分ですけれども、定率減税というのは、もともと平成１１年の景気がどん底と言われる時期に、景気回復として行われたものでありまして、再三お話があったとおり、この間。","voiceIndex":20,"id":"exchange-007"},{"speaker":"稲川委員","kind":"質問","question":"素朴な質問なんですけれども、税に対する庶民の皆様の怒りや憤りというのは、税務課にはどれくらい寄せられているんですか。単純な質問ですが。","respondent":"武内税務課長","answer":"怒りという部分については、確かに何で去年とこんなに違うんだということをあらわにされる方もいらっしゃいますけれども、この辺の趣旨を住民に説明して、ご理解いただくということで、区民の方には対応をしています。","voiceIndex":23,"id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"６と７のところで、単純な質問で申しわけないんですが、６のところの対象となるところがどういうところなのかと、あと、この内容というか、中身を教えていただきたいのと、７に対してもどういった方のためのものなのかということと、控除の内容をちょっとわかりやすく教えていただけたらと思います。","respondent":"武内税務課長","answer":"６番目の条約適用配当等に対する軽減税率というのは、昨年２月に、日本とイギリスが租税条約というのを結ぶ中で、株の取引の活性化をするということで、そういう投資家を誘発するための政策として行われておりました。","voiceIndex":25,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この議案に対して賛成です。地方税法、租税特別措置法の改正に伴う改正で、区として当然の対応だと思います。この議案に対して賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-010"},{"speaker":"安藤委員","kind":"意見","question":"やっぱり格差の広がりが指摘されていますけれども、社会問題になって、やっぱりますます税収減というふうになる税制が盛り込まれているので、賛成するわけにいかないということと、やっぱり景気の話がありますけれども、政府の税調でも、今回５年間の時限措置だったわけですけれども、当初、税調でも株価が回復した現在、続ける理由はないという意見も出されていたんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-011"},{"speaker":"渡部委員","kind":"意見","question":"私も賛成をします。半年前まで企業人としてサラリーマンをやっておりました。やはりこの景気が緩やかな回復と言われていますが、実感として、勤めていて回復しているとは思えない。その株を取得をしやすくする、企業が株を還流しやすくするという部分でも、これに関しては私は賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-012"}]},{"id":"topic-02","title":"の２番目に移ります。請願・陳情審査","agenda":"の２番目に移ります。請願・陳情審査","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"請願の件について聞きたいんですが、請願の紹介議員はこの中には当然いないですし、それからこの請願自体も問題ないということで、十分承知した上でなんですけれども、同じ様式のパターンで９件の請願が出ているということ、同じ会派の方にお聞きするような形になると思うんですが、我々でしたら、同じ内容でこれでしたら、１件にまとめられる。なぜ、９件になさらなければいけなかったか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もちろん、それはわかりますけど、なぜかなということが、中で話が出ているかどうかということをお聞きしたかったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問・要望","question":"６２％の方が回答している。所得金額は２００万円未満が増大。そういった状況なわけですね。やっぱり今回の趣旨にありますように、今回の増税が区民の暮らしというのを圧迫しているとお考えなのかどうか、お考えじゃないのかなということをお伺いしたいと思います。","respondent":"武内税務課長","answer":"この税源移譲によって、区民のどの程度の人数に影響しているのかというご質問だと思うんですけれども、この図を見ていただけるとわかるように、従来、住民税が昨年まで５％の方につきましては１０％になっているわけですから。","voiceIndex":45,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"川崎市だけじゃなくて、名古屋市、京都市でもありますけれども、あるんですよね。そういう、今、講じていただいた軽減策以外に、川崎市ほかのようにもっと踏み込んだ、何かこの請願にこたえるそういった軽減策をつくるべきじゃないかと思うんですけれども、そういう実施する用意というのがあるんでしょうかということで３点です。","respondent":"武内税務課長","answer":"減免制度の創設というのは、公平の原則からいって、国の法律の中で対応をするべきものなのかなというふうに考えております。","voiceIndex":47,"id":"exchange-016"},{"speaker":"渡辺委員","kind":"質問","question":"ただし、その方が情報のすべてを把握しているわけじゃないかと思うので、そういったことで問い合わせをする。数値にはできないかと思うんですが、各担当の方の報告や、課長からの感触も踏まえて、対応した結果どうだったというのをちょっと参考のため、お聞きしたいと思います。","respondent":"武内税務課長","answer":"もちろん、法制度の中の改正ということで説明していますので、ほとんどの方は納得していただいて、ご理解いただいているというふうに考えております。","voiceIndex":49,"id":"exchange-017"},{"speaker":"渡辺委員","kind":"確認","question":"よくわかりました。今、数字だけがひとり歩きしますと、問い合わせというのは悪い問い合わせというんですか、苦情というくくりでだけではないと、思いますので、問い合わせがあって、それに対して答えた数字が、私は７００なり何なりだと理解してよろしいかと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問","question":"今、渡辺委員からの質問にあった、いろいろ問い合わせがあったというのは、問い合わせをいただいている方って、やはり個人事業主の方が多いんですか。特にそういう方が多いというわけではないんでしょうか。","respondent":"武内税務課長","answer":"そういった意味では、もちろん会社にお勤めの方については５月１４日に企業、会社を通じて納税通知書を発布しているわけですけれども、その問い合わせは６月の普通徴収、今言った個人事業主の方等に発布してからの問い合わせの件数ですから。","voiceIndex":52,"id":"exchange-019"},{"speaker":"渡部委員","kind":"質問","question":"それに対して、やはり後から出てきている住民税ですから、区のほうに「おい、何でこんなに取るんだ」という話が挙がってくると思うんですが、それが次の確定申告でまた減免されるのは間違いないわけです。次から普通にとられるから、また若干上がるというときの説明までを、どこかでやっておかないと、また次、どこかで文句が出てくるんじゃないかなと思う部分があるんですが、いかがでしょうか。","respondent":"武内税務課長","answer":"委員がおっしゃるとおり、そういう個人事業主の方につきましては、青色申告会あるいは納税貯蓄組合等に参加している方も大勢いらっしゃいますので、そういう組織を通じて十二分にこういう救済措置についてご理解いただけるような準備をしていきたいと考えています。","voiceIndex":54,"id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"ぜひ各種団体等ですとか、私の近いところで、例えば塾の経営者というのがおりまして、そうなるとなかなか情報というのは入ってこなくて、「うわー、上がっちゃった」と。なおかつ７月２日の納入期限が来て、まだお金が準備できないというようなこともありまして、きついなという意見も確かにあったのも事実ですし、皆さんがきついとは思っているんでしょう。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-021"},{"speaker":"山路委員","kind":"質問","question":"この税改正に対して、非常になれていないということと、十分にいろいろなお話はお伺いするんですけど、まずこの請願項目の１番の住民税の増税をもとに戻すための措置をとってくださいということなんですが、定率減税８年間の間というのは、非常にこの定率減税は年金の一部に当てたとか、どん底から目には見えてきませんけど、景気のやや上向きという、大きな社会状況全体像もあると思うんです。","respondent":"武内税務課長","answer":"それと同時に、あわせて皆さんが加入しております国民年金の基礎年金の国庫負担金を税金で賄うということで、平成２１年度までに３分の１から２分の１に段階的に引き上げましょうというものの財源として、平成１７年度に縮減した分の１,１００億円。","voiceIndex":57,"id":"exchange-022"},{"speaker":"山路委員","kind":"質問","question":"ちょっと請願項目に戻ります。定率減税の廃止になって、もとに戻したわけですよね。現実は違うわけですよね。増税じゃないわけですね。もとに戻ったわけですね。低所得者の方が一部増税になったという、ちょっと質問が悪いですけど、増税じゃないのに、増税分と書いてありますから、もとに戻す。この辺のとらえ方を説明してくださいますか。","respondent":"武内税務課長","answer":"そういった意味で、どのぐらい定率減税を廃止することによって、低所得者の方が影響するのかという数字については、ちょっと把握できないんですけれども、私どもとしては、平成１８年度に縮減したときに、１７万５,０００人の方が所得割というものがかかっていますので。","voiceIndex":59,"id":"exchange-023"},{"speaker":"山路委員","kind":"質問","question":"ここをどう判断していいかという部分で迷うんですけど、ずっと事実関係を追求していきますと、理解されている、誤解されている、社会保険庁の問題がイメージとして、税金とかいろいろなものにあるかもわかりませんけど、現実違うんですね。増税されていない中で、住民税の減税とはまず不可能なことでしょう、そこは。この請願項目に沿って、ちょっとお伺いしているんですけど。","respondent":"武内税務課長","answer":"現状においては、減税をするということは不可能と考えています。","voiceIndex":61,"id":"exchange-024"},{"speaker":"山路委員","kind":"質問","question":"請願項目の文章を理解するためにお伺いしているわけなんですね。その２番目の国民健康保険料を下げてくださいということで、所得が少ない人に国民健康保険料の減免を実施してくださいということで、要はこれは品川区だけで単独でできるものか。そこで、税が上がったら、国保も上がるかということになるんですけど、その辺の今回の税制改正とのことについて、ご説明をちょっとしていただけますでしょうか。","respondent":"原国保年金課長","answer":"今年につきましても、そういった形で、２３区でこれらに伴う影響をいろいろ考えながら、先ほど説明したような形で、本来の住民税率１０％ですけれども、それを２.５％控除する形で、保険料算定ということで軽減措置を２３区独自で実施しているものです。","voiceIndex":63,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"２つ聞きたいんです。額の増額がほかにどういうところに影響して、結果としてどこの負担増につながるのかという、その要素をちょっと考えられる限り教えていただきたいのと、もう一つは、窓口の話に戻って恐縮なんですが、その生活実態を問い合わせの中で、絶対区民の方から訴えられているはずなんですね。その声を伺った結果、考えている区民の生活実態というのをちょっとお伺いしたいと思います。","respondent":"武内税務課長","answer":"住民税のこういう改正に伴いまして、それにかかわる部分ということは、まず今、国民健康保険料、それから介護保険料、また高齢者にありますシルバーパスも影響するのかなと思うんです。それから、都営住宅に入居している方も、一部そういう関連もあるのかなと考えます。","voiceIndex":67,"id":"exchange-026"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"私はサラリーマンのところも増税になっているし、年金暮らしのご夫婦もひとり暮らしの方も、総体的に住民税とか、国保、介護保険料とか連動した値上げになっているわけなんですけれども、その辺のご説明もちゃんとしていただきたいなと思うのと、ぜひトータルで見てほしいというところでは、その辺の影響をどう感じているのかなというところを実際窓口や電話で対応されているというところにおいては。","respondent":"武内税務課長","answer":"高齢者に対する非課税措置というお話が出ましたので、これにつきましては、平成１８年度の税制改正の中で、お話ししていますので、今回、請願が出ているのは、昨年の税制改正についての請願というふうにとらえましたので、あえて、ここでご説明をしておりません。","voiceIndex":69,"id":"exchange-027"},{"speaker":"飯沼副委員長","kind":"提案","question":"私が伺った国保が３倍になった方なんかは、住民税が非課税であったのが、所得が増えないのに税のとり方が変わったがために、ある意味では年金で所得が減っているのに、住民税非課税が課税になった。そのことで国保が３倍にも上がっちゃった人もいるわけですよ。去年ですよ。払えない人への減免制度を拡大していくという姿勢を持っていただきたいのですが、いかがでしょうか。","respondent":"田中区民生活事業部長","answer":"その結果、保険に入らない何千万という世帯がアメリカの場合だと発生するとかいうような話がありますので、とても大切な国民健康保険の制度だと思いますので、持続可能な形で２３区も、国も考えてやってきておりますので、ぜひその辺のところをご理解いただきたいと思います。","voiceIndex":71,"id":"exchange-028"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"ちょっと国保のことを伺います。今、田中区民生活事業部長の言葉で持続可能な制度、もちろんそうですね。滞納のところで伺いたいのですが、払わないのではなくて、払えない人たちが多分多いのではないかと思うあたりで、私は今ある減免措置ではとても不十分。払えない人のための救済策が大事であると思うんですが、その点もお伺いします。","respondent":"原国保年金課長","answer":"そういった意味では、この辺の少子高齢化の中で、高齢医療といった中で、非常に医療費も一方で上がっていますし、生存率というんですか、長く生きられる、世界一ということで、これは今の日本の社会の医療制度が充実していることによって。","voiceIndex":73,"id":"exchange-029"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"「保険者は特別な理由がある被保険者で、保険医療機関等に第４２条又は前条の規定による一部負担金を支払うことが困難であると認められるものに対し、次の各号の措置を採ることができる」ということで、３点書かれていて、「一部負担金を減額すること」「一部負担金の支払を免除すること」「保険医療機関等に対する支払にかえて、一部負担金を直接に徴収することとし、その徴収を猶予すること」と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-030"},{"speaker":"山路委員","kind":"意見","question":"結論を出すということですけれども、社会保障制度を持続可能な制度へということで、今回の改正は非常に重要な点で、救済措置というのは国でも東京都でも、いろいろ議論されておりますけれども、これはとらなきゃいけない。そういうところから考えますと、この請願の内容に関しましては賛成できない。ですので、決をとっていただいて結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"私はかなり区民の皆さんの実態を考えて、非常に重要な請願だと思いますので、この当委員会１回だけではちょっと議論し尽くせないというか、深められないと、すごく実感しておりますので、継続をしたいところなんですが、内容を見ると、緊急性がありますので、やはりどうなるかわかりませんけれども、採択をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"違います。内容的にはすごく緊急性を求められることですので、本日、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"自民党としては、態度としては不採択で結構です。そこのところ、住民税だけ減税すると、すべてに減税になってくるわけですね。それから国民健康保険に関しても、先ほどの理事者のご答弁にありましたように、医療費をもとにしての国保制度上の中で、２３区同率でやっている、また所得が少ない方の減免措置は既にある程度やっていらっしゃる部分がありますので、その辺も区としては行っているということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-034"},{"speaker":"稲川委員","kind":"質問","question":"庶民、庶民と言うけど、それはまた話がずれちゃいますけど、庶民というのはどういうことなんだという話で、例えばどこかの量販店で買い物をしている人たちが庶民なのかどうなのかという話だってあるじゃないですか。庶民だから、庶民イコール税金が払えない。ネットカフェ難民という話はありましたけれども、その話だって、ぜいたくじゃないですか、お金を払ってそこにいられるんだから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私はぜひ本請願には、地方自治体の本旨に照らして、すぐにでもこたえるべきだと思いますので、この請願は採択するべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"私も個人的にこれは不採択だと考えております。やはり税金を納めるのは、私たちの義務でもありますし、そのために仕事を当然している。確かに地域の方々から、この件に関する声が多いのも事実です。これは実際、国で決まったことであって、動いているわけですから、何とかこれは自分自身も地域の広報マンになって頑張っていきたいと思います。","respondent":"川西委員長","answer":"大変遅くなって申しわけありませんが、それでは平成１９年請願第９号から１５号まで、ならびに第１８号および１９号の９件につきまして、採択とすることに賛成の方の挙手をお願いいたします。","voiceIndex":94,"id":"exchange-037"},{"speaker":"川西委員長","kind":"質問・要望","question":"次にその他を行います。私のほうから今定例会の一般質問にかかわる所管質問についてご案内を申し上げます。本件は委員会活動の活性化という観点から、各常任委員会において、当該会期中の一般質問にかかわる当該委員会の所管質問を行うというものです。質問なさりたい委員の方がいらっしゃいましたら、委員長に通告し、翌日理事者に答弁していただくこととしております。以上です。他に何かありますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-038"},{"speaker":"安藤委員","kind":"意見","question":"前回の区民委員会で、国民保護計画の報告がありましたけれども、それについて、ぜひ明日、その他あたりでやれないかなと。いつやるのか、それを委員長、副委員長のお考えもあるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2007-01-01&TermEnd=2007-12-31"}],"sourceMeta":{"pages":0,"characters":35467,"voices":99}}]);
